    function uid(prefix = "item") {
      if (globalThis.crypto && crypto.randomUUID) return `${prefix}-${crypto.randomUUID()}`;
      return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    }

    function clamp(value, min, max) {
      return Math.min(max, Math.max(min, Number(value) || 0));
    }

	    function escapeHtml(value) {
      return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
	    }

	    function safeLinkUrl(value) {
	      const url = String(value || "").trim();
	      return !url || /^(?:javascript|data):/i.test(url) ? "" : url;
	    }

    function readJson(value, fallback) {
      try { return value ? JSON.parse(value) : fallback; }
      catch (_) { return fallback; }
    }

    function clone(value) {
      return JSON.parse(JSON.stringify(value));
    }

    function hotspotStyle(index) {
      const length = HOTSPOT_STYLES.length;
      const normalizedIndex = ((Number(index) || 0) % length + length) % length;
      return HOTSPOT_STYLES[normalizedIndex];
    }

    function contentsNumberStyle(index) {
      const style = hotspotStyle(index - 1);
      const ink = style.name === "mauve" ? "#ffffff" : "#000000";
      return `--contents-number-color:${style.color};--contents-number-ink:${ink}`;
    }

    function hotspotSlotIndex(id, slide = currentSlide()) {
      return slide?.hotspots?.findIndex((item) => item.id === id) ?? -1;
    }

    function slugify(value) {
      return String(value || "")
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 80);
    }

    function detectMediaType(url) {
      const value = String(url || "");
      return Object.entries(MEDIA_TYPES).find(([, pattern]) => pattern.test(value))?.[0] || "image";
    }

    function mediaDisplayFilename(value) {
      const original = String(value || "").trim();
      if (!original) return "";
      try {
        const url = new URL(original, location.href);
        return decodeURIComponent(url.pathname.split("/").filter(Boolean).pop() || original);
      } catch (_) {
        return decodeURIComponent(original.split(/[?#]/)[0].split("/").pop() || original);
      }
    }

    function builtInAnnotationFilename(value) {
      const original = String(value || "").trim();
      if (!original || /^data:/i.test(original)) return "";
      try {
        const url = new URL(original, location.href);
        const marker = "/images/tutorial-annotations/";
        const markerIndex = url.pathname.indexOf(marker);
        if (markerIndex < 0) return "";
        const encodedFilename = url.pathname.slice(markerIndex + marker.length);
        return decodeURIComponent(encodedFilename);
      } catch (_) {
        return "";
      }
    }

    function canonicalAnnotationFilename(value) {
      const path = String(value || "").replace(/^\/+|\/+$/g, "");
      const parts = path.split("/").filter(Boolean);
      const filename = parts.pop() || "";
      parts.push(filename.toLowerCase() === "audio-annotation.png"
        ? "play-audio-annotation.png"
        : filename);
      return parts.join("/");
    }

    function encodedAnnotationFilename(value) {
      return canonicalAnnotationFilename(value)
        .split("/")
        .map((part) => encodeURIComponent(part))
        .join("/");
    }

    function annotationAssetUrl(filename) {
      return `${ANNOTATION_ASSET_ROOT}${encodedAnnotationFilename(filename)}?v=${ANNOTATION_ASSET_VERSION}`;
    }

    function publicAnnotationAssetUrl(filename) {
      return `${PUBLIC_ANNOTATION_ASSET_ROOT}${encodedAnnotationFilename(filename)}?v=${ANNOTATION_ASSET_VERSION}`;
    }

    function resolveAnnotationAssetSrc(value) {
      const filename = builtInAnnotationFilename(value);
      return filename ? annotationAssetUrl(filename) : String(value || "");
    }

    function normalizeShapeAssetUrl(name, value) {
      const filename = builtInAnnotationFilename(value)
        || (String(name || "").toLowerCase() === "audio annotation" ? "play-audio-annotation.png" : "");
      return filename ? publicAnnotationAssetUrl(filename) : encodeURI(String(value || ""));
    }

    function renderAnnotationAssetImage(src, label, loading = "eager") {
      const safeLabel = String(label || "Annotation");
      return `<span class="annotation-asset-fallback" aria-hidden="true">${escapeHtml(safeLabel)}</span><img src="${escapeHtml(resolveAnnotationAssetSrc(src))}" alt="${escapeHtml(safeLabel)}" loading="${loading}" onload="this.hidden=false;this.closest('.annotation-asset-frame')?.classList.remove('has-missing-annotation-art')" onerror="this.hidden=true;this.closest('.annotation-asset-frame')?.classList.add('has-missing-annotation-art')">`;
    }

    function normalizeHostedAnnotationUrl(_type, value) {
      // Tamara supplies the final hosted path. Preserve Imgur images and
      // website-hosted audio/video URLs exactly as entered.
      return String(value || "").trim();
    }

