    async function projectApi(path = "", options = {}) {
      const response = await fetch(`${PROJECT_API_ROOT}${path}`, {
        cache: "no-store",
        ...options,
        headers: {
          "Content-Type": "application/json",
          ...(options.headers || {})
        }
      });
      const payload = readJson(await response.text(), {});
      if (!response.ok) throw new Error(payload.error || `The local project connection returned ${response.status}.`);
      return payload;
    }

