    async function confirmProjectNameDialog() {
      const input = root.querySelector("#projectNameInput");
      const name = String(input?.value || "").trim();
      if (!name) {
        input?.setCustomValidity("Enter a draft name.");
        input?.reportValidity();
        return;
      }
      const mode = projectDialogMode;
      closeProjectNameDialog();
      if (mode === "new") await createProject(name);
      if (mode === "rename") await renameCurrentProject(name);
      if (mode === "duplicate") await duplicateCurrentProject(name);
    }

    async function createProject(name) {
      if (projectApiError) {
        showToast(projectApiError);
        return;
      }
      const openedFromBuilder = Boolean(currentProject);
      if (openedFromBuilder) {
        if (!await saveProjectToDiskNow()) {
          showToast("The current draft did not save to disk, so New Draft was stopped.");
          return;
        }
      } else {
        renderProjectLoading("Creating the new draft…");
      }
      try {
        const payload = await projectApi("", {
          method: "POST",
          body: JSON.stringify({ name, state: newProjectTemplate() })
        });
        location.assign(projectUrl(payload.project.id));
      } catch (error) {
        const message = `The draft could not be created: ${error?.message || "save failed"}`;
        if (openedFromBuilder) showToast(message);
        else {
          projectApiError = message;
          renderProjectChooser();
        }
      }
    }

    async function openProject(id) {
      if (!/^project-[a-zA-Z0-9_-]{1,100}$/.test(String(id || ""))) return;
      if (currentProject && id !== PROJECT_ID && !await saveProjectToDiskNow()) {
        const selector = root.querySelector("#projectSelect");
        if (selector) selector.value = PROJECT_ID;
        showToast("The current draft did not save to disk, so switching was stopped.");
        return;
      }
      location.assign(projectUrl(id));
    }

    async function deleteProject(id, name) {
      if (!/^project-[a-zA-Z0-9_-]{1,100}$/.test(String(id || ""))) return;
      const draftName = String(name || "this draft");
      if (!window.confirm(`Delete “${draftName}”?\n\nThis removes the draft from the opening screen.`)) return;
      try {
        await projectApi(`/${encodeURIComponent(id)}/delete`, { method: "POST", body: "{}" });
        projects = projects.filter((project) => project.id !== id);
        renderProjectChooser();
      } catch (error) {
        projectApiError = `Could not delete ${draftName}: ${error?.message || "delete failed"}`;
        renderProjectChooser();
      }
    }

    async function renameCurrentProject(name) {
      if (!currentProject) return;
      if (name.trim() === currentProject.name) return;
      try {
        const payload = await projectApi(`/${encodeURIComponent(PROJECT_ID)}`, {
          method: "PUT",
          body: JSON.stringify({ name })
        });
        currentProject = payload.project;
        projects = projects.map((project) => project.id === PROJECT_ID
          ? { id: currentProject.id, name: currentProject.name, createdAt: currentProject.createdAt, updatedAt: currentProject.updatedAt }
          : project);
        render();
        showToast(`Renamed this draft to ${currentProject.name}.`);
      } catch (error) {
        showToast(`The draft could not be renamed: ${error?.message || "save failed"}`);
      }
    }

    async function duplicateCurrentProject(name) {
      if (!currentProject) return;
      if (!await saveProjectToDiskNow()) {
        showToast("The current draft did not save to disk, so Copy was stopped.");
        return;
      }
      try {
        const payload = await projectApi("", {
          method: "POST",
          body: JSON.stringify({ name, state: clone(state) })
        });
        location.assign(projectUrl(payload.project.id));
      } catch (error) {
        showToast(`The draft could not be duplicated: ${error?.message || "save failed"}`);
      }
