    function normalizeState() {
      state.meta ||= {};
	      state.meta.version = 3;
	      state.meta.touched ||= {};
	      state.meta.pageType = state.meta.pageType === "demo" ? "demo" : "tutorial";
	      state.meta.group = String(state.meta.group || "");
	      state.meta.primaryActionLabel = String(state.meta.primaryActionLabel || (state.meta.pageType === "demo" ? "Open Tutorial" : "Open Tool"));
	      state.meta.primaryActionUrl = String(state.meta.primaryActionUrl || "");
	      state.meta.relatedCalloutEnabled = Boolean(state.meta.relatedCalloutEnabled);
	      state.meta.relatedCalloutTitle = String(state.meta.relatedCalloutTitle || "");
	      state.meta.relatedCalloutText = String(state.meta.relatedCalloutText || "");
	      state.meta.relatedCalloutLabel = String(state.meta.relatedCalloutLabel || "");
	      state.meta.relatedCalloutUrl = String(state.meta.relatedCalloutUrl || "");
      state.meta.demoBuilderVersion = 1;
      state.meta.demoDefaultDuration = DEMO_DEFAULT_DURATION;
      delete state.meta.status;
      delete state.meta.touched.status;
      state.tutorial ||= { title: "TUTORIAL TITLE", slides: [] };
      state.tutorial.title = String(state.tutorial.title || "TUTORIAL TITLE").toUpperCase();
      state.tutorial.slides = Array.isArray(state.tutorial.slides) ? state.tutorial.slides : [];
      if (!state.tutorial.slides.length || state.tutorial.slides[0].kind !== "cover") {
        state.tutorial.slides.unshift(createSlide("cover"));
      }
      state.tutorial.slides = state.tutorial.slides.map((slide, index) => normalizeSlide(slide, index));
      state.ui ||= {};
      state.ui.slideIndex = clamp(state.ui.slideIndex, 0, state.tutorial.slides.length - 1);
      state.ui.contentsOpen = Boolean(state.ui.contentsOpen);
      state.ui.videoModalId ||= null;
    }

    function applyVisualRefinements() {
      const appliedVersion = Number(state.meta.visualRefinementVersion) || 0;
      if (appliedVersion >= VISUAL_REFINEMENT_VERSION) return;
      state.tutorial.slides.forEach((slide) => {
        if (slide.media?.type !== "image" || slide.media.fit !== "match" || !slide.media.url) return;
        slide.media.x = 0;
        slide.media.y = 0;
        slide.media.scale = 1;
      });
      state.meta.visualRefinementVersion = VISUAL_REFINEMENT_VERSION;
      if (MODE === "builder") saveStateNow();
    }

    function applyCoverAutoFit() {
      const appliedVersion = Number(state.meta.coverAutoFitVersion) || 0;
      if (appliedVersion >= COVER_AUTO_FIT_VERSION) return;
      const cover = state.tutorial.slides[0];
      if (cover?.media?.url && ["image", "gif"].includes(cover.media.type)) {
        cover.media.fit = "match";
        cover.media.x = 0;
        cover.media.y = 0;
        cover.media.scale = 1;
      }
      state.meta.coverAutoFitVersion = COVER_AUTO_FIT_VERSION;
      if (MODE === "builder") saveStateNow();
    }

    function applyFixedVideoFrame() {
      const appliedVersion = Number(state.meta.fixedVideoFrameVersion) || 0;
      if (appliedVersion >= FIXED_VIDEO_FRAME_VERSION) return;
      state.tutorial.slides.forEach((slide) => {
        if (slide.media?.fit === "match") slide.media.fit = "contain";
      });
      state.meta.fixedVideoFrameVersion = FIXED_VIDEO_FRAME_VERSION;
      if (MODE === "builder") saveStateNow();
    }

    function normalizeSlide(slide, index) {
      const kind = index === 0
        ? "cover"
        : slide?.kind === "video" ? "video" : slide?.kind === "scroll" ? "scroll" : "image";
      const description = String(slide?.description || (kind === "cover" ? "Tutorial description." : ""));
      const savedManualDuration = slide?.demo?.manualDuration;
      const manualDuration = savedManualDuration !== null && savedManualDuration !== undefined && savedManualDuration !== ""
        ? clamp(Number(savedManualDuration), DEMO_MIN_DURATION, DEMO_MAX_DURATION)
        : slide?.demo?.timing === "manual"
          ? clamp(Number(slide?.demo?.duration) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION)
          : null;
      const media = {
        url: String(slide?.media?.url || ""),
        type: kind === "video" ? "video" : kind === "scroll" ? "image" : detectMediaType(slide?.media?.url),
        fit: ["match", "contain", "cover"].includes(slide?.media?.fit) ? slide.media.fit : "contain",
        matte: normalizeSiteColor(slide?.media?.matte, kind === "cover" ? "#fbeaf9" : "#ffffff"),
        x: clamp(slide?.media?.x, -40, 40),
        y: clamp(slide?.media?.y, -40, 40),
        scale: clamp(slide?.media?.scale || 1, MEDIA_MIN_SCALE, MEDIA_MAX_SCALE),
        naturalWidth: Math.max(0, Math.round(Number(slide?.media?.naturalWidth) || 0)),
        naturalHeight: Math.max(0, Math.round(Number(slide?.media?.naturalHeight) || 0))
      };
      const slideContext = { kind, media };
      return {
        id: slide?.id || uid(kind),
        richText: slide?.richText && typeof slide.richText === "object" ? clone(slide.richText) : {},
        kind,
        scrollViewportWidth: kind === "scroll"
          ? clamp(slide?.scrollViewportWidth ?? SCROLL_DEFAULT_VIEWPORT_WIDTH, SCROLL_VIEWPORT_MIN_WIDTH, 100)
          : 100,
        scrollHeaderHeight: kind === "scroll"
          ? clamp(slide?.scrollHeaderHeight ?? SCROLL_DEFAULT_HEADER_HEIGHT, 0, SCROLL_MAX_HEADER_HEIGHT)
          : 0,
        browserUrl: String(slide?.browserUrl || ""),
        gptName: String(slide?.gptName || ""),
        title: String(slide?.title || (kind === "cover" ? "TUTORIAL SUBTITLE" : kind === "video" ? "VIDEO PAGE" : kind === "scroll" ? "SCROLL PAGE" : "SLIDE TITLE")),
        description: normalizeMixedBodyValue(description, slide?.descriptionListStyle),
        descriptionListStyle: "",
        media,
        demo: {
          timing: manualDuration !== null
            ? "manual"
            : String(slide?.demo?.audioUrl || "").trim() ? "audio" : "default",
          manualDuration,
          duration: clamp(Number(slide?.demo?.duration) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION),
          audioUrl: String(slide?.demo?.audioUrl || "")
        },
        hotspots: kind !== "video" && Array.isArray(slide?.hotspots)
          ? slide.hotspots.map((item, hotspotIndex) => fitStageObjectBounds(normalizeHotspot(item, hotspotIndex, slideContext), slideContext))
          : [],
        annotations: Array.isArray(slide?.annotations)
          ? slide.annotations.map((item, annotationIndex) => fitStageObjectBounds(normalizeAnnotation(item, annotationIndex, slideContext), slideContext))
          : []
      };
    }

    function normalizeHotspot(item, index, slide = currentSlide()) {
      const hasPopupX = item?.popupX !== null && item?.popupX !== undefined && item?.popupX !== "" && Number.isFinite(Number(item.popupX));
      const hasPopupY = item?.popupY !== null && item?.popupY !== undefined && item?.popupY !== "" && Number.isFinite(Number(item.popupY));
      const hasPopupW = item?.popupW !== null && item?.popupW !== undefined && item?.popupW !== "" && Number.isFinite(Number(item.popupW));
      const hasPopupH = item?.popupH !== null && item?.popupH !== undefined && item?.popupH !== "" && Number.isFinite(Number(item.popupH));
      return {
        id: item?.id || uid("hotspot"),
        title: String(item?.title || `HOTSPOT ${index + 1}`),
        autoTitle: typeof item?.autoTitle === "boolean"
          ? item.autoTitle
          : /^HOTSPOT\s+\d+$/i.test(String(item?.title || `HOTSPOT ${index + 1}`).trim()),
        body: normalizeMixedBodyValue(String(item?.body || ""), item?.bodyListStyle),
        bodyListStyle: "",
        color: hotspotStyle(index).color,
        x: clamp(item?.x ?? 50, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION),
        y: clamp(item?.y ?? 42, STAGE_OBJECT_MIN_POSITION, stageVerticalPositionMax(slide)),
        w: clamp(item?.w ?? HOTSPOT_DEFAULT_WIDTH, 5, 90),
        h: clamp(item?.h ?? HOTSPOT_DEFAULT_HEIGHT, 4, 90),
        z: Number.isFinite(item?.z) ? item.z : index + 10,
        opacity: clamp(item?.opacity ?? 1, .1, 1),
        locked: Boolean(item?.locked),
        hotspotGroupId: String(item?.hotspotGroupId || ""),
        rotation: clamp(item?.rotation, -180, 180),
        popupX: hasPopupX && hasPopupY ? clamp(Number(item.popupX), 2, 98) : null,
        popupY: hasPopupX && hasPopupY ? clamp(Number(item.popupY), 2, 98) : null,
        popupW: hasPopupW ? clamp(Number(item.popupW), 12, 92) : null,
        popupH: hasPopupH ? clamp(Number(item.popupH), 10, 92) : null,
        textAlign: item?.textAlign === "center" ? "center" : "left",
        markerStyle: "number-box", imageShadow: Boolean(item?.imageShadow), shadowHeight: clamp(item?.shadowHeight ?? 9, 0, 40)
      };
    }

    function normalizeAnnotation(item, index, slide = currentSlide()) {
      const type = ["shape", "image", "gif", "video", "audio", "link", "text", "slide-intro", "callout", "markup", "cover", "blur", "magnifier", "clip-frame"].includes(item?.type)
        ? item.type : "image";
      const markup = normalizeMarkupKind(item?.markup);
      const textStyle = ["regular", "italic", "underline", "bold", "hand", "impact-label", "impact-label-reversed"].includes(item?.textStyle)
        ? item.textStyle
        : "regular";
      return {
        id: item?.id || uid(type),
        richText: item?.richText && typeof item.richText === "object" ? clone(item.richText) : {},
        type,
        label: String(item?.label || ""),
        src: String(item?.src || ""),
        url: normalizeHostedAnnotationUrl(type, item?.url),
        text: String(item?.text || (type === "text" ? "new note" : "")),
        introTitle: String(item?.introTitle || (type === "slide-intro" ? "SLIDE INTRODUCTION" : "")),
        introBody: normalizeMixedBodyValue(String(item?.introBody || (type === "slide-intro" ? "Add the introductory text for this slide." : "")), item?.introBodyListStyle),
        introBodyListStyle: "",
        introAlign: item?.introAlign === "center" ? "center" : "left",
        introBodyAlign: item?.introBodyAlign === "left" ? "left" : null,
        introTitleOnly: type === "slide-intro" && Boolean(item?.introTitleOnly),
        calloutTitle: String(item?.calloutTitle || (type === "callout" ? "CALLOUT" : "")),
        calloutBody: normalizeMixedBodyValue(String(item?.calloutBody || (type === "callout" ? "Add callout text." : "")), item?.calloutBodyListStyle),
        calloutBodyListStyle: "",
        calloutAlign: item?.calloutAlign === "center" ? "center" : "left",
        textStyle,
        textColor: normalizeSiteColor(item?.textColor, "#000000"),
        textFontSize: clamp(item?.textFontSize ?? (["hand", "impact-label", "impact-label-reversed"].includes(textStyle) ? 22 : 16), TEXT_FONT_SIZE_MIN, TEXT_FONT_SIZE_MAX),
        textLetterSpacing: clamp(item?.textLetterSpacing ?? 0, -2, 12),
        textLineHeight: clamp(item?.textLineHeight ?? 1.2, TEXT_LINE_HEIGHT_MIN, TEXT_LINE_HEIGHT_MAX),
        textAlign: item?.textAlign === "left" ? "left" : "center",
        manualTextFrame: ["text", "slide-intro", "callout"].includes(type),
        fillColor: /^#[0-9a-f]{6}$/i.test(String(item?.fillColor || "")) ? normalizeSiteColor(item.fillColor, "#ffffff") : "#ffffff",
        markupColor: /^#[0-9a-f]{6}$/i.test(String(item?.markupColor || "")) ? normalizeSiteColor(item.markupColor, "#000000") : "#000000",
        blurStrength: clamp(item?.blurStrength ?? 12, 1, 30),
        markup: type === "markup" ? markup : "",
        strokeWidth: clamp(item?.strokeWidth ?? 5, 1, 10),
        markupCornerRadius: type === "markup" ? clamp(item?.markupCornerRadius ?? 0, 0, 43) : 0,
        markupPoints: type === "markup" && isPathMarkup(markup)
          ? normalizeMarkupPoints(item?.markupPoints, markup)
          : null,
        x: clamp(item?.x ?? 50, STAGE_ANNOTATION_MIN_X, STAGE_ANNOTATION_MAX_X),
        y: clamp(item?.y ?? 48, STAGE_OBJECT_MIN_POSITION, stageVerticalPositionMax(slide)),
        w: clamp(item?.w ?? (type === "audio" ? 30 : type === "slide-intro" ? 38 : type === "callout" ? 34 : type === "magnifier" ? 22 : type === "clip-frame" ? 26 : 18), item?.cropWindow ? 1 : 5, type === "cover" ? 100 : 90),
        h: clamp(item?.h ?? (type === "audio" ? 30 : ["cover", "blur"].includes(type) ? 30 : type === "slide-intro" ? 18 : type === "callout" ? 22 : type === "magnifier" ? 36.6667 : type === "clip-frame" ? 43.3333 : 16), item?.cropWindow ? 1 : 4, 90),
        z: Number.isFinite(item?.z) ? item.z : index + 50,
        opacity: clamp(item?.opacity ?? 1, .1, 1),
        locked: Boolean(item?.locked),
        hotspotGroupId: String(item?.hotspotGroupId || ""),
        objectGroupId: String(item?.objectGroupId || ""),
        rotation: clamp(item?.rotation, -180, 180),
        flipX: type === "shape" && Boolean(item?.flipX),
        imageShadow: Boolean(item?.imageShadow),
        shadowHeight: clamp(item?.shadowHeight ?? 9, 0, 40),
        outlineEnabled: item?.outlineEnabled !== false,
        appearanceColor: item?.appearanceColor === "transparent" || /^#[0-9a-f]{6}$/i.test(item?.appearanceColor || "") ? item.appearanceColor : null,
        cropEnabled: CROPPABLE_ANNOTATION_TYPES.includes(type) && Boolean(item?.cropEnabled),
        cropX: CROPPABLE_ANNOTATION_TYPES.includes(type) ? clamp(item?.cropX ?? 50, 0, 100) : 50,
        cropY: CROPPABLE_ANNOTATION_TYPES.includes(type) ? clamp(item?.cropY ?? 50, 0, 100) : 50,
        cropScale: CROPPABLE_ANNOTATION_TYPES.includes(type) ? clamp(item?.cropScale ?? 1, OVERLAY_CROP_MIN_SCALE, OVERLAY_CROP_MAX_SCALE) : 1,
        cropWindow: CROPPABLE_ANNOTATION_TYPES.includes(type) && item?.cropWindow
          && ["left", "top", "width", "height"].every(key => Number.isFinite(item.cropWindow[key]))
          && item.cropWindow.width > 0 && item.cropWindow.height > 0
          ? { ...item.cropWindow } : null,
        cornerRadius: CROPPABLE_ANNOTATION_TYPES.includes(type) ? clamp(item?.cornerRadius ?? 0, 0, 50) : 0,
        magnification: type === "magnifier" ? clamp(item?.magnification ?? 2, 1.25, 4) : 2,
        magnifierShape: type === "magnifier" && ["square", "rounded", "circle"].includes(item?.magnifierShape)
          ? item.magnifierShape
          : "rounded",
        clipFrameId: type !== "clip-frame" ? String(item?.clipFrameId || "") : "",
        clipFrameShape: type === "clip-frame" && ["straight", "rounded"].includes(item?.clipFrameShape)
          ? item.clipFrameShape
          : "rounded"
      };
    }

    function normalizeMarkupKind(value) {
      const candidate = String(value || "");
      const legacy = {
        line: "line-dotted",
        arrow: "arrow-solid",
        box: "square-solid",
        circle: "circle-solid"
      };
      if (legacy[candidate]) return legacy[candidate];
      const valid = MARKUP_SHAPES.some((shape) => {
        const styles = ["circle", "square"].includes(shape.key) ? CLOSED_MARKUP_STYLES : MARKUP_STYLES;
        return styles.some((style) => candidate === `${shape.key}-${style.key}`);
      }) || ["circle-dotted", "square-dotted"].includes(candidate);
      return valid ? candidate : "line-solid";
    }

    function isPathMarkup(kind) {
      return kind.startsWith("line-") || kind.startsWith("arrow-");
    }

    function isRotatableMarkup(kind) {
      const normalized = normalizeMarkupKind(kind);
      return isPathMarkup(normalized) || normalized.startsWith("circle-") || normalized.startsWith("square-");
    }

    function normalizeMarkupPoints(points, kind) {
      const defaults = kind.startsWith("arrow-")
        ? { start: { x: 8, y: 64 }, curve: { x: 50, y: 36 }, end: { x: 92, y: 50 } }
        : { start: { x: 8, y: 50 }, curve: { x: 50, y: 50 }, end: { x: 92, y: 50 } };
      const point = (value, fallback) => ({
        x: clamp(value?.x ?? fallback.x, 2, 98),
        y: clamp(value?.y ?? fallback.y, 2, 98)
      });
      return {
        start: point(points?.start, defaults.start),
        curve: point(points?.curve, defaults.curve),
        end: point(points?.end, defaults.end)
      };
    }

    function markupLabel(kind) {
      const normalized = normalizeMarkupKind(kind);
      const shape = normalized.split("-")[0];
      const styleLabel = normalized.endsWith("-fill-solid")
        ? "Filled + Solid Border"
        : normalized.endsWith("-fill-dashed")
          ? "Filled + Dashed Border"
          : normalized.endsWith("-dotted")
            ? "Dotted"
            : normalized.endsWith("-fill") ? "Filled" : "Solid";
      return `${styleLabel} ${shape}`;
    }

    function createSlide(kind) {
      return normalizeSlide({
        id: uid(kind),
        kind,
        title: kind === "cover" ? "TUTORIAL SUBTITLE" : kind === "video" ? "VIDEO PAGE" : kind === "scroll" ? "SCROLL PAGE" : "SLIDE TITLE",
        description: kind === "cover" ? "Tutorial description." : kind === "image" ? "Slide description." : "",
        media: { url: "", type: kind === "video" ? "video" : "image", fit: "contain", matte: kind === "cover" ? "#fbeaf9" : "#ffffff", x: 0, y: 0, scale: 1 },
        demo: { timing: "default", manualDuration: null, duration: DEMO_DEFAULT_DURATION, audioUrl: "" },
        hotspots: [],
        annotations: []
      }, kind === "cover" ? 0 : 1);
    }

    function currentSlide() {
      return state.tutorial.slides[state.ui.slideIndex];
    }

    function activeHotspot() {
      return currentSlide()?.hotspots.find((item) => item.id === state.ui.activeHotspotId) || null;
    }

    function slideIntroCard(slide = currentSlide()) {
      return slide?.annotations.find((item) => item.type === "slide-intro") || null;
    }

    function defaultSlideTitle(slide) {
      return slide?.kind === "cover"
        ? "TUTORIAL SUBTITLE"
        : slide?.kind === "video" ? "VIDEO PAGE" : slide?.kind === "scroll" ? "SCROLL PAGE" : "SLIDE TITLE";
    }

    function isSlideIntroState(slide = currentSlide()) {
      return Boolean(slideIntroCard(slide)) && !slide.hotspots.some((item) => item.id === state.ui.activeHotspotId);
    }

    function selectedObject() {
      const slide = currentSlide();
      if (!slide || !state.ui.selectedId) return null;
      return state.ui.selectedKind === "hotspot"
        ? slide.hotspots.find((item) => item.id === state.ui.selectedId)
        : slide.annotations.find((item) => item.id === state.ui.selectedId);
    }

    function selectionKey(kind, id) {
      return kind && id ? `${kind}:${id}` : "";
    }

    function selectionEntry(key) {
      if (typeof key !== "string") return null;
      const separator = key.indexOf(":");
      if (separator < 1) return null;
      const kind = key.slice(0, separator);
      const id = key.slice(separator + 1);
      const slide = currentSlide();
      if (!slide || !["hotspot", "annotation"].includes(kind)) return null;
      const item = kind === "hotspot"
        ? slide.hotspots.find((entry) => entry.id === id)
        : slide.annotations.find((entry) => entry.id === id);
      return item ? { key, kind, id, item } : null;
    }

    function syncObjectSelection() {
      if (MODE !== "builder") {
        multiSelection = [];
        return;
      }
      multiSelection = [...new Set(multiSelection)].filter((key) => selectionEntry(key));
      const primaryKey = selectionKey(state.ui.selectedKind, state.ui.selectedId);
      const primary = selectionEntry(primaryKey);
      if (!primary) {
        const fallback = selectionEntry(multiSelection[multiSelection.length - 1]);
        state.ui.selectedKind = fallback?.kind || null;
        state.ui.selectedId = fallback?.id || null;
        if (!fallback) multiSelection = [];
        return;
      }
      if (!multiSelection.includes(primaryKey)) multiSelection = [primaryKey];
    }

    function selectedObjects() {
      syncObjectSelection();
      return multiSelection.map((key) => selectionEntry(key)).filter(Boolean);
    }

    function hotspotGroupingSelection(selection = selectedObjects()) {
      const hotspots = selection.filter(({ kind }) => kind === "hotspot");
      const annotations = selection.filter(({ kind, item }) => kind === "annotation" && item.type !== "slide-intro");
      return {
        hotspot: hotspots.length === 1 ? hotspots[0].item : null,
        annotations,
        valid: hotspots.length === 1
          && annotations.length > 0
          && hotspots.length + annotations.length === selection.length
      };
    }

    function objectGroupEntriesForItem(item, slide = currentSlide()) {
      const groupId = String(item?.objectGroupId || "");
      if (!groupId || !slide) return [];
      return slide.annotations
        .filter((annotation) => annotation.objectGroupId === groupId)
        .map((annotation) => ({
          key: selectionKey("annotation", annotation.id),
          kind: "annotation",
          id: annotation.id,
          item: annotation
        }));
    }

    function objectGroupingSelection(selection = selectedObjects()) {
      const annotations = selection.filter(({ kind, item }) => kind === "annotation" && item.type !== "slide-intro");
      const onlyAnnotations = annotations.length === selection.length;
      const groupIds = [...new Set(annotations.map(({ item }) => item.objectGroupId).filter(Boolean))];
      const sameExistingGroup = annotations.length >= 2
        && groupIds.length === 1
        && annotations.every(({ item }) => item.objectGroupId === groupIds[0]);
      return {
        annotations,
        valid: onlyAnnotations && annotations.length >= 2,
        grouped: sameExistingGroup,
        groupId: sameExistingGroup ? groupIds[0] : ""
      };
    }

    function clipFrameMembers(frameOrId, slide = currentSlide()) {
      const frameId = typeof frameOrId === "string" ? frameOrId : frameOrId?.id;
      if (!frameId || !slide) return [];
      return slide.annotations.filter((annotation) => annotation.clipFrameId === frameId);
    }

    function clipFrameForMember(annotation, slide = currentSlide()) {
      if (!annotation?.clipFrameId || !slide) return null;
      return slide.annotations.find((item) => item.id === annotation.clipFrameId && item.type === "clip-frame") || null;
    }

    function clipFrameSceneStyle(frame) {
      const width = Math.max(Number(frame?.w) || 1, 1);
      const height = Math.max(Number(frame?.h) || 1, 1);
      const left = (Number(frame?.x) || 0) - width / 2;
      const top = (Number(frame?.y) || 0) - height / 2;
      return `--clip-frame-scene-left:${-left * 100 / width}%;--clip-frame-scene-top:${-top * 100 / height}%;--clip-frame-scene-width:${10000 / width}%;--clip-frame-scene-height:${10000 / height}%`;
    }

    function topLevelAnnotations(slide) {
      const frameIds = new Set(slide.annotations.filter((item) => item.type === "clip-frame").map((item) => item.id));
      return slide.annotations.filter((item) => !item.clipFrameId || !frameIds.has(item.clipFrameId));
    }

    function arrangementEntries(selection = selectedObjects()) {
      const unlockedSelection = selection.filter(({ item }) => !item.locked);
      return { entries: unlockedSelection, usesAllHotspots: false };
    }

    function isObjectSelected(kind, id) {
      return MODE === "builder" && multiSelection.includes(selectionKey(kind, id));
    }

    function mediaBase() {
      const folder = slugify(state.meta.mediaFolder || state.meta.tutorialSlug || "");
      return folder ? `${MEDIA_ROOT}${folder}/` : MEDIA_ROOT;
    }

    function syncMediaUrlSeeds(previousBase) {
      const nextBase = mediaBase();
      if (nextBase === previousBase) return;
      [
        root.querySelector("#mainMediaUrl"),
        ...root.querySelectorAll('.annotation-row input:not(#annotation-link-url)')
      ].filter(Boolean).forEach((input) => {
        if (!input.value || input.value === previousBase) input.value = nextBase;
      });
    }

    function updateMediaDropZone() {
      const zone = root.querySelector("[data-media-drop-zone]");
      if (!zone) return;
      zone.dataset.state = mediaDropState;
      const status = zone.querySelector("[data-media-drop-status]");
      if (status) status.textContent = mediaDropStatusText();
      const connectButton = zone.querySelector('[data-action="connect-media-directory"]');
      const existingButton = zone.querySelector('[data-action="select-existing-media-file"]');
      const copyButton = zone.querySelector('[data-action="copy-new-media-file"]');
      if (connectButton) connectButton.textContent = mediaSiteDirectoryHandle ? "Change Media Website Folder" : "Connect Media Website Folder";
      if (existingButton) existingButton.disabled = false;
      if (copyButton) copyButton.disabled = false;
    }

    function formatMediaFileSize(bytes) {
      const size = Number(bytes) || 0;
      if (size < 1024) return `${size} B`;
      if (size < 1024 ** 2) return `${(size / 1024).toFixed(1)} KB`;
      if (size < 1024 ** 3) return `${(size / 1024 ** 2).toFixed(1)} MB`;
      return `${(size / 1024 ** 3).toFixed(2)} GB`;
    }

    function mediaTypeForFile(file) {
      const mime = String(file?.type || "").toLowerCase();
      if (mime === "image/gif") return "gif";
      if (mime.startsWith("image/")) return "image";
      if (mime.startsWith("video/")) return "video";
      if (mime.startsWith("audio/")) return "audio";
      return Object.entries(MEDIA_TYPES).find(([, pattern]) => pattern.test(file?.name || ""))?.[0] || "";
    }

    function webSafeMediaFilename(filename) {
      const original = String(filename || "media").trim();
      const dot = original.lastIndexOf(".");
      const extension = dot > 0 ? original.slice(dot).toLowerCase().replace(/[^.a-z0-9]/g, "") : "";
      const stem = slugify(dot > 0 ? original.slice(0, dot) : original) || "media";
      return `${stem}${extension}`;
    }

    async function availableMediaFilename(directory, preferredName) {
      const dot = preferredName.lastIndexOf(".");
      const stem = dot > 0 ? preferredName.slice(0, dot) : preferredName;
      const extension = dot > 0 ? preferredName.slice(dot) : "";
      for (let index = 1; index < 1000; index += 1) {
        const candidate = index === 1 ? preferredName : `${stem}-${index}${extension}`;
        try {
          await directory.getFileHandle(candidate);
        } catch (error) {
          if (error?.name === "NotFoundError") return candidate;
          throw error;
        }
      }
      throw new Error("Could not create a unique media filename.");
    }

    function openMediaHandleDatabase() {
      return new Promise((resolve, reject) => {
        const request = indexedDB.open(MEDIA_HANDLE_DB, 1);
        request.onupgradeneeded = () => {
          if (!request.result.objectStoreNames.contains(MEDIA_HANDLE_STORE)) {
            request.result.createObjectStore(MEDIA_HANDLE_STORE);
          }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error("Could not open saved folder access."));
      });
    }

    async function rememberMediaDirectoryHandle(handle, key) {
      const database = await openMediaHandleDatabase();
      try {
        await new Promise((resolve, reject) => {
          const transaction = database.transaction(MEDIA_HANDLE_STORE, "readwrite");
          transaction.objectStore(MEDIA_HANDLE_STORE).put(handle, key);
          transaction.oncomplete = () => resolve();
          transaction.onerror = () => reject(transaction.error || new Error("Could not remember the media website folder."));
          transaction.onabort = () => reject(transaction.error || new Error("Could not remember the media website folder."));
        });
      } finally {
        database.close();
      }
    }

    function rememberMediaSiteDirectory(handle) {
      return rememberMediaDirectoryHandle(handle, MEDIA_HANDLE_KEY);
    }

    async function savedMediaDirectoryHandle(key) {
      const database = await openMediaHandleDatabase();
      try {
        return await new Promise((resolve, reject) => {
          const request = database.transaction(MEDIA_HANDLE_STORE, "readonly")
            .objectStore(MEDIA_HANDLE_STORE).get(key);
          request.onsuccess = () => resolve(request.result || null);
          request.onerror = () => reject(request.error || new Error("Could not restore the media website folder."));
        });
      } finally {
        database.close();
      }
    }

    function savedMediaSiteDirectory() {
      return savedMediaDirectoryHandle(MEDIA_HANDLE_KEY);
    }

    async function restoreMediaSiteDirectory() {
      if (!("indexedDB" in window)) return;
      try {
        const handle = await savedMediaSiteDirectory();
        if (!handle || handle.kind !== "directory" || handle.name !== "mh_media") return;
        mediaSiteDirectoryHandle = handle;
        const rememberedDirectory = await savedMediaDirectoryHandle(MEDIA_LAST_DIRECTORY_KEY).catch(() => null);
        mediaLastDirectoryHandle = rememberedDirectory?.kind === "directory" ? rememberedDirectory : handle;
        const permission = handle.queryPermission
          ? await handle.queryPermission({ mode: "readwrite" })
          : "granted";
        mediaDropState = permission === "granted" ? "ready" : "remembered";
        mediaDropMessage = permission === "granted"
          ? "Media website connected. Select any existing file inside mh_media."
          : "Media website folder remembered. Select a file to restore access.";
        updateMediaDropZone();
      } catch (_) {
        // Remembering the folder is optional; manual connection remains available.
      }
    }

    async function ensureMediaDirectoryPermission() {
      if (!mediaSiteDirectoryHandle) return false;
      if (!mediaSiteDirectoryHandle.queryPermission) return true;
      if (await mediaSiteDirectoryHandle.queryPermission({ mode: "readwrite" }) === "granted") return true;
      return await mediaSiteDirectoryHandle.requestPermission({ mode: "readwrite" }) === "granted";
    }

    async function connectMediaDirectory() {
      if (!("showDirectoryPicker" in window)) {
        mediaDropState = "error";
        mediaDropMessage = "Folder connection needs Chrome or Edge. The URL field still works normally.";
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return false;
      }
      try {
        const handle = await window.showDirectoryPicker({ id: "magic-hashtags-media-site", mode: "readwrite" });
        if (handle.name !== "mh_media") {
          mediaDropState = "error";
          mediaDropMessage = 'Choose the main "mh_media" folder. Then you can select a file from any folder inside it.';
          updateMediaDropZone();
          showToast(mediaDropMessage);
          return false;
        }
        mediaSiteDirectoryHandle = handle;
        mediaLastDirectoryHandle = handle;
        Promise.all([
          rememberMediaSiteDirectory(handle),
          rememberMediaDirectoryHandle(handle, MEDIA_LAST_DIRECTORY_KEY)
        ]).catch(() => {});
        mediaDropState = "ready";
        mediaDropMessage = "Media website connected. Select any existing file inside mh_media.";
        updateMediaDropZone();
        showToast("Media website connected. Existing files will be linked without copying them.");
        return true;
      } catch (error) {
        if (error?.name === "AbortError") return false;
        mediaDropState = "error";
        mediaDropMessage = `Could not connect the media website folder: ${error?.message || "folder access failed"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return false;
      }
    }

    function publicMediaUrl(pathParts) {
      return `${MEDIA_SITE_ORIGIN}/${pathParts.map((part) => encodeURIComponent(part)).join("/")}`;
    }

    function mediaPickerStartDirectory() {
      return mediaLastDirectoryHandle || mediaSiteDirectoryHandle;
    }

    async function rememberSelectedMediaDirectory(pathParts) {
      if (!mediaSiteDirectoryHandle || !Array.isArray(pathParts) || !pathParts.length) return;
      try {
        let directory = mediaSiteDirectoryHandle;
        for (const part of pathParts.slice(0, -1)) {
          directory = await directory.getDirectoryHandle(part);
        }
        mediaLastDirectoryHandle = directory;
        await rememberMediaDirectoryHandle(directory, MEDIA_LAST_DIRECTORY_KEY);
      } catch (_) {
        // The picker ID still remembers its last location if persisting the handle is unavailable.
      }
    }

    function linkMediaToSlide(slideId, file, pathParts, message, stateName = "linked") {
      const mediaType = mediaTypeForFile(file);
      if (!mediaType) throw new Error("Use an image, GIF, audio file, MP4, WebM, MOV, or M4V file.");
      const targetSlide = state.tutorial.slides.find((slide) => slide.id === slideId);
      if (!targetSlide) throw new Error("the destination slide is no longer available");
      targetSlide.media.url = publicMediaUrl(pathParts);
      targetSlide.media.type = mediaType;
      targetSlide.media.fit = "contain";
      targetSlide.media.x = 0;
      targetSlide.media.y = 0;
      targetSlide.media.scale = 1;
      targetSlide.media.naturalWidth = 0;
      targetSlide.media.naturalHeight = 0;
      if (targetSlide.kind !== "cover") {
        targetSlide.kind = targetSlide.kind === "scroll" && mediaType !== "video"
          ? "scroll"
          : mediaType === "video" ? "video" : targetSlide.kind === "video" ? "image" : targetSlide.kind;
        if (targetSlide.kind === "scroll") targetSlide.media.type = "image";
      }
      mediaDropState = stateName;
      mediaDropMessage = message;
      commit(message);
    }

    async function selectExistingMediaFile(expectedSlideKind = "", requestedSlideId = "") {
      const targetSlideId = requestedSlideId || currentSlide().id;
      if (!mediaSiteDirectoryHandle && !await connectMediaDirectory()) return;
      if (!("showOpenFilePicker" in window)) {
        showToast("File selection needs Chrome or Edge. You can still paste a media URL.");
        return;
      }
      try {
        if (!await ensureMediaDirectoryPermission()) throw new Error("folder access was not granted");
        const pickerTypes = expectedSlideKind === "video"
          ? [{
              description: "Video",
              accept: { "video/*": [".mp4", ".webm", ".mov", ".m4v"] }
            }]
          : ["image", "scroll"].includes(expectedSlideKind)
            ? [{
                description: "Images and GIFs",
                accept: { "image/*": [".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".avif"] }
              }]
            : [{
                description: "Images, video, GIF, and audio",
                accept: {
                  "image/*": [".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".avif"],
                  "video/*": [".mp4", ".webm", ".mov", ".m4v"],
                  "audio/*": [".mp3", ".m4a", ".wav", ".ogg", ".aac"]
                }
              }];
        const [fileHandle] = await window.showOpenFilePicker({
          id: MEDIA_LIBRARY_PICKER_ID,
          startIn: mediaPickerStartDirectory(),
          multiple: false,
          excludeAcceptAllOption: Boolean(expectedSlideKind),
          types: pickerTypes
        });
        if (!fileHandle || fileHandle.kind !== "file") throw new Error("Choose one media file.");
        const pathParts = await mediaSiteDirectoryHandle.resolve(fileHandle);
        if (!pathParts?.length) {
          throw new Error("That file is not inside the connected mh_media folder. Use Copy New File only if it is not on the media website yet.");
        }
        await rememberSelectedMediaDirectory(pathParts);
        const file = await fileHandle.getFile();
        const actualType = mediaTypeForFile(file);
        if (expectedSlideKind === "video" && actualType !== "video") {
          throw new Error("Choose an MP4, WebM, MOV, or M4V video file.");
        }
        if (expectedSlideKind === "image" && !["image", "gif"].includes(actualType)) {
          throw new Error("Choose an image or GIF file.");
        }
        linkMediaToSlide(targetSlideId, file, pathParts, `Linked existing website file: ${pathParts.join("/")}`);
        showToast(`${file.name} linked and loaded. No file was copied or renamed.`);
      } catch (error) {
        if (error?.name === "AbortError") return;
        mediaDropState = "error";
        mediaDropMessage = `Could not link that file: ${error?.message || "file access failed"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

    async function selectExistingAnnotationMedia(type) {
      const picker = ANNOTATION_MEDIA_PICKERS[type];
      if (!picker) return;
      if (!("showDirectoryPicker" in window) || !("showOpenFilePicker" in window)) {
        activateToolbarAnnotationUrl(type);
        showToast(`Folder selection is unavailable here. Paste the ${picker.label} URL in the toolbar and press Return.`);
        return;
      }
      if (!mediaSiteDirectoryHandle) {
        if (await connectMediaDirectory()) {
          mediaDropMessage = `mh_media is connected. Click the ${picker.label} annotation button again to select the file.`;
          updateMediaDropZone();
          showToast(mediaDropMessage);
        }
        return;
      }
      const targetSlideId = currentSlide().id;
      try {
        if (!await ensureMediaDirectoryPermission()) throw new Error("folder access was not granted");
        const [fileHandle] = await window.showOpenFilePicker({
          id: MEDIA_LIBRARY_PICKER_ID,
          startIn: mediaPickerStartDirectory(),
          multiple: false,
          excludeAcceptAllOption: type !== "audio",
          types: [{ description: picker.description, accept: picker.accept }]
        });
        if (!fileHandle || fileHandle.kind !== "file") throw new Error(`Choose one ${picker.label} file.`);
        const pathParts = await mediaSiteDirectoryHandle.resolve(fileHandle);
        if (!pathParts?.length) {
          throw new Error("That file is not inside the connected mh_media folder.");
        }
        await rememberSelectedMediaDirectory(pathParts);
        const file = await fileHandle.getFile();
        const actualType = mediaTypeForFile(file);
        if (actualType !== type) {
          throw new Error(`That is ${actualType ? `a ${actualType}` : "not a supported media"} file. Choose ${picker.label}.`);
        }
        if (currentSlide().id !== targetSlideId) throw new Error("the destination slide changed while the picker was open");
        const publicUrl = publicMediaUrl(pathParts);
        const videoLabel = toolbarVideoLabel();
        mediaDropState = "linked";
        mediaDropMessage = `Linked annotation file: ${pathParts.join("/")}`;
        addAnnotationFromUrl(type, publicUrl, videoLabel);
        if (type === "video") resetToolbarAnnotationInput(true);
        showToast(`${file.name} added as an annotation. No file was copied or renamed.`);
      } catch (error) {
        if (error?.name === "AbortError") return;
        mediaDropState = "error";
        mediaDropMessage = `Could not add that ${picker.label} annotation: ${error?.message || "file access failed"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

    async function selectExistingSlideAudio() {
