    async function chooseNewMediaFile() {
      if (!mediaSiteDirectoryHandle) {
        if (await connectMediaDirectory()) {
          mediaDropMessage = "mh_media is connected. Click Copy a New File again to select the file.";
          updateMediaDropZone();
          showToast(mediaDropMessage);
        }
        return;
      }
      if (!("showOpenFilePicker" in window)) {
        showToast("File selection needs Chrome or Edge.");
        return;
      }
      try {
        const [fileHandle] = await window.showOpenFilePicker({ id: "magic-hashtags-new-media", multiple: false });
        await copyNewMediaFile(await fileHandle.getFile());
      } catch (error) {
        if (error?.name === "AbortError") return;
        mediaDropState = "error";
        mediaDropMessage = `Could not add that new file: ${error?.message || "file access failed"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

    async function copyNewMediaFile(file) {
      if (!file) return;
      const mediaType = mediaTypeForFile(file);
      if (!mediaType) {
        mediaDropState = "error";
        mediaDropMessage = "Use an image, GIF, audio file, MP4, WebM, MOV, or M4V file.";
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return;
      }
      const folder = mediaFolderSlug();
      if (!folder) {
        mediaDropState = "error";
        mediaDropMessage = "Add a short tutorial folder name before copying the new file.";
        updateMediaDropZone();
        root.querySelector("#mediaDropFolder")?.focus();
        showToast(mediaDropMessage);
        return;
      }
      if (!mediaSiteDirectoryHandle) {
        mediaDropState = "error";
        mediaDropMessage = "Connect the main mh_media folder first.";
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return;
      }
      const targetSlideId = currentSlide().id;
      try {
        if (!await ensureMediaDirectoryPermission()) throw new Error("write permission was not granted");
        mediaDropState = "copying";
        mediaDropMessage = `Copying ${file.name} (${formatMediaFileSize(file.size)})…`;
        updateMediaDropZone();
        const tutorialsDirectory = await mediaSiteDirectoryHandle.getDirectoryHandle("tutorials", { create: true });
        const tutorialDirectory = await tutorialsDirectory.getDirectoryHandle(folder, { create: true });
        const filename = await availableMediaFilename(tutorialDirectory, webSafeMediaFilename(file.name));
        const fileHandle = await tutorialDirectory.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        await writable.write(file);
        await writable.close();
        linkMediaToSlide(
          targetSlideId,
          file,
          ["tutorials", folder, filename],
          `Copied and linked tutorials/${folder}/${filename}. Publish the media website when you are ready.`,
          "copied"
        );
        showToast(`${filename} copied and linked. Publish the media website when ready.`);
      } catch (error) {
        mediaDropState = "error";
        mediaDropMessage = `Media copy failed: ${error?.message || "unknown error"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

	    function computedPublicUrl(meta = state.meta) {
	      const sectionSlug = slugify(meta.section);
	      const section = PUBLIC_SECTION_FOLDERS[sectionSlug] || sectionSlug;
      const tutorial = slugify(meta.tutorialSlug);
      if (section && tutorial) return `${CANONICAL_SITE}/learn/${section}/${tutorial}/`;
      if (section) return `${CANONICAL_SITE}/learn/${section}/`;
      return `${CANONICAL_SITE}/learn/`;
    }

    function publicUrl(meta = state.meta) {
      if (meta.touched?.publicUrl && String(meta.publicUrl || "").trim()) {
        return String(meta.publicUrl).trim();
      }
      return computedPublicUrl(meta);
    }

    function applySmartDefaults() {
      const touched = state.meta.touched;
      const title = state.tutorial.title === "TUTORIAL TITLE" ? "" : state.tutorial.title.trim();
      const cover = state.tutorial.slides[0];
      const slug = slugify(title);
      const set = (key, value) => {
        if (!touched[key]) state.meta[key] = value;
      };
      set("tutorialSlug", slug);
      set("mediaFolder", slug);
      set("cardTitle", title);
      set("summary", cover?.description || "");
      set("modalDescription", cover?.description || "");
      set("socialTitle", title);
      set("socialDescription", cover?.description || "");
      set("socialImage", cover?.media?.url || "");
	      set("socialImageAlt", title ? `${title} tutorial preview` : "");
	      set("primaryActionLabel", state.meta.pageType === "demo" ? "Open Tutorial" : "Open Tool");
      set("publicUrl", computedPublicUrl());
    }

    function markTouched(key) {
      state.meta.touched[key] = true;
    }

    function scheduleSave() {
      if (MODE !== "builder") return;
      clearTimeout(saveTimer);
      draftSavePhase = "saving";
      updateDraftSaveStatus();
      saveTimer = setTimeout(saveStateNow, 180);
    }

    function saveStateNow() {
      if (MODE !== "builder") return false;
      clearTimeout(saveTimer);
      state.meta.updatedAt = Date.now();
      let browserBackupSaved = true;
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        lastDraftSavedAt = state.meta.updatedAt;
      } catch (error) {
        browserBackupSaved = false;
        draftStorageError = `Browser autosave failed: ${error?.message || "storage access failed"}`;
      }
      if (IS_PROJECT_APP && currentProject) {
        queueProjectDiskSave();
        return true;
      }
      if (browserBackupSaved) {
        draftStorageError = "";
        draftSavePhase = "saved";
        updateDraftSaveStatus();
        return true;
      } else {
        draftSavePhase = "error";
        updateDraftSaveStatus();
        return false;
      }
    }

    function queueProjectDiskSave() {
      if (!IS_PROJECT_APP || !currentProject) return Promise.resolve(false);
      const snapshot = clone(state);
      const saveVersion = ++projectDiskSaveVersion;
      draftSavePhase = "saving";
      updateDraftSaveStatus();
      projectDiskSavePromise = projectDiskSavePromise
        .catch(() => false)
        .then(async () => {
          const payload = await projectApi(`/${encodeURIComponent(PROJECT_ID)}`, {
            method: "PUT",
            body: JSON.stringify({ state: snapshot })
          });
          currentProject = payload.project;
          const summary = {
            id: currentProject.id,
            name: currentProject.name,
            createdAt: currentProject.createdAt,
            updatedAt: currentProject.updatedAt
          };
          projects = projects.map((project) => project.id === PROJECT_ID ? summary : project);
          if (saveVersion === projectDiskSaveVersion) {
            draftStorageError = "";
            draftSavePhase = "saved";
            lastDraftSavedAt = Number(snapshot.meta?.updatedAt) || Date.now();
            updateDraftSaveStatus();
          }
          return true;
        })
        .catch((error) => {
          if (saveVersion === projectDiskSaveVersion) {
            draftStorageError = `Disk autosave failed: ${error?.message || "save failed"}. The browser safety copy is still available.`;
            draftSavePhase = "error";
            updateDraftSaveStatus();
          }
          return false;
        });
      return projectDiskSavePromise;
    }

    async function saveProjectToDiskNow() {
      if (!IS_PROJECT_APP || !currentProject) return saveStateNow();
      saveStateNow();
      return projectDiskSavePromise;
    }

    function draftSaveStatusText() {
      if (draftSavePhase === "error") return IS_PROJECT_APP ? "Disk autosave failed — browser safety copy kept" : "Autosave failed — use Save Editable Copy";
      if (draftSavePhase === "saving") return IS_PROJECT_APP ? "Saving draft to this Mac…" : "Saving browser draft…";
      if (lastDraftSavedAt) {
        const time = new Date(lastDraftSavedAt).toLocaleTimeString([], { hour: "numeric", minute: "2-digit", second: "2-digit" });
        return IS_PROJECT_APP ? `Draft saved on this Mac ${time}` : `Browser draft saved ${time}`;
      }
      return IS_PROJECT_APP ? "On-disk draft ready" : "Browser draft ready";
    }

    function updateDraftSaveStatus() {
      const status = root?.querySelector("[data-draft-save-status]");
      if (!status) return;
      status.dataset.state = draftSavePhase;
      status.textContent = draftSaveStatusText();
      status.title = draftStorageError || (IS_PROJECT_APP
        ? "Autosaves this named draft to the hidden tutorial project file beside the V2 builder."
        : `Autosaves this draft in the current browser for ${DRAFT_FILENAME}`);
    }

    function editableCopyFilename() {
      const stem = DRAFT_FILENAME.replace(/\.html?$/i, "");
      const fallbackStem = slugify(state.meta.tutorialSlug || state.tutorial.title) || stem || "tutorial-demo";
      return `${fallbackStem}-editable-demo-builder.html`;
    }

    function historySnapshot() {
      const meta = clone(state.meta);
      delete meta.updatedAt;
      return JSON.stringify({ meta, tutorial: state.tutorial });
    }

    function recordUndoStep() {
      const nextSnapshot = historySnapshot();
      if (!committedSnapshot || nextSnapshot === committedSnapshot) return;
      undoStack.push(committedSnapshot);
      if (undoStack.length > 50) undoStack.shift();
      committedSnapshot = nextSnapshot;
    }

    function undoLastChange() {
      recordUndoStep();
      const previousSnapshot = undoStack.pop();
      if (!previousSnapshot) {
        showToast("Nothing to undo.");
        return;
      }
      const previous = readJson(previousSnapshot, null);
      if (!previous) return;
      state.meta = previous.meta;
      state.tutorial = previous.tutorial;
      normalizeState();
      const slide = currentSlide();
      if (!isSlideIntroState(slide) && !slide.hotspots.some((item) => item.id === state.ui.activeHotspotId)) {
        state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
      }
      const selectedStillExists = state.ui.selectedKind === "hotspot"
        ? slide.hotspots.some((item) => item.id === state.ui.selectedId)
        : state.ui.selectedKind === "annotation"
          ? slide.annotations.some((item) => item.id === state.ui.selectedId)
          : false;
      if (!selectedStillExists) {
        state.ui.selectedKind = null;
        state.ui.selectedId = null;
      }
      state.ui.contentsOpen = false;
      state.ui.videoModalId = null;
      committedSnapshot = historySnapshot();
      scheduleSave();
      render();
      showToast("Undid last change.");
    }

    function commit(message, shouldRender = true) {
      applySmartDefaults();
      recordUndoStep();
      scheduleSave();
      if (message) showToast(message);
      if (shouldRender) render();
    }

    function showToast(message, duration = 2600) {
      clearTimeout(toastTimer);
      document.querySelector(".toast")?.remove();
      const node = document.createElement("div");
      node.className = "toast";
      node.setAttribute("role", "status");
      node.textContent = message;
      document.body.append(node);
      toastTimer = setTimeout(() => node.remove(), duration);
    }

    function toggleDraftMore() {
      draftMoreOpen = !draftMoreOpen;
      render();
      if (draftMoreOpen) setTimeout(() => root.querySelector(".builder-more-popover button")?.focus(), 0);
    }

    function runDraftMoreAction(action) {
      draftMoreOpen = false;
      render();
      return action();
    }

