        target: '<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/>',
        zoomIn: '<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M10 7v6M7 10h6"/>',
        zoomOut: '<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6"/>',
        reset: '<path d="M4 8V3m0 0h5M4 3l4 4a8 8 0 1 1-2 9"/>',
        flipHorizontal: '<path d="M12 3v18M9 7H4m0 0 3-3M4 7l3 3M15 17h5m0 0-3-3m3 3-3 3"/>',
        close: '<path d="M5 5l14 14M19 5 5 19"/>'
      };
      return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="miter">${paths[name] || ""}</svg>`;
    }

    function toolbarIcon(filename) {
      const encodedFilename = encodeURIComponent(String(filename || ""));
      const localSrc = `images/tutorial-annotations/builder-toolbar/${encodedFilename}`;
      const hostedSrc = `${PUBLIC_ANNOTATION_ASSET_ROOT}builder-toolbar/${encodedFilename}`;
      return `<img class="toolbar-icon-image" src="${escapeHtml(localSrc)}" data-toolbar-fallback="${escapeHtml(hostedSrc)}" alt="" aria-hidden="true" onerror="this.onerror=null;this.src=this.dataset.toolbarFallback">`;
    }

    function numberedToolbarArt(filename) {
      const src = `images/tutorial-annotations/builder-toolbar/new-toolbar/${encodeURIComponent(String(filename || ""))}`;
      return `<img class="numbered-toolbar-art" src="${escapeHtml(src)}" alt="" aria-hidden="true">`;
    }

    function groupedShapes() {
      const groups = new Map();
      shapes.forEach((shape) => {
        const group = String(shape.group || "SHAPES").trim().toUpperCase() || "SHAPES";
        if (!groups.has(group)) groups.set(group, []);
        groups.get(group).push(shape);
      });
      return Array.from(groups, ([group, entries]) => ({
        group,
        entries: entries.slice().sort((a, b) => String(a.name).localeCompare(String(b.name)))
      })).sort((a, b) => a.group.localeCompare(b.group));
    }

    function renderShapeNavigation(numbered = false) {
      const categories = groupedShapes();
      const trigger = numbered
        ? numberedToolbarArt("tb-A19-shapes-dropdown.png")
        : '<span>SHAPES</span><span aria-hidden="true">▾</span>';
      return `
        <div class="shape-nav ${numbered ? "numbered-toolbar-shapes" : ""}" data-shape-menu>
          <button class="shape-nav-trigger" type="button" aria-haspopup="menu" aria-label="Open shape categories" title="Type a letter to jump through categories; Enter opens the highlighted category">${trigger}</button>
          <div class="shape-nav-panel" role="menu" aria-label="Shape categories">
            ${categories.length ? categories.map(({ group, entries }) => {
              const disabled = ["BUILT-IN CONTROLS", "HOTSPOTS"].includes(group);
              return `
                <div class="shape-nav-category ${disabled ? "is-disabled" : ""}">
                  <button class="shape-nav-category-trigger" type="button" role="menuitem" aria-haspopup="menu" ${disabled ? "disabled" : ""}>${escapeHtml(group)}</button>
                  <div class="shape-nav-items" role="menu" aria-label="${escapeHtml(group)}">
                    ${entries.map((shape) => `<button class="shape-nav-item" type="button" role="menuitem" data-action="add-shape-from-menu" data-url="${escapeHtml(shape.url)}" data-name="${escapeHtml(shape.name)}" ${disabled ? "disabled" : ""}>${escapeHtml(String(shape.name).toUpperCase())}</button>`).join("")}
                  </div>
                </div>
              `;
            }).join("") : '<span class="shape-nav-empty">NO SHAPES PUBLISHED</span>'}
          </div>
        </div>
      `;
    }

    function renderDraftNavigation() {
      return `
        <div class="shape-nav numbered-toolbar-drafts" data-shape-menu data-draft-menu>
          <button class="shape-nav-trigger" type="button" aria-haspopup="menu" aria-label="Open draft image folders">${numberedToolbarArt("tb-A20-drafts-dropdown.png")}</button>
          <div class="shape-nav-panel" role="menu" aria-label="Draft image folders">
            ${draftImageGroups.map(({ label, entries, loaded, available }) => `
              <div class="shape-nav-category">
                <button class="shape-nav-category-trigger" type="button" aria-haspopup="menu">${escapeHtml(label)}</button>
                <div class="shape-nav-items" role="menu" aria-label="${escapeHtml(label)} images">
                  ${entries.length
                    ? entries.map((entry) => `<button class="shape-nav-item" type="button" data-action="add-draft-image" data-url="${escapeHtml(entry.url)}" data-name="${escapeHtml(entry.name)}" data-type="${escapeHtml(entry.type)}">${escapeHtml(entry.label)}</button>`).join("")
                    : `<span class="shape-nav-empty">${loaded ? (available ? "EMPTY FOLDER" : "FOLDER UNAVAILABLE") : "LOADING…"}</span>`}
                </div>
              </div>
            `).join("")}
          </div>
        </div>
      `;
    }

    function positionShapeNavigation(menu) {
      if (!menu) return;
      const trigger = menu.querySelector(".shape-nav-trigger");
      const panel = menu.querySelector(".shape-nav-panel");
      if (!trigger || !panel) return;
      const rect = trigger.getBoundingClientRect();
      const panelWidth = 190;
      const itemPanelWidth = 264;
      const left = clamp(rect.left, 8, Math.max(8, window.innerWidth - panelWidth - 8));
      panel.style.left = `${left}px`;
      const hoverGap = menu.matches("[data-draft-menu]") ? 0 : 4;
      panel.style.top = `${Math.min(rect.bottom + hoverGap, window.innerHeight - 80)}px`;
      menu.classList.toggle("shape-nav-open-left", left + panelWidth + itemPanelWidth > window.innerWidth - 8 && left >= itemPanelWidth);
    }

    function shapeMenuButtons(scope, selector) {
      return Array.from(scope?.querySelectorAll(selector) || [])
        .filter((button) => !button.disabled && button.offsetParent !== null);
    }

    function focusShapeMenuMatch(scope, selector, letter) {
      const key = String(letter || "").toUpperCase();
      const matches = shapeMenuButtons(scope, selector)
        .filter((button) => button.textContent.trim().toUpperCase().startsWith(key));
      if (!matches.length) return false;
      const now = Date.now();
      const continuing = shapeMenuTypeahead.scope === scope
        && shapeMenuTypeahead.key === key
        && now - shapeMenuTypeahead.at < 1200;
      const index = continuing ? (shapeMenuTypeahead.index + 1) % matches.length : 0;
      shapeMenuTypeahead = { scope, key, index, at: now };
      matches[index].focus();
      return true;
    }

    function handleShapeNavigationKey(event) {
      if (MODE !== "builder" || event.ctrlKey || event.metaKey || event.altKey) return false;
      const menu = event.target.closest?.("[data-shape-menu]:not([data-draft-menu])");
      if (!menu) return false;
      positionShapeNavigation(menu);
      const trigger = event.target.closest(".shape-nav-trigger");
      const categoryTrigger = event.target.closest(".shape-nav-category-trigger");
      const item = event.target.closest(".shape-nav-item");
      const panel = menu.querySelector(":scope > .shape-nav-panel");
      const category = event.target.closest(".shape-nav-category");
      const itemsPanel = item?.closest(".shape-nav-items");
      const isLetter = event.key.length === 1 && /^[a-z0-9]$/i.test(event.key);

      if (isLetter) {
        const matched = item
          ? focusShapeMenuMatch(itemsPanel, ":scope > .shape-nav-item", event.key)
          : focusShapeMenuMatch(panel, ":scope > .shape-nav-category > .shape-nav-category-trigger", event.key);
        if (matched) event.preventDefault();
        return matched;
      }

      if (trigger && ["Enter", " ", "ArrowDown"].includes(event.key)) {
        const first = shapeMenuButtons(panel, ":scope > .shape-nav-category > .shape-nav-category-trigger")[0];
        if (!first) return false;
        event.preventDefault();
        shapeMenuTypeahead = { scope: null, key: "", index: -1, at: 0 };
        first.focus();
        return true;
      }

      if (categoryTrigger && ["Enter", " ", "ArrowRight"].includes(event.key)) {
        const first = shapeMenuButtons(category, ":scope > .shape-nav-items > .shape-nav-item")[0];
        if (!first) return false;
        event.preventDefault();
        shapeMenuTypeahead = { scope: null, key: "", index: -1, at: 0 };
        first.focus();
        return true;
      }

      if (item && ["Escape", "ArrowLeft"].includes(event.key)) {
        event.preventDefault();
        category?.querySelector(":scope > .shape-nav-category-trigger")?.focus();
        return true;
      }

      const navigationScope = item ? itemsPanel : categoryTrigger ? panel : null;
      const navigationSelector = item
        ? ":scope > .shape-nav-item"
        : ":scope > .shape-nav-category > .shape-nav-category-trigger";
      if (navigationScope && ["ArrowDown", "ArrowUp"].includes(event.key)) {
        const buttons = shapeMenuButtons(navigationScope, navigationSelector);
        const current = buttons.indexOf(event.target);
        if (!buttons.length) return false;
        event.preventDefault();
        const delta = event.key === "ArrowDown" ? 1 : -1;
        buttons[(current + delta + buttons.length) % buttons.length].focus();
        return true;
      }

      if (event.key === "Escape") {
        event.preventDefault();
        menu.querySelector(":scope > .shape-nav-trigger")?.focus();
        return true;
      }
      return false;
    }

    function isPipeBodyLine(line) {
      return /^\s*\|(?:\s|$)/.test(line);
    }

    function isNumberedBodyLine(line) {
      return /^\s*\d+[.)](?:\s|$)/.test(line);
    }

    function normalizeMixedBodyValue(value, legacyListStyle = "") {
      const normalized = String(value || "").replace(/\r/g, "");
      if (legacyListStyle !== "pipe") return normalized;
      return normalized
        .split("\n")
        .map((line) => line.trim() && !isPipeBodyLine(line) ? `| ${line}` : line)
        .join("\n");
    }

    function mixedBodyLines(value) {
      return String(value || "")
        .replace(/\r/g, "")
        .split("\n")
        .map((line) => {
          const kind = isPipeBodyLine(line) ? "pipe" : isNumberedBodyLine(line) ? "numbered" : "plain";
          const text = kind === "pipe"
            ? line.replace(/^\s*\|\s?/, "")
            : kind === "numbered"
              ? line.replace(/^\s*\d+[.)]\s?/, "")
              : line;
          return { kind, pipe: kind === "pipe", numbered: kind === "numbered", text };
        });
    }

    function bodyHasPipeLines(value) {
      return mixedBodyLines(value).some((line) => line.pipe);
    }

    function bodyHasNumberedLines(value) {
      return mixedBodyLines(value).some((line) => line.numbered);
    }

    function wordColorTarget(binding) {
      const [path, id] = String(binding || "").split(":");
      const [kind, field] = path.split(".");
      if (kind === "slide" && ["title", "description"].includes(field)) {
        const item = state.tutorial.slides.find(s => s.id === id);
        return item ? { item, field } : null;
      }
      if (kind === "annotation" && ["text", "introTitle", "introBody", "calloutTitle", "calloutBody"].includes(field)) {
        const item = currentSlide().annotations.find(a => a.id === id);
        return item ? { item, field } : null;
      }
      return null;
    }

    function safeWordHtml(html) {
      const template = document.createElement("template");
      template.innerHTML = String(html || "");
      const clean = node => {
        if (node.nodeType === 3) return escapeHtml(node.textContent);
        if (node.nodeType !== 1 || ["SCRIPT", "STYLE", "IFRAME", "OBJECT"].includes(node.tagName)) return "";
        if (node.tagName === "BR") return "<br>";
        const content = Array.from(node.childNodes).map(clean).join("");
        const declarations = ["color", "background-color"].map(key => {
          const value = node.style.getPropertyValue(key);
          return value && CSS.supports(key, value) ? key + ":" + value : "";
        }).filter(Boolean).join(";");
        const result = declarations ? '<span style="' + escapeHtml(declarations) + '">' + content + "</span>" : content;
        return result + (["DIV", "P"].includes(node.tagName) ? "<br>" : "");
      };
      return Array.from(template.content.childNodes).map(clean).join("").replace(/(<br>)+$/, "");
    }

    function savedWordHtml(item, field) {
      const saved = item?.richText?.[field];
      return saved && saved.text === item[field] ? saved : null;
    }

    function renderWordText(item, field) {
      const saved = savedWordHtml(item, field);
      return saved?.html != null ? safeWordHtml(saved.html) : escapeHtml(item?.[field] || "");
    }

    function captureWordFormatting(editor) {
      const target = wordColorTarget(editor?.dataset.bind);
      if (!target) return;
      target.item.richText ||= {};
      const lines = editor.classList.contains("mixed-body-editor")
        ? Array.from(editor.querySelectorAll(":scope > .mixed-body-line")).map(line => safeWordHtml(line.innerHTML))
        : null;
      target.item.richText[target.field] = { text: target.item[target.field], ...(lines ? { lines } : { html: safeWordHtml(editor.innerHTML) }) };
    }

    function rememberWordSelection() {
      const selection = window.getSelection();
      if (!selection?.rangeCount || selection.isCollapsed) return;
      const range = selection.getRangeAt(0);
      const parent = range.commonAncestorContainer.nodeType === 1 ? range.commonAncestorContainer : range.commonAncestorContainer.parentElement;
      const editor = parent?.closest('[contenteditable="true"][data-bind]');
      if (!editor || !wordColorTarget(editor.dataset.bind)) return;
      const prefix = range.cloneRange();
      prefix.selectNodeContents(editor);
      prefix.setEnd(range.startContainer, range.startOffset);
      rememberWordSelection.saved = { binding: editor.dataset.bind, start: prefix.toString().length, end: prefix.toString().length + range.toString().length, text: editor.textContent };
    }

    function applyWordColor(property, value) {
      const saved = rememberWordSelection.saved;
      const editor = saved && Array.from(root.querySelectorAll('[contenteditable="true"][data-bind]')).find(e => e.dataset.bind === saved.binding);
      if (!editor || editor.textContent !== saved.text || saved.end <= saved.start) {
        showToast("Highlight the words you want to color first.");
        return;
      }
      if (!["color", "background-color"].includes(property) || !CSS.supports(property, value)) return;
      const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT);
      const parts = [];
      let offset = 0, node;
      while ((node = walker.nextNode())) {
        const end = offset + node.length;
        if (end > saved.start && offset < saved.end) parts.push({ node, start: Math.max(0, saved.start - offset), end: Math.min(node.length, saved.end - offset) });
        offset = end;
      }
      parts.reverse().forEach(part => {
        if (part.end < part.node.length) part.node.splitText(part.end);
        const text = part.start ? part.node.splitText(part.start) : part.node;
        const span = document.createElement("span");
        span.style.setProperty(property, value);
        text.replaceWith(span);
        span.append(text);
      });
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      captureWordFormatting(editor);
      commit(property === "color" ? "Changed selected words' color." : "Changed selected words' highlight.", false);
    }

    function renderWordColorControls() {
      const art = (location.pathname.includes("/tutorial-builder-work/") ? "../" : "") + "images/tutorial-annotations/builder-toolbar/new-toolbar/tb-B18-font-color-picker.png";
      return '<span class="word-color-controls" role="group" aria-label="Selected words"><label title="Selected words: text color"><img src="' + art + '" alt=""><span>A</span><input type="color" data-word-color="color" value="#000000" aria-label="Selected words text color"></label><label title="Selected words: text background highlight"><img src="' + art + '" alt=""><span style="background:#ffff00">A</span><input type="color" data-word-color="background-color" value="#ffff00" aria-label="Selected words highlight color"></label><button type="button" data-action="clear-word-highlight" title="Remove highlight from selected words" aria-label="Clear selected words highlight">No<br>highlight</button></span>';
    }

    function renderMixedBodyContent(value, richLines = null) {
      const blocks = [];
      let paragraphs = [];
      let bullets = [];
      let numbered = [];
      const flushParagraph = () => {
        if (!paragraphs.length) return;
        blocks.push(`<p>${paragraphs.join("<br>")}</p>`);
        paragraphs = [];
      };
      const flushBullets = () => {
        if (!bullets.length) return;
        blocks.push(`<ul class="pipe-list">${bullets.map((line) => `<li>${line}</li>`).join("")}</ul>`);
        bullets = [];
      };
      const flushNumbered = () => {
        if (!numbered.length) return;
        blocks.push(`<ol class="numbered-list">${numbered.map((line) => `<li>${line}</li>`).join("")}</ol>`);
        numbered = [];
      };

      mixedBodyLines(value).forEach((line, index) => {
        const html = richLines?.[index] != null ? safeWordHtml(richLines[index]) : escapeHtml(line.text);
        if (line.pipe) {
          flushParagraph();
          flushNumbered();
          bullets.push(html);
          return;
        }
        if (line.numbered) {
          flushParagraph();
          flushBullets();
          numbered.push(html);
          return;
        }
        flushBullets();
        flushNumbered();
        if (line.text) {
          paragraphs.push(html);
        } else {
          flushParagraph();
        }
      });
      flushParagraph();
      flushBullets();
      flushNumbered();
      return blocks.join("");
    }

    function renderBodyFormatBar(pipeAction, numberedAction, id, pipeActive, numberedActive, leadingControls = "") {
      if (MODE !== "builder") return "";
      return `
        <div class="body-format-bar">
          ${leadingControls}
          <button class="body-list-toggle pipe-list-toggle ${pipeActive ? "is-active" : ""}" type="button"
            data-list-kind="pipe" data-action="${pipeAction}" data-id="${id}" aria-pressed="${pipeActive}"
            title="Toggle pipe bullets for the current or selected lines">
            <span class="pipe-list-toggle__mark" aria-hidden="true">|</span>Pipe bullets
          </button>
          <button class="body-list-toggle numbered-list-toggle ${numberedActive ? "is-active" : ""}" type="button"
            data-list-kind="numbered" data-action="${numberedAction}" data-id="${id}" aria-pressed="${numberedActive}"
            title="Toggle a numbered list for the current or selected lines">
            <span class="pipe-list-toggle__mark" aria-hidden="true">1.</span>Numbered
          </button>
        </div>
      `;
    }

    function renderBody(value, options) {
      const { className, binding, label, placeholder } = options;
      const target = wordColorTarget(binding);
      const richLines = target ? savedWordHtml(target.item, target.field)?.lines : null;
      if (MODE === "builder") {
        const lines = mixedBodyLines(value);
        const content = lines.map((line, index) => {
          const placeholderAttribute = lines.length === 1 && !line.text
            ? ` data-placeholder="${escapeHtml(placeholder)}"`
            : "";
          const listClass = line.kind === "pipe" ? "is-pipe" : line.kind === "numbered" ? "is-numbered" : "";
          return `<div class="mixed-body-line ${listClass}" data-list-kind="${line.kind}" data-pipe="${line.pipe}"${placeholderAttribute}>${richLines?.[index] != null ? safeWordHtml(richLines[index]) : escapeHtml(line.text)}</div>`;
        }).join("");
        return `<div class="${className} mixed-body-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${escapeHtml(label)}" data-bind="${binding}">${content}</div>`;
      }
      return `<div class="${className} mixed-body">${renderMixedBodyContent(value, richLines)}</div>`;
    }

    function objectStyle(item) {
      const width = Math.max(1, Number(item.w) || 1);
      const height = Math.max(1, Number(item.h) || 1);
      const magnifierRadius = item.magnifierShape === "circle" ? 50 : item.magnifierShape === "rounded" ? 12 : 0;
      const clipFrameRadius = item.type === "clip-frame" && item.clipFrameShape === "rounded" ? 12 : 0;
      const magnifierSceneWidth = 10000 / width;
      const magnifierSceneHeight = 10000 / height;
      const magnifierSceneLeft = -((Number(item.x) || 0) - width / 2) * 100 / width;
      const magnifierSceneTop = -((Number(item.y) || 0) - height / 2) * 100 / height;
      const scrollY = (Number(item.y) || 0) * SCENE_HEIGHT / SCENE_WIDTH;
      const scrollHeight = (Number(item.h) || 1) * SCENE_HEIGHT / SCENE_WIDTH;
      const cardTextScale = (Number(item.textFontSize) || 16) / 16;
      const cardTitleBase = item.type === "slide-intro" ? 1.333333 : 1.266667;
      const cardTitleFontSize = cardTitleBase * cardTextScale;
      const cardBodyFontSize = 1.133333 * cardTextScale;
      return appearanceStyle(item) + cropWindowStyle(item) + `--x:${item.x}%;--y:${item.y}%;--w:${item.w}%;--h:${item.h}%;--scroll-y:${scrollY}cqw;--scroll-h:${scrollHeight}cqw;--z:${item.z};--opacity:${item.opacity};--rotation:${item.rotation || 0}deg;--flip-x:${item.flipX ? -1 : 1};--markup-width:${item.strokeWidth || 5};--markup-corner-radius:${item.markupCornerRadius || 0};--markup-color:${item.markupColor || "#000000"};--markup-fill-color:${item.fillColor || "#ffffff"};--cover-color:${item.fillColor || "#ffffff"};--blur-strength:${item.blurStrength || 12}px;--text-font-size:${item.textFontSize || 16}px;--card-title-font-size:${cardTitleFontSize}cqw;--card-body-font-size:${cardBodyFontSize}cqw;--text-letter-spacing:${item.textLetterSpacing || 0}px;--text-line-height:${item.textLineHeight || 1.2};--text-align:${item.textAlign || "center"};--crop-x:${item.cropX ?? 50}%;--crop-y:${item.cropY ?? 50}%;--crop-scale:${item.cropScale || 1};--corner-radius:${item.cornerRadius || 0}%;--magnifier-scale:${item.magnification || 2};--magnifier-radius:${magnifierRadius}%;--clip-frame-radius:${clipFrameRadius}%;--magnifier-scene-width:${magnifierSceneWidth}%;--magnifier-scene-height:${magnifierSceneHeight}%;--magnifier-scene-left:${magnifierSceneLeft}%;--magnifier-scene-top:${magnifierSceneTop}%;--magnifier-origin-x:${item.x}%;--magnifier-origin-y:${item.y}%`;
    }

    function appearanceStyle(item) {
      const height = clamp(item.shadowHeight ?? 9, 0, 40);
      const shadow = item.imageShadow && height > 0 ? `drop-shadow(0 ${height}px ${Math.max(1, height * .45)}px rgba(0,0,0,.28))` : "none";
      const previewShadow = item.imageShadow && height > 0 ? `drop-shadow(0 ${height*.22}px ${Math.max(.5,height*.1)}px rgba(0,0,0,.28))` : "none";
      const color = item.appearanceColor;
      const border = color && ["image","gif","shape","video","audio","link","clip-frame","blur"].includes(item.type) ? `--appearance-border:2px solid ${color};` : "";
      return `${border}${color ? `--appearance-text:${color};` : ""}--object-shadow:${shadow};--object-shadow-preview:${previewShadow};--object-outline-width:${item.outlineEnabled === false ? 0 : 3}px;--object-outline-color:${color || "#000000"};`;
    }

    function selectedObjectColor(item) {
      if (!item) return "#000000";
      if (item.type === "text") return item.textColor;
      if (item.type === "cover" || (item.type === "markup" && item.markup.includes("fill"))) return item.fillColor;
      if (item.type === "markup") return item.markupColor;
      return item.appearanceColor === "transparent" ? "#000000" : item.appearanceColor || "#000000";
    }

    function applySelectedObjectColor(color) {
      const item = selectedObject();
      if (!item || state.ui.selectedKind === "hotspot" || !/^#[0-9a-f]{6}$/i.test(color)) return;
      if (item.type === "text") item.textColor = color;
      else if (item.type === "cover") item.fillColor = color;
      else if (item.type === "markup") {
        if (item.markup.includes("fill")) item.fillColor = color;
        else item.markupColor = color;
      } else item.appearanceColor = color;
      commit("Updated selected object color.");
    }

    function cropWindowStyle(item) {
      const crop = item.cropEnabled && item.cropWindow;
      return crop ? `--crop-left:${crop.left}%;--crop-top:${crop.top}%;--crop-width:${crop.width}%;--crop-height:${crop.height}%;` : "";
    }

	    function renderSiteHeader() {
	      const toolLinks = SITE_TOOL_LINKS.map((link) => `
                <a href="${link.href}"${isInternalSiteUrl(link.href) ? "" : ' target="_blank" rel="noopener noreferrer"'}>${escapeHtml(link.label)}</a>
              `).join("");
	      return `
        <header class="site-header">
          <div class="site-header__inner">
            <nav class="site-nav" aria-label="Site">
