    function slideHasMainVideo(slide) {
      return Boolean(slide && (slide.kind === "video" || slide.media?.type === "video") && String(slide.media?.url || "").trim());
    }

    function demoVideoTargetIndex() {
      if (!IS_DEMO_PLAYER) return -1;
      if (slideHasMainVideo(currentSlide())) return state.ui.slideIndex;
      if (state.ui.slideIndex === 0 && slideHasMainVideo(state.tutorial.slides[1])) return 1;
      return -1;
    }

    function shouldRenderDemoVideoGate() {
      return IS_DEMO_PLAYER && !demoVideoGateDismissed && demoVideoTargetIndex() >= 0;
    }

    function renderDemoVideoSoundGate() {
      if (!shouldRenderDemoVideoGate()) return "";
      const suffix = IS_DEMO_EMBED ? " Demo" : "";
