    function isDemoCenteredSlide(slide = currentSlide()) {
      return Boolean(slide);
    }

    function demoPopupClasses(slide) {
      const hotspot = slide.hotspots.find((item) => item.id === state.ui.activeHotspotId);
      if (!hotspot) return "is-demo-popup is-empty";
      const sizeClass = Number.isFinite(hotspot.popupW) && Number.isFinite(hotspot.popupH) ? " is-custom-size" : "";
      if (Number.isFinite(hotspot.popupX) && Number.isFinite(hotspot.popupY)) return `is-demo-popup is-custom-position${sizeClass}`;
      const horizontal = hotspot.x <= 50 ? "demo-popup-right" : "demo-popup-left";
      const vertical = hotspot.y <= 50 ? "demo-popup-bottom" : "demo-popup-top";
      return `is-demo-popup ${horizontal} ${vertical}${sizeClass}`;
    }

    function demoPopupStyle(slide) {
      const hotspot = slide.hotspots.find((item) => item.id === state.ui.activeHotspotId);
      if (!hotspot) return "";
      const longestLine = Math.max(
        String(hotspot.title || "").length,
        ...String(hotspot.body || "").replace(/\r/g, "").split("\n").map((line) => line.replace(/^\s*(?:\||\d+[.)])\s?/, "").length)
      );
      const popupWidth = Number.isFinite(hotspot.popupW)
        ? `${hotspot.popupW}%`
        : `${clamp(Math.round(205 + longestLine * 5.2), 245, 440)}px`;
      const popupHeight = Number.isFinite(hotspot.popupH) ? `;--popup-height:${hotspot.popupH}%` : "";
      const position = Number.isFinite(hotspot.popupX) && Number.isFinite(hotspot.popupY)
        ? `;--popup-x:${hotspot.popupX}%;--popup-y:${hotspot.popupY}%`
        : "";
      return ` style="--popup-width:${popupWidth}${popupHeight}${position}"`;
    }

