            ${button("tb-c23-add-image-annotation-embed.png", 'data-action="select-annotation-media" data-type="image" title="Add uploaded image annotation" aria-label="Add uploaded image annotation"')}
            ${button("tb-c24-crop.png", `data-action="toggle-inserted-image-crop" title="${insertedImageCropEditing ? "Finish cropping the selected image or shape" : "Crop the selected image or shape"}" aria-label="${insertedImageCropEditing ? "Finish cropping the selected image or shape" : "Crop the selected image or shape"}" aria-pressed="${Boolean(insertedImageCropEditing)}"`, !selectedInsertedImage)}
            ${button("tb-c25-shadow.png", `data-action="toggle-inserted-image-shadow" title="Toggle a lifted shadow on the selected image, GIF, shape, circle, square, line, or arrow" aria-label="Toggle a lifted shadow on the selected image, GIF, shape, or markup annotation" aria-pressed="${insertedImageShadow}"`, !selectedShadowTarget)}
            <label class="corner-rounding-slider" title="Shadow elevation: lower to higher"><input id="shadowHeightSlider" type="range" min="0" max="40" step="1" value="${selectedShadowTarget?.shadowHeight ?? 9}" aria-label="Shadow elevation" ${selectedShadowTarget ? "" : "disabled"}><output id="shadowHeightValue">${selectedShadowTarget?.shadowHeight ?? 9}</output></label>
            <button class="toolbar-word-button" type="button" data-action="toggle-magnifier-outline" aria-pressed="${selectedMagnifierAnnotation?.outlineEnabled !== false}" ${selectedMagnifierAnnotation ? "" : "disabled"}>Outline</button>
            <label class="numbered-toolbar-corners has-corner-art" title="Curve the selected image or shape corners"><img class="numbered-toolbar-art" src="images/builder-toolbar-buttons/corners.png" alt="" aria-hidden="true"><select id="insertedImageCornerPreset" aria-label="Selected image or shape corner style" ${selectedCornerTarget ? "" : "disabled"}>${![0,3,10,50].includes(insertedImageCornerRadius) ? `<option value="${insertedImageCornerRadius}" selected>${insertedImageCornerRadius}%</option>` : ""}<option value="0" ${insertedImageCornerRadius === 0 ? "selected" : ""}>Square</option><option value="3" ${insertedImageCornerRadius === 3 ? "selected" : ""}>Soft</option><option value="10" ${insertedImageCornerRadius === 10 ? "selected" : ""}>Rounded</option><option value="50" ${insertedImageCornerRadius === 50 ? "selected" : ""}>Circle</option></select></label>
            <label class="corner-rounding-slider" title="Adjust selected image, GIF, or shape corner rounding"><input id="insertedImageCornerSlider" type="range" min="0" max="50" step="1" value="${insertedImageCornerRadius}" aria-label="Corner rounding" ${selectedCornerTarget ? "" : "disabled"}><output id="insertedImageCornerValue" for="insertedImageCornerSlider">${insertedImageCornerRadius}%</output></label>
            ${button("tb-c26-reset-image.png", 'data-action="reset-inserted-image" title="Remove cropping and curved corners from the selected image or shape" aria-label="Reset selected image"', !selectedInsertedImage)}
            ${button("tb-c28-add-interactive-link-annotation.png", 'data-action="activate-annotation-url" data-type="link" title="Place the link annotation using the URL in the box" aria-label="Place link annotation"')}
            <label class="numbered-toolbar-input" title="Paste a URL, then click the link button"><input id="annotation-link-input" value="${escapeHtml(toolbarAnnotationDraft.mode === "link" ? toolbarAnnotationDraft.value : "https://")}" aria-label="Link annotation URL" placeholder="HTTPS://"></label>
            ${button("tb-c31-add-video-pop-up-embed.png", 'data-action="select-annotation-media" data-type="video" title="Add popup video annotation for a tutorial" aria-label="Add popup video annotation for a tutorial"')}
            <label class="numbered-toolbar-input" title="Video popup title"><input id="annotation-video-label" value="${escapeHtml(toolbarAnnotationDraft.videoTitle || "")}" aria-label="Video popup title" placeholder="VIDEO POPUP TITLE"></label>
          </div>
          <datalist id="magic-hashtags-color-palette">
            ${SITE_COLOR_PRESETS.map(([value, label]) => `<option value="${value}" label="${escapeHtml(label)}"></option>`).join("")}
          </datalist>
        </section>
      `;
    }

    function renderSidebar(slide) {
      const descriptionUsesPipes = bodyHasPipeLines(slide.description);
      const descriptionUsesNumbers = bodyHasNumberedLines(slide.description);
      const baseSidebarClasses = isDemoCenteredSlide(slide)
        ? `slide-sidebar ${demoPopupClasses(slide)}`
        : "slide-sidebar";
      const activeHotspot = slide.hotspots.find((item) => item.id === state.ui.activeHotspotId);
      const scrollHotspotExpanded = slide.kind === "scroll" && scrollExpandedHotspots.get(slide.id) === activeHotspot?.id;
      const sidebarClasses = `${baseSidebarClasses}${slide.kind === "scroll" ? ` is-scroll-hotspot-panel ${scrollHotspotExpanded ? "is-expanded" : "is-collapsed"}` : ""}`;
      return `
        <aside class="${sidebarClasses}" data-hotspot-align="${escapeHtml(activeHotspot?.textAlign || "left")}" data-scroll-hotspot-state="${scrollHotspotExpanded ? "expanded" : "collapsed"}"${isDemoCenteredSlide(slide) ? demoPopupStyle(slide) : ""}>
          ${MODE === "builder" && isDemoCenteredSlide(slide) && activeHotspot ? `<div class="demo-popup-drag-handle" data-popup-drag-handle data-id="${activeHotspot.id}" title="Drag to position this hotspot text box">↕ Drag text box</div>` : ""}
          ${MODE === "builder" && isDemoCenteredSlide(slide) && activeHotspot ? renderPopupResizeHandles(activeHotspot) : ""}
          <div class="editable-box slide-sidebar__title" ${MODE === "builder" ? `contenteditable="true" role="textbox" aria-label="Slide title" data-bind="slide.title:${slide.id}"` : ""} data-placeholder="SLIDE TITLE">${renderWordText(slide, "title")}</div>
          <div class="body-field">
            ${renderBodyFormatBar("toggle-slide-pipe-list", "toggle-slide-numbered-list", slide.id, descriptionUsesPipes, descriptionUsesNumbers)}
            ${renderBody(slide.description, {
              className: "editable-box slide-sidebar__description",
              binding: `slide.description:${slide.id}`,
              label: "Slide body",
              placeholder: "Slide description.",
              listStyle: slide.descriptionListStyle
            })}
          </div>
          ${slide.hotspots.length || MODE === "builder" ? `
            <div class="sidebar-divider"></div>
            <div class="hotspot-list">
              ${slide.hotspots.map((hotspot, index) => renderHotspotRow(hotspot, index)).join("")}
              ${slide.hotspots.length || MODE !== "builder" ? "" : `<div class="sidebar-empty">${slide.kind === "cover" ? "Cover hotspots are optional. Add one from the toolbar when needed." : "Add a hotspot from the toolbar when this slide needs ordered details."}</div>`}
            </div>
          ` : ""}
        </aside>
      `;
    }

    function renderPopupResizeHandles(hotspot) {
      return ["nw", "n", "ne", "e", "se", "s", "sw", "w"]
        .map((handle) => `<span class="popup-resize-handle" data-popup-resize-handle data-handle="${handle}" data-id="${escapeHtml(hotspot.id)}" title="Resize hotspot text box" aria-hidden="true"></span>`)
        .join("");
    }

    function renderHotspotRow(hotspot, index) {
      const active = state.ui.activeHotspotId === hotspot.id;
      const titleId = `hotspotTitle-${hotspot.id}`;
      const detailId = `hotspotDetail-${hotspot.id}`;
      const style = hotspotStyle(index);
      return `
        <div class="hotspot-entry ${active ? "is-active" : ""}" data-id="${hotspot.id}">
          <div class="hotspot-row ${active ? "is-active" : ""}" style="--hotspot-color:${style.color}" data-action="activate-hotspot" data-id="${hotspot.id}" aria-expanded="${active}" aria-controls="${detailId}" ${MODE === "player" ? `role="button" tabindex="0" aria-label="Open ${escapeHtml(hotspot.title || `Hotspot ${index + 1}`)} details"` : ""}>
            <div class="hotspot-row__title" id="${titleId}" ${MODE === "builder" ? `contenteditable="true" role="textbox" aria-label="Hotspot ${index + 1} title" data-bind="hotspot.title:${hotspot.id}"` : ""}>${escapeHtml(hotspot.title || `HOTSPOT ${index + 1}`)}</div>
            ${MODE === "builder" ? `<button type="button" data-action="hotspot-row-up" data-id="${hotspot.id}" aria-label="Move ${escapeHtml(hotspot.title)} title and body up; keep hotspot ${index + 1} marker fixed" ${index > 0 ? "" : "disabled"}>${icon("up")}</button><button type="button" data-action="hotspot-row-down" data-id="${hotspot.id}" aria-label="Move ${escapeHtml(hotspot.title)} title and body down; keep hotspot ${index + 1} marker fixed" ${index < currentSlide().hotspots.length - 1 ? "" : "disabled"}>${icon("down")}</button>` : ""}
          </div>
          ${active ? renderHotspotDetail(hotspot) : ""}
        </div>
      `;
    }

    function renderHotspotDetail(hotspot) {
      const titleId = `hotspotTitle-${hotspot.id}`;
      const detailId = `hotspotDetail-${hotspot.id}`;
      const label = `${hotspot.title || "Hotspot"} details`;
      const detail = renderBody(hotspot.body, {
        className: "hotspot-detail",
        binding: `hotspot.body:${hotspot.id}`,
        label,
        placeholder: "Type hotspot details here.",
        listStyle: hotspot.bodyListStyle
      });
      if (MODE !== "builder") {
        return `<div class="hotspot-detail-panel" id="${detailId}" role="region" aria-labelledby="${titleId}" aria-live="polite" data-action="activate-hotspot" data-id="${hotspot.id}" tabindex="0">${detail}</div>`;
      }
      return `
        <div class="hotspot-detail-panel" id="${detailId}" aria-live="polite">
          ${renderBodyFormatBar("toggle-hotspot-pipe-list", "toggle-hotspot-numbered-list", hotspot.id, bodyHasPipeLines(hotspot.body), bodyHasNumberedLines(hotspot.body))}
          ${detail}
        </div>
      `;
    }

    function renderStage(slide) {
      const orderedAnnotations = topLevelAnnotations(slide).slice().sort((a,b) => a.z - b.z).filter(isVisibleForActiveHotspot).map(renderAnnotation).join("");
      const visibleHotspots = slide.hotspots.map((hotspot, index) => isHotspotVisibleForActiveState(hotspot, slide) ? renderHotspot(hotspot, index) : "").join("");
      const stageContent = slide.kind === "scroll"
        ? `<div class="scroll-slide-viewport" data-scroll-slide="${escapeHtml(slide.id)}" tabindex="0" aria-label="Scrollable ${escapeHtml(slide.title || "page")}">
            <div class="scroll-slide-content">
              ${renderScrollMainMedia(slide)}
              ${orderedAnnotations}
              ${visibleHotspots}
            </div>
          </div>
          <button class="scroll-slide-caret" type="button" data-action="scroll-page-down" aria-label="Scroll down" title="Scroll down" hidden aria-hidden="true">⌄</button>`
        : `${renderMainMedia(slide)}${orderedAnnotations}${visibleHotspots}`;
      return `
        <div class="stage-wrap">
          <div class="stage has-slide-background" data-stage data-scene-coordinate-system="${SCENE_COORDINATE_SYSTEM}" data-media-fit="${escapeHtml(slide.media.fit)}" style="--stage-matte:${escapeHtml(slide.media.matte)};--media-aspect:${SCENE_WIDTH} / ${SCENE_HEIGHT};--scroll-viewport-width:${slide.scrollViewportWidth || 100}%">
            ${stageContent}
            ${renderSlideNarrationControl(slide)}
            ${renderDemoVideoSoundGate()}
          </div>
        </div>
      `;
    }

    function renderDeviceFrame() {
      return `<div class="slide-device-frame" aria-hidden="true"><img src="${DEVICE_FRAME_URL}" alt="" loading="eager" decoding="async"></div>`;
    }

    function renderBrowserHeader(slide) {
      const url = String(slide.browserUrl || "");
      const gptName = String(slide.gptName || "");
      const urlField = MODE === "builder"
        ? `<input class="slide-browser-field slide-browser-url" type="text" value="${escapeHtml(url)}" placeholder="ENTER URL" data-browser-field="browserUrl" aria-label="Browser URL for this slide">`
        : `<div class="slide-browser-field slide-browser-url">${escapeHtml(url)}</div>`;
      const nameField = MODE === "builder"
        ? `<input class="slide-browser-field slide-browser-gpt-name" type="text" value="${escapeHtml(gptName)}" placeholder="ENTER GPT NAME" data-browser-field="gptName" aria-label="GPT name for this slide">`
        : `<div class="slide-browser-field slide-browser-gpt-name">${escapeHtml(gptName)}</div>`;
      return `<div class="slide-browser-header" data-fixed-browser-header>
        <div class="slide-browser-address"><img src="${DEVICE_ADDRESS_BAR_URL}" alt="" loading="eager" decoding="async">${urlField}</div>
        <div class="slide-browser-gpt-row">${nameField}</div>
      </div>`;
    }

    function renderSlideNarrationControl(slide) {
      if (MODE !== "builder") return "";
      const audioUrl = String(slide.demo?.audioUrl || "").trim();
      const hasAudio = Boolean(audioUrl);
      const isOpen = slideNarrationPanelSlideId === slide.id;
      const isPlaying = slideNarrationPreviewPlaying && slideNarrationPreviewSlideId === slide.id;
      const filename = mediaDisplayFilename(audioUrl);
      return `
        <div class="slide-narration-control" data-builder-only>
          <button type="button" class="slide-narration-badge ${hasAudio ? "has-audio" : ""}" data-action="toggle-slide-audio-panel" aria-label="${hasAudio ? "Open slide narration controls" : "Add slide narration audio"}" aria-expanded="${isOpen}" title="${hasAudio ? `Narration attached: ${escapeHtml(filename)}` : "No slide narration attached"}">
            ${icon("audio")}
            ${hasAudio ? '<span class="slide-narration-badge-dot" aria-hidden="true"></span>' : ""}
          </button>
          ${isOpen ? `
            <div class="slide-narration-popover" role="dialog" aria-label="Slide narration controls">
              <strong>Slide narration</strong>
              ${hasAudio
                ? `<span class="slide-narration-filename" title="${escapeHtml(filename)}">${escapeHtml(filename)}</span>`
                : '<span class="slide-narration-filename">No narration attached</span>'}
              <div class="slide-narration-actions">
                ${hasAudio ? `<button type="button" data-action="toggle-slide-audio-preview">${isPlaying ? "Pause" : "Play / Replay"}</button>` : ""}
                <button type="button" data-action="select-slide-audio">${hasAudio ? "Replace" : "Add Audio"}</button>
                ${hasAudio ? '<button type="button" data-action="remove-slide-audio">Remove</button>' : ""}
              </div>
            </div>
          ` : ""}
        </div>
      `;
    }

    function renderMainMediaControls(slide, className = "") {
      return `
        <div class="stage-media-controls ${escapeHtml(className)}" data-builder-only aria-label="Main image controls">
          <button type="button" data-action="media-fit" data-value="match" class="${slide.media.fit === "match" ? "is-active" : ""}">Match</button>
          <button type="button" data-action="media-fit" data-value="contain" class="${slide.media.fit === "contain" ? "is-active" : ""}">Contain</button>
          <button type="button" data-action="media-fit" data-value="cover" class="${slide.media.fit === "cover" ? "is-active" : ""}">Cover</button>
          <button class="icon-button" type="button" data-action="media-up" title="Move media up" aria-label="Move media up">${icon("up")}</button>
          <button class="icon-button" type="button" data-action="media-down" title="Move media down" aria-label="Move media down">${icon("down")}</button>
          <button class="icon-button" type="button" data-action="media-left" title="Move media left" aria-label="Move media left">${icon("left")}</button>
          <button class="icon-button" type="button" data-action="media-right" title="Move media right" aria-label="Move media right">${icon("right")}</button>
          <button class="icon-button" type="button" data-action="media-zoom-in" title="Zoom media in" aria-label="Zoom media in">${icon("zoomIn")}</button>
          <button class="icon-button" type="button" data-action="media-zoom-out" title="Zoom media out" aria-label="Zoom media out">${icon("zoomOut")}</button>
          <button class="icon-button" type="button" data-action="media-reset" title="Reset media position and size" aria-label="Reset media position and size">${icon("reset")}</button>
        </div>`;
    }

    function isHotspotVisibleForActiveState(hotspot, slide = currentSlide()) {
      if (isSlideIntroState(slide)) return false;
      if (slide?.kind === "scroll") return true;
      const activeId = slide.hotspots.some((item) => item.id === state.ui.activeHotspotId)
        ? state.ui.activeHotspotId
        : slide.hotspots[0]?.id || null;
      if (hotspot.id === activeId) return true;
      if (!hotspot.locked) return false;
      const hotspotIndex = slide.hotspots.findIndex((item) => item.id === hotspot.id);
      const activeIndex = slide.hotspots.findIndex((item) => item.id === activeId);
      return hotspotIndex >= 0 && activeIndex >= hotspotIndex;
    }

    function isVisibleForActiveHotspot(item) {
      if (item.type === "slide-intro") return isSlideIntroState();
      if (currentSlide()?.kind === "video") return true;
      if (!item.hotspotGroupId) return true;
      if (item.hotspotGroupId === state.ui.activeHotspotId) return true;
      if (!item.locked || isSlideIntroState()) return false;
      const slide = currentSlide();
      const placedIndex = slide.hotspots.findIndex((hotspot) => hotspot.id === item.hotspotGroupId);
      const activeIndex = slide.hotspots.findIndex((hotspot) => hotspot.id === state.ui.activeHotspotId);
      return placedIndex >= 0 && activeIndex >= placedIndex;
    }

    function renderMainMedia(slide) {
      const media = slide.media;
      const objectFit = media.fit === "match" ? "contain" : media.fit;
      const hasTransform = Math.abs(media.x) > .001 || Math.abs(media.y) > .001 || Math.abs(media.scale - 1) > .001;
      const naturalSizeStyle = media.naturalWidth > 0 && media.naturalHeight > 0
        ? `;--media-natural-width:${media.naturalWidth}px;--media-natural-height:${media.naturalHeight}px`
        : "";
      const style = `--media-fit:${objectFit};--media-x:${media.x}%;--media-y:${media.y}%;--media-scale:${media.scale}${naturalSizeStyle}`;
      const layerClass = slide.kind === "video" ? "media-layer main-video-frame" : "media-layer";
      const layerStart = `<div class="${layerClass}" data-fit="${media.fit}" data-has-transform="${hasTransform}" style="${style}">`;
      const mediaKind = slide.kind === "video" || media.type === "video"
        ? "Video"
        : media.type === "audio" ? "Audio" : "Image";
      const failure = `<div class="media-placeholder" data-main-media-error hidden>${mediaKind} link could not be loaded. Check that it opens the media file directly.</div>`;
      if (!media.url) return `${layerStart}<div class="media-placeholder">${slide.kind === "video" ? "Video media box" : "Image media box"}</div></div>`;
      if (slide.kind === "video" || media.type === "video") {
        const preload = MODE === "player" ? "auto" : "metadata";
        const demoAttributes = IS_DEMO_PLAYER ? " muted loop" : "";
        const videoControls = IS_DEMO_PLAYER
          ? ""
          : `<div class="main-video-controls" aria-label="Video controls"><button class="icon-button" type="button" data-action="toggle-main-video" aria-label="Play video">${icon("play")}</button><input type="range" min="0" max="0" step="0.05" value="0" data-main-video-timeline aria-label="Video timeline" aria-valuetext="0:00 of 0:00"></div>`;
        return `${layerStart}${failure}<video data-main-video src="${escapeHtml(media.url)}" playsinline preload="${preload}"${demoAttributes} aria-label="${escapeHtml(slide.title || "Tutorial video")}" onloadedmetadata="this.hidden=false;this.previousElementSibling.hidden=true;this.closest('.main-video-frame')?.classList.remove('has-media-error')" onerror="this.hidden=true;this.previousElementSibling.hidden=false;this.closest('.main-video-frame')?.classList.add('has-media-error')"></video>${videoControls}</div>`;
      }
      if (media.type === "audio") {
        return `${layerStart}${failure}<audio src="${escapeHtml(media.url)}" controls preload="metadata" aria-label="${escapeHtml(slide.title || "Tutorial audio")}" onloadedmetadata="this.hidden=false;this.previousElementSibling.hidden=true" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></audio></div>`;
      }
      const sizeAttributes = media.naturalWidth > 0 && media.naturalHeight > 0
        ? ` width="${media.naturalWidth}" height="${media.naturalHeight}"`
        : "";
      return `${layerStart}${failure}<img data-main-media-image data-slide-id="${escapeHtml(slide.id)}" src="${escapeHtml(media.url)}" alt="${escapeHtml(slide.title || "Tutorial image")}"${sizeAttributes} loading="eager" decoding="async" onload="this.hidden=false;this.previousElementSibling.hidden=true" onerror="this.hidden=true;this.previousElementSibling.hidden=false"></div>`;
    }

    function renderScrollMainMedia(slide) {
      const media = slide.media;
      const failure = `<div class="media-placeholder" data-main-media-error ${media.url ? "hidden" : ""}>${media.url ? "Scroll-page image link could not be loaded. Check that it opens the image directly." : "Choose a tall image for this scroll slide."}</div>`;
      if (!media.url) return failure;
      const sizeAttributes = media.naturalWidth > 0 && media.naturalHeight > 0
        ? ` width="${media.naturalWidth}" height="${media.naturalHeight}"`
        : "";
      const layerStyle = `--scroll-media-width:${media.scale * 100}%;--scroll-media-x:${media.x}cqw;--scroll-media-y:${media.y * SCENE_HEIGHT / SCENE_WIDTH}cqw`;
      const sharedImage = `class="scroll-slide-page-image" src="${escapeHtml(media.url)}"${sizeAttributes} loading="eager" decoding="async"`;
      return `${failure}
        <div class="scroll-slide-page-layer" style="${layerStyle}">
          <img ${sharedImage} data-main-media-image data-slide-id="${escapeHtml(slide.id)}" alt="${escapeHtml(slide.title || "Scrollable tutorial page")}" onload="this.hidden=false;this.closest('.scroll-slide-content')?.querySelector('[data-main-media-error]')?.setAttribute('hidden','')" onerror="this.hidden=true;this.closest('.scroll-slide-content')?.querySelector('[data-main-media-error]')?.removeAttribute('hidden')">
        </div>`;
    }

    function renderHotspot(hotspot, index) {
      const selected = isObjectSelected("hotspot", hotspot.id);
      const primary = state.ui.selectedKind === "hotspot" && state.ui.selectedId === hotspot.id;
      const active = state.ui.activeHotspotId === hotspot.id;
      const grouped = Boolean(hotspot.hotspotGroupId);
      const style = hotspotStyle(index);
      return `
        <div class="stage-object hotspot-object ${selected ? "is-selected" : ""} ${active ? "is-active" : ""} ${hotspot.locked ? "is-locked" : ""} ${grouped ? "is-grouped" : ""}"
          data-object data-kind="hotspot" data-id="${hotspot.id}" data-action="activate-hotspot"
          role="button" tabindex="0" aria-label="Open ${escapeHtml(hotspot.title || `Hotspot ${index + 1}`)} details"
          style="${objectStyle(hotspot)};--hotspot-color:${style.color}" data-hotspot-style="${escapeHtml(style.name)}">
          <div class="object-frame"><span class="hotspot-art-fallback" aria-hidden="true"></span><img src="${style.image}" alt="" loading="eager" onload="this.hidden=false;this.parentElement.classList.remove('has-missing-hotspot-art')" onerror="this.hidden=true;this.parentElement.classList.add('has-missing-hotspot-art')"><span class="hotspot-number">${index + 1}</span></div>
          ${primary && !hotspot.locked ? renderHandles() : ""}
        </div>
      `;
    }

    function renderAnnotation(annotation) {
      const selected = isObjectSelected("annotation", annotation.id);
      const primary = state.ui.selectedKind === "annotation" && state.ui.selectedId === annotation.id;
      const audioIsPlaying = annotation.type === "audio" && activeAudio === annotation.id && audioPlaying;
      const grouped = Boolean(annotation.hotspotGroupId);
      const cropEnabled = isCroppableAnnotation(annotation) && annotation.cropEnabled;
      const cropEditing = isCroppableAnnotation(annotation) && imageCropEditId === annotation.id;
      const imageShadow = isShadowableAnnotation(annotation) && annotation.imageShadow;
      const clippedMember = Boolean(clipFrameForMember(annotation));
      const classes = `stage-object annotation-${annotation.type} ${["video","link"].includes(annotation.type) ? "annotation-trigger" : ""} ${audioIsPlaying ? "is-playing" : ""} ${selected ? "is-selected" : ""} ${annotation.locked ? "is-locked" : ""} ${grouped ? "is-grouped" : ""} ${cropEnabled ? `is-crop-enabled ${annotation.cropWindow ? "has-crop-window" : ""}` : ""} ${cropEditing ? "is-crop-editing" : ""} ${imageShadow ? "has-image-shadow" : ""} ${clippedMember ? "is-clipped-member" : ""}`;
      let content = "";
      if (["shape","image","gif"].includes(annotation.type)) {
        content = `<div class="object-frame annotation-asset-frame">${renderAnnotationAssetImage(annotation.src, annotation.label || "Annotation", "eager")}</div>`;
      } else if (annotation.type === "slide-intro") {
        content = `<div class="object-frame slide-intro-card">
          ${MODE === "builder" ? '<span class="card-top-drag-handle" data-handle="move" title="Drag this intro card" aria-label="Drag this intro card"></span>' : ""}
          ${MODE === "builder" ? `<label class="slide-intro-card__title-only-toggle" data-builder-only><input type="checkbox" data-action="toggle-intro-title-only" data-id="${escapeHtml(annotation.id)}" aria-label="Show only the intro title" ${annotation.introTitleOnly ? "checked" : ""}>Title only</label>` : ""}
          <div class="slide-intro-card__title" ${MODE === "builder" ? `contenteditable="true" role="textbox" aria-label="Slide intro title" data-bind="annotation.introTitle:${annotation.id}"` : ""}>${renderWordText(annotation, "introTitle")}</div>
          ${annotation.introTitleOnly ? "" : `<div class="slide-intro-card__body-field">
            ${renderBodyFormatBar("toggle-intro-pipe-list", "toggle-intro-numbered-list", annotation.id, bodyHasPipeLines(annotation.introBody), bodyHasNumberedLines(annotation.introBody), `<button type="button" class="body-list-toggle ${annotation.introBodyAlign === "left" ? "is-active" : ""}" data-action="toggle-intro-body-left" data-id="${annotation.id}" aria-pressed="${annotation.introBodyAlign === "left"}" title="Left-align only the body; click again to follow the title alignment">Body left</button>`)}
            ${renderBody(annotation.introBody, {
              className: "slide-intro-card__body",
              binding: `annotation.introBody:${annotation.id}`,
              label: "Slide intro body",
              placeholder: "Add the introductory text for this slide."
            })}
          </div>`}
        </div>`;
      } else if (annotation.type === "callout") {
        content = `<div class="object-frame standalone-callout-card">
          ${MODE === "builder" ? '<span class="card-top-drag-handle" data-handle="move" title="Drag this callout" aria-label="Drag this callout"></span>' : ""}
          <div class="standalone-callout-card__title" ${MODE === "builder" ? `contenteditable="true" role="textbox" aria-label="Callout title" data-bind="annotation.calloutTitle:${annotation.id}"` : ""}>${renderWordText(annotation, "calloutTitle")}</div>
          <div class="standalone-callout-card__body-field">
            ${renderBodyFormatBar("toggle-callout-pipe-list", "toggle-callout-numbered-list", annotation.id, bodyHasPipeLines(annotation.calloutBody), bodyHasNumberedLines(annotation.calloutBody))}
            ${renderBody(annotation.calloutBody, {
              className: "standalone-callout-card__body",
              binding: `annotation.calloutBody:${annotation.id}`,
              label: "Callout body",
              placeholder: "Add callout text."
            })}
          </div>
        </div>`;
      } else if (annotation.type === "cover") {
        content = `<div class="object-frame" role="img" aria-label="${escapeHtml(annotation.label || "Cover area")}"></div>`;
      } else if (annotation.type === "blur") {
        content = `<div class="object-frame" role="img" aria-label="${escapeHtml(annotation.label || "Blurred area")}"></div>`;
      } else if (annotation.type === "text") {
        content = `<div class="object-frame" ${MODE === "builder" ? `contenteditable="true" role="textbox" aria-label="Annotation text" data-bind="annotation.text:${annotation.id}"` : ""} style="color:${escapeHtml(annotation.textColor)}">${renderWordText(annotation, "text")}</div>`;
      } else if (annotation.type === "markup") {
        content = `<div class="object-frame markup-frame">${markupSvg(annotation)}</div>`;
      } else if (annotation.type === "magnifier") {
        content = `<div class="object-frame magnifier-viewport" role="img" aria-label="Magnified area">
          <span class="magnifier-scene-host" data-magnifier-scene-host aria-hidden="true"></span>
        </div>
        ${primary && MODE === "builder" ? `<div class="magnifier-controls" data-builder-only aria-label="Magnifier controls">
          <button type="button" data-action="adjust-magnifier" data-delta="-0.25" title="Reduce magnification" aria-label="Reduce magnification">−</button>
          <output aria-label="Current magnification">${Number(annotation.magnification || 2).toFixed(2).replace(/0+$/, "").replace(/\.$/, "")}×</output>
          <button type="button" data-action="adjust-magnifier" data-delta="0.25" title="Increase magnification" aria-label="Increase magnification">+</button>
        </div>` : ""}`;
      } else if (annotation.type === "clip-frame") {
        const members = clipFrameMembers(annotation)
          .slice()
          .sort((a, b) => a.z - b.z)
          .filter(isVisibleForActiveHotspot)
          .map(renderAnnotation)
          .join("");
        content = `<div class="object-frame clip-frame-viewport" role="group" aria-label="Clipped frame contents">
          <div class="clip-frame-scene" style="${clipFrameSceneStyle(annotation)}">${members}</div>
        </div>
        ${primary && MODE === "builder" ? `<div class="clip-frame-controls" data-builder-only aria-label="Clip frame controls">
          <button type="button" data-action="set-clip-frame-shape" data-value="straight" aria-pressed="${annotation.clipFrameShape === "straight"}">Straight</button>
          <button type="button" data-action="set-clip-frame-shape" data-value="rounded" aria-pressed="${annotation.clipFrameShape === "rounded"}">Rounded</button>
          <button type="button" data-action="release-clip-frame" title="Remove the frame but keep its contents">Release</button>
        </div>` : ""}`;
      } else if (annotation.type === "video") {
        content = `<div class="object-frame annotation-asset-frame">${renderAnnotationAssetImage(VIDEO_ANNOTATION_IMAGE, annotation.label || "Play video")}</div>`;
      } else if (annotation.type === "link") {
        content = MODE === "player"
          ? `<div class="object-frame annotation-asset-frame"><a href="${escapeHtml(annotation.url)}" target="_blank" rel="noopener noreferrer" aria-label="${escapeHtml(annotation.label || "Open external link")}">${renderAnnotationAssetImage(LINK_ANNOTATION_IMAGE, annotation.label || "Open link")}</a></div>`
          : `<div class="object-frame annotation-asset-frame">${renderAnnotationAssetImage(LINK_ANNOTATION_IMAGE, annotation.label || "Open link")}</div>`;
      } else {
        const liveAudio = audioIsPlaying ? window.__tutorialAudio : null;
        const duration = liveAudio && Number.isFinite(liveAudio.duration) ? liveAudio.duration : 0;
        const currentTime = liveAudio ? clamp(liveAudio.currentTime, 0, duration || 0) : 0;
        content = `<div class="object-frame annotation-asset-frame">
          ${renderAnnotationAssetImage(audioIsPlaying ? AUDIO_PAUSE_IMAGE : AUDIO_PLAY_IMAGE, audioIsPlaying ? "Pause audio" : "Play audio")}
          <button type="button" class="audio-image-control audio-image-control--toggle" data-action="toggle-audio" data-id="${annotation.id}" aria-label="${audioIsPlaying ? "Pause" : "Play"} audio" aria-pressed="${audioIsPlaying}"></button>
          ${audioIsPlaying ? `<div class="audio-timeline-wrap">
            <input type="range" min="0" max="${duration}" step="0.05" value="${currentTime}" data-audio-timeline data-id="${annotation.id}" aria-label="Audio timeline" aria-valuetext="${formatVideoTime(currentTime)} of ${formatVideoTime(duration)}">
          </div>` : ""}
        </div>`;
      }
      return `
        <div class="${classes}" data-object data-kind="annotation" data-id="${annotation.id}" data-text-style="${annotation.textStyle}" ${annotation.type === "magnifier" ? `data-magnifier-lens data-magnifier-z="${annotation.z}"` : ""} ${annotation.type === "clip-frame" ? "data-clip-frame" : ""} ${annotation.type === "slide-intro" ? `data-intro-align="${escapeHtml(annotation.introAlign)}" data-intro-body-align="${annotation.introBodyAlign || "inherit"}" data-intro-title-only="${Boolean(annotation.introTitleOnly)}"` : ""} ${annotation.type === "callout" ? `data-callout-align="${escapeHtml(annotation.calloutAlign)}"` : ""} ${annotation.type === "markup" ? `data-markup-kind="${escapeHtml(annotation.markup)}"` : ""} ${annotation.type === "video" ? `role="button" tabindex="0" aria-label="Open ${escapeHtml(annotation.label || "video")}"` : ""} ${MODE === "builder" && annotation.type === "video" ? 'title="Click once to select; click the selected video again to preview"' : ""} style="${objectStyle(annotation)}">
          ${content}
          ${primary && !annotation.locked ? renderHandles(annotation) : ""}
        </div>
      `;
    }

    function markupCornerRadii(annotation) {
      const radius = clamp(annotation.markupCornerRadius ?? 0, 0, 43);
      const renderedWidth = Math.max(.01, (Number(annotation.w) || 1) * SCENE_ASPECT);
      const renderedHeight = Math.max(.01, Number(annotation.h) || 1);
      const shorterSide = Math.min(renderedWidth, renderedHeight);
      return {
        rx: Math.round(radius * shorterSide / renderedWidth * 1000) / 1000,
        ry: Math.round(radius * shorterSide / renderedHeight * 1000) / 1000
      };
    }

    function applyLiveMarkupCornerRadii(annotation, element) {
      if (!element || !normalizeMarkupKind(annotation.markup).startsWith("square-")) return;
      const { rx, ry } = markupCornerRadii(annotation);
      element.querySelectorAll('[data-markup-square="true"]').forEach((rectangle) => {
        rectangle.setAttribute("rx", String(rx));
        rectangle.setAttribute("ry", String(ry));
      });
    }

    function markupSvg(annotation) {
      const kind = normalizeMarkupKind(annotation.markup);
      const filledWithBorder = kind.endsWith("-fill-solid") || kind.endsWith("-fill-dashed");
      const filled = kind.endsWith("-fill") || filledWithBorder;
      const dashed = kind.endsWith("-dotted") || kind.endsWith("-fill-dashed");
      const dash = dashed ? ' stroke-dasharray="8 7"' : "";
      const fill = filledWithBorder ? "var(--markup-fill-color, #ffffff)" : "var(--markup-color, #000000)";
      const { rx: cornerRadiusX, ry: cornerRadiusY } = markupCornerRadii(annotation);
      if (kind.startsWith("square-")) {
        return filled
          ? `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><rect data-markup-square="true" x="7" y="7" width="86" height="86" rx="${cornerRadiusX}" ry="${cornerRadiusY}" fill="${fill}" stroke="${filledWithBorder ? "var(--markup-color, #000000)" : "none"}" stroke-linejoin="round"${filledWithBorder ? dash : ""}/></svg>`
          : `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><rect data-markup-square="true" x="7" y="7" width="86" height="86" rx="${cornerRadiusX}" ry="${cornerRadiusY}" fill="none" stroke="var(--markup-color, #000000)" stroke-linejoin="round"${dash}/></svg>`;
      }
      if (kind.startsWith("circle-")) {
        return filled
          ? `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><ellipse cx="50" cy="50" rx="43" ry="43" fill="${fill}" stroke="${filledWithBorder ? "var(--markup-color, #000000)" : "none"}"${filledWithBorder ? dash : ""}/></svg>`
          : `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><ellipse cx="50" cy="50" rx="43" ry="43" fill="none" stroke="var(--markup-color, #000000)"${dash}/></svg>`;
      }
      const path = markupPath(annotation);
      if (kind.startsWith("arrow-")) {
        const markerId = uid("arrowhead");
        return `<svg data-arrow-points="${escapeHtml(JSON.stringify(normalizeMarkupPoints(annotation.markupPoints, annotation.markup)))}" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="${markerId}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto" markerUnits="strokeWidth" overflow="visible"><path d="M1 1 L9 5 L1 9" fill="none" stroke="var(--markup-color, #000000)" stroke-linecap="round" stroke-linejoin="round" style="stroke-width:1.45;vector-effect:none"/></marker></defs><path data-markup-primary="true" d="${path}" fill="none" stroke="var(--markup-color, #000000)" stroke-linecap="round"${dash} marker-end="url(#${markerId})"/></svg>`;
      }
      return `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path data-markup-primary="true" d="${path}" fill="none" stroke="var(--markup-color, #000000)" stroke-linecap="round"${dash}/></svg>`;
    }

    // Draw arrow geometry in CSS pixels, so non-square boxes cannot stretch the head.
    function updateArrowGeometry(svg) {
      const width = svg.clientWidth;
      const height = svg.clientHeight;
      if (!width || !height) return;
      const points = JSON.parse(svg.dataset.arrowPoints);
      const xy = (point) => `${point.x * width / 100} ${point.y * height / 100}`;
      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
      svg.querySelector('[data-markup-primary="true"]').setAttribute("d",
        `M ${xy(points.start)} Q ${xy(points.curve)} ${xy(points.end)}`);
    }

    function observeArrowGeometry() {
      if (!observeArrowGeometry.observer) {
        observeArrowGeometry.observer = new ResizeObserver((entries) => {
          entries.forEach(({ target }) => updateArrowGeometry(target));
        });
      }
      const observer = observeArrowGeometry.observer;
      observer.disconnect();
      root.querySelectorAll("svg[data-arrow-points]").forEach((svg) => {
        updateArrowGeometry(svg);
        observer.observe(svg);
      });
    }

    function markupPath(annotation) {
      const points = normalizeMarkupPoints(annotation.markupPoints, annotation.markup);
      return `M ${points.start.x} ${points.start.y} Q ${points.curve.x} ${points.curve.y} ${points.end.x} ${points.end.y}`;
    }

    function syncSelectionControls() {
      if (MODE !== "builder") return;
      root.querySelectorAll("[data-object].is-selected").forEach((object) => {
        const frame = object.querySelector(":scope > .object-frame");
        const stage = object.closest("[data-stage]");
        if (!frame || !stage || !object.offsetWidth || !object.offsetHeight) return;
        const box = object.getBoundingClientRect();
        const item = object.dataset.kind === "hotspot"
          ? currentSlide().hotspots.find(i => i.id === object.dataset.id)
          : currentSlide().annotations.find(i => i.id === object.dataset.id);
        let left = 0, top = 0, width = object.offsetWidth, height = object.offsetHeight;
        // Tighten the editing controls only; do not rewrite saved sizes or artwork.
        if (!item?.rotation) {
          if (item?.type === "text" && !String(item.textStyle).startsWith("impact-label") && frame.textContent.trim()) {
            const range = document.createRange();
            range.selectNodeContents(frame);
            const ink = range.getBoundingClientRect();
            if (ink.width && ink.height) {
              left = Math.max(0, (ink.left - box.left) * object.offsetWidth / box.width - 4);
              top = Math.max(0, (ink.top - box.top) * object.offsetHeight / box.height - 4);
              width = Math.min(object.offsetWidth - left, ink.width * object.offsetWidth / box.width + 8);
              height = Math.min(object.offsetHeight - top, ink.height * object.offsetHeight / box.height + 8);
            }
          } else {
            const img = frame.querySelector(":scope > img");
            if (img?.naturalWidth && img.naturalHeight && getComputedStyle(img).objectFit === "contain" && !item?.cropEnabled) {
              const scale = Math.min(width / img.naturalWidth, height / img.naturalHeight);
              const iw = img.naturalWidth * scale, ih = img.naturalHeight * scale;
              left = (width - iw) / 2; top = (height - ih) / 2; width = iw; height = ih;
            }
          }
        }
        object.style.setProperty("--selection-left", left + "px");
        object.style.setProperty("--selection-top", top + "px");
        object.style.setProperty("--selection-width", width + "px");
        object.style.setProperty("--selection-height", height + "px");
        object.querySelectorAll(":scope > .resize-handle").forEach(handle => {
          const name = handle.dataset.handle;
          const x = left + (name.includes("w") ? 0 : name.includes("e") ? width : width / 2);
          const y = top + (name.includes("n") ? 0 : name.includes("s") ? height : height / 2);
          Object.assign(handle.style, { left: x + "px", top: y + "px", right: "auto", bottom: "auto", transform: "translate(-50%, -50%)" });
        });
        const stageBox = stage.getBoundingClientRect();
        object.querySelectorAll(":scope > .move-handle").forEach(handle => {
          const hw = handle.offsetWidth;
          let x = handle.classList.contains("move-handle--left") ? left - hw - 10 : left + width + 10;
          if (!item?.rotation) {
            const sx = box.width / object.offsetWidth;
            const low = (Math.max(4, stageBox.left + 4) - box.left) / sx;
            const high = (Math.min(innerWidth - 4, stageBox.right - 4) - box.left) / sx - hw;
            x = Math.max(low, Math.min(x, high));
          }
          Object.assign(handle.style, { left: x + "px", right: "auto", top: (top + height / 2) + "px", bottom: "auto" });
        });
      });
    }

    function renderHandles(item = null) {
      const resizeHandles = item
        ? ["nw","n","ne","e","se","s","sw","w"]
        : ["nw","ne","sw","se"];
      const resize = resizeHandles.map((handle) => `<span class="resize-handle" data-handle="${handle}" aria-hidden="true"></span>`).join("");
      const markupPoints = item?.type === "markup" && isPathMarkup(item.markup)
        ? normalizeMarkupPoints(item.markupPoints, item.markup)
        : null;
      const bend = markupPoints ? `
        <span class="markup-point-handle" data-handle="markup-start" style="left:${markupPoints.start.x}%;top:${markupPoints.start.y}%" aria-hidden="true"></span>
        <span class="markup-point-handle markup-point-handle--bend" data-handle="markup-curve" style="left:${markupPoints.curve.x}%;top:${markupPoints.curve.y}%" aria-hidden="true"></span>
        <span class="markup-point-handle" data-handle="markup-end" style="left:${markupPoints.end.x}%;top:${markupPoints.end.y}%" aria-hidden="true"></span>
      ` : "";
      const rotate = ["shape", "text", "slide-intro", "callout"].includes(item?.type)
        || (item?.type === "markup" && isRotatableMarkup(item.markup))
        ? `<span class="rotate-handle" data-handle="rotate" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="miter"><path d="M20 7V3m0 0h-4m4 0-4 4a7 7 0 1 0 2 7"/></svg></span>`
        : "";
      const flip = item?.type === "shape"
        ? `<button type="button" class="flip-handle ${item.flipX ? "is-active" : ""}" data-action="flip-shape" data-id="${escapeHtml(item.id)}" title="Flip shape side to side" aria-label="Flip shape horizontally" aria-pressed="${Boolean(item.flipX)}">${icon("flipHorizontal")}</button>`
        : "";
      const leftMove = '<span class="move-handle move-handle--left" data-handle="move" aria-hidden="true">Move</span>';
      return `${resize}${bend}${rotate}${flip}${leftMove}<span class="move-handle" data-handle="move" aria-hidden="true">Move</span>`;
    }

    function atBeginning() {
      const slide = currentSlide();
      if (state.ui.slideIndex > 0) return false;
      return !slide.hotspots.length || !state.ui.activeHotspotId || slide.hotspots[0]?.id === state.ui.activeHotspotId;
    }

    function atEnd() {
      const slide = currentSlide();
      if (state.ui.slideIndex < state.tutorial.slides.length - 1) return false;
      const lastHotspot = slide.hotspots[slide.hotspots.length - 1];
      return !slide.hotspots.length || lastHotspot?.id === state.ui.activeHotspotId;
    }

    function readerBackLabel() {
      return "Back";
    }

    function readerNextLabel() {
      return "Next";
    }

    function renderReaderNav() {
      return `
        <nav class="reader-nav" aria-label="Tutorial navigation">
          <button class="nav-button" type="button" data-action="reader-back" ${atBeginning() ? "disabled" : ""}>${readerBackLabel()}</button>
          <button class="contents-button" type="button" data-action="open-contents" aria-haspopup="dialog" aria-label="Menu">${icon("contents")}<span>Menu</span></button>
          <button class="nav-button" type="button" data-action="reader-next" ${atEnd() ? "disabled" : ""}>${readerNextLabel()}</button>
        </nav>
      `;
    }

    function renderDemoPlaybackControls() {
      const videoSlide = slideHasMainVideo(currentSlide());
      const playLabel = demoStarted && demoPlaying ? "Pause" : demoFinished ? "Replay" : "Play";
      const playIcon = demoStarted && demoPlaying ? "pause" : "play";
      return `
        <section class="demo-playback-controls ${videoSlide ? "has-video" : ""}" data-demo-playback aria-label="${videoSlide ? "Video" : "Demo"} playback controls">
          <button class="demo-playback-toggle" type="button" data-action="demo-toggle" title="${playLabel}" aria-label="${playLabel} demo" aria-pressed="${demoStarted && demoPlaying}">${icon(playIcon)}</button>
          <input class="demo-playback-progress" data-demo-seek type="range" min="0" max="${videoSlide ? "0" : "100"}" step="0.05" value="${videoSlide ? "0" : demoOverallProgress()}" aria-label="${videoSlide ? "Video" : "Demo"} timeline" aria-valuetext="${videoSlide ? "0:00 of 0:00" : escapeHtml(demoProgressText())}">
          ${videoSlide ? `<button class="icon-button demo-sound-button" type="button" data-action="demo-video-sound" title="${demoVideoSoundEnabled ? "Mute" : "Unmute"} video" aria-label="${demoVideoSoundEnabled ? "Mute" : "Unmute"} video" aria-pressed="${demoVideoSoundEnabled}">${icon(demoVideoSoundEnabled ? "volume" : "muted")}</button>` : ""}
          <button class="demo-menu-button" type="button" data-action="open-contents" title="Menu" aria-label="Open menu" aria-haspopup="dialog">${icon("contents")}<span>Menu</span></button>
          <button class="icon-button demo-restart-button" type="button" data-action="demo-restart" title="Restart ${videoSlide ? "video" : "demo"}" aria-label="Restart ${videoSlide ? "video" : "demo"}">${icon("reset")}</button>
        </section>
      `;
