    function mediaDropStatusText() {
      const folder = mediaFolderSlug();
      if (["copying", "copied", "linked", "error", "remembered"].includes(mediaDropState)) return mediaDropMessage;
      if (mediaSiteDirectoryHandle) return `Connected to mh_media.${folder ? ` New files can be copied to tutorials/${folder}/.` : ""}`;
      return "First connect the main mh_media folder. Then choose the image, video, or audio file you want to use.";
