	              ["tech-tips", "Tech Tips"]
	            ])}
	            ${metaInput("group", "Section group (optional)", meta.group, "ChatGPT Tools")}
	            ${metaInput("mediaFolder", "Media tutorial folder", meta.mediaFolder, "pinning-chatgpt")}
	            ${metaInput("cardTitle", "Card title", meta.cardTitle)}
	            ${metaInput("order", "Display order", meta.order, "10", "number")}
            <div class="metadata-public-url">
              <label for="metadata-public-url">Public / social share URL</label>
              <div class="metadata-url-row">
                <input id="metadata-public-url" data-meta="publicUrl" type="url" value="${escapeHtml(publicUrl())}" placeholder="https://magichashtags.com/learn/…">
                <button type="button" data-action="copy-public-url">Copy Share Link</button>
              </div>
            </div>
	            ${metaArea("summary", "Card summary", meta.summary)}
	            ${metaArea("modalDescription", "Modal description", meta.modalDescription)}
	            ${metaInput("primaryActionLabel", "Primary button label", meta.primaryActionLabel, meta.pageType === "demo" ? "Open Tutorial" : "Open Tool")}
	            ${metaInput("primaryActionUrl", "Primary button destination", meta.primaryActionUrl, "https://…", "url")}
	            ${metaCheckbox("relatedCalloutEnabled", "Show an additional related-page callout", meta.relatedCalloutEnabled)}
	            ${metaInput("relatedCalloutTitle", "Related callout title", meta.relatedCalloutTitle, "Before you continue")}
	            ${metaArea("relatedCalloutText", "Related callout explanation", meta.relatedCalloutText)}
	            ${metaInput("relatedCalloutLabel", "Related button label", meta.relatedCalloutLabel, "Open Customizer")}
	            ${metaInput("relatedCalloutUrl", "Related button destination", meta.relatedCalloutUrl, "https://…", "url")}
	            ${metaInput("socialTitle", "Social share title", meta.socialTitle)}
            ${metaArea("socialDescription", "Social share description", meta.socialDescription)}
            ${metaInput("socialImage", "Social preview image URL", meta.socialImage)}
            ${metaInput("socialImageAlt", "Social image alt text", meta.socialImageAlt)}
	            <div class="metadata-note">Choose <strong>Tool Demo</strong> when the exported page should send visitors to a tutorial. Choose <strong>Tutorial</strong> when it should send visitors to the tool or setup page. The optional related callout is for connections such as Exhibit Descriptions → Customizer. The export stays a standalone HTML file.</div>
	          </div>
        </details>
      `;
    }

    function metaInput(key, label, value, placeholder = "", type = "text", readonly = false) {
      return `<label>${escapeHtml(label)}<input data-meta="${key}" type="${type}" value="${escapeHtml(value ?? "")}" placeholder="${escapeHtml(placeholder)}" ${readonly ? "readonly" : ""}></label>`;
    }

	    function metaArea(key, label, value) {
	      return `<label>${escapeHtml(label)}<textarea data-meta="${key}">${escapeHtml(value ?? "")}</textarea></label>`;
	    }

	    function metaSelect(key, label, value, options) {
	      return `<label>${escapeHtml(label)}<select data-meta="${key}">${options.map(([optionValue, optionLabel]) => `<option value="${escapeHtml(optionValue)}" ${optionValue === value ? "selected" : ""}>${escapeHtml(optionLabel)}</option>`).join("")}</select></label>`;
	    }

    function metaCheckbox(key, label, checked) {
	      return `<label class="metadata-checkbox"><input data-meta="${key}" type="checkbox" ${checked ? "checked" : ""}><span>${escapeHtml(label)}</span></label>`;
	    }

    function renderContentsPreviewMedia(slide) {
      const media = slide.media || {};
      const mediaUrl = String(media.url || "").trim();
      if (slide.kind === "video" || media.type === "video") {
        return `<span class="contents-preview-video-label">VIDEO PAGE</span>`;
      }
      if (!mediaUrl || media.type === "audio") return "";
      const fit = media.fit === "cover" ? "cover" : "contain";
      const style = `--media-fit:${fit};--media-x:${Number(media.x) || 0}%;--media-y:${Number(media.y) || 0}%;--media-scale:${Number(media.scale) || 1}`;
      return `<span class="contents-preview-media" style="${style}"><img src="${escapeHtml(mediaUrl)}" alt="" loading="eager" decoding="async"></span>`;
    }

    function renderContentsPreviewAnnotation(annotation, slide = currentSlide()) {
      const type = annotation.type;
      const baseStyle = objectStyle(annotation);
      const open = (extraClass = "") => `<span class="contents-preview-object ${extraClass}" style="${baseStyle}">`;
      if (["shape", "image", "gif"].includes(type)) {
        const src = resolveAnnotationAssetSrc(annotation.src);
        const cropClass = isCroppableAnnotation(annotation) && annotation.cropEnabled ? ` is-crop-enabled ${annotation.cropWindow ? "has-crop-window" : ""}` : "";
        const shadowClass = isCroppableAnnotation(annotation) && annotation.imageShadow ? " has-image-shadow" : "";
        return `${open(`contents-preview-${type}${cropClass}${shadowClass}`)}<img src="${escapeHtml(src)}" alt="" loading="eager" decoding="async"></span>`;
      }
      if (type === "clip-frame") {
        const members = clipFrameMembers(annotation, slide)
          .slice()
          .sort((a, b) => a.z - b.z)
          .map((member) => renderContentsPreviewAnnotation(member, slide))
          .join("");
        return `<span class="contents-preview-object contents-preview-clip-frame" style="${baseStyle}"><span class="clip-frame-viewport"><span class="clip-frame-scene" style="${clipFrameSceneStyle(annotation)}">${members}</span></span></span>`;
      }
      if (type === "magnifier") {
        return `<span class="contents-preview-object contents-preview-magnifier" data-magnifier-lens data-magnifier-z="${annotation.z}" style="${baseStyle}"><span class="magnifier-viewport"><span class="magnifier-scene-host" data-magnifier-scene-host aria-hidden="true"></span></span></span>`;
      }
      if (type === "cover") return `${open("contents-preview-cover")}</span>`;
      if (type === "blur") return `${open("contents-preview-blur")}</span>`;
      if (type === "markup") return `${open(`contents-preview-markup${annotation.imageShadow ? " has-image-shadow" : ""}`)}${markupSvg(annotation)}</span>`;
      if (type === "text") {
        const size = Math.max(4, (Number(annotation.textFontSize) || 16) * .32);
        const textStyle = annotation.textStyle === "italic" ? "italic" : "normal";
        const style = `${baseStyle};--preview-text-color:${annotation.textColor || "#000000"};--preview-text-size:${size}px;--preview-text-style:${textStyle}`;
        return `<span class="contents-preview-object contents-preview-text" data-text-style="${escapeHtml(annotation.textStyle)}" style="${escapeHtml(style)}">${escapeHtml(annotation.text)}</span>`;
      }
      if (type === "slide-intro" || type === "callout") {
        const title = type === "slide-intro" ? annotation.introTitle : annotation.calloutTitle;
        const body = type === "slide-intro" ? annotation.introBody : annotation.calloutBody;
        const titleOnly = type === "slide-intro" && annotation.introTitleOnly;
        return `${open(`contents-preview-card${titleOnly ? " contents-preview-card--title-only" : ""}`)}<span class="contents-preview-card-title">${escapeHtml(title || "")}</span>${titleOnly ? "" : `<span class="contents-preview-card-body">${escapeHtml(body || "")}</span>`}</span>`;
      }
      const iconSrc = type === "video"
        ? VIDEO_ANNOTATION_IMAGE
        : type === "link"
          ? LINK_ANNOTATION_IMAGE
          : type === "audio" ? AUDIO_PLAY_IMAGE : "";
      return iconSrc
        ? `${open(`contents-preview-${type}`)}<img src="${escapeHtml(resolveAnnotationAssetSrc(iconSrc))}" alt="" loading="eager" decoding="async"></span>`
        : "";
    }

    function renderContentsPreviewHotspot(hotspot, index) {
      const style = hotspotStyle(index);
      return `<span class="contents-preview-object contents-preview-hotspot" style="${objectStyle(hotspot)}"><img src="${escapeHtml(style.image)}" alt="" loading="eager" decoding="async"><span class="contents-preview-hotspot-number">${index + 1}</span></span>`;
    }

    function renderContentsSlidePreview(slide) {
      const previewColor = /^#[0-9a-f]{6}$/i.test(String(slide.media?.matte || "")) ? slide.media.matte : "#ffffff";
      const annotations = topLevelAnnotations(slide)
        .slice()
        .sort((a, b) => a.z - b.z)
        .map((annotation) => renderContentsPreviewAnnotation(annotation, slide))
        .join("");
      const hotspots = slide.hotspots.map(renderContentsPreviewHotspot).join("");
      return `<span class="contents-preview-stage" data-scene-coordinate-system="${SCENE_COORDINATE_SYSTEM}" style="--contents-preview-color:${escapeHtml(previewColor)}">${renderContentsPreviewMedia(slide)}${annotations}${hotspots}</span>`;
    }

    function renderContentsModal() {
      return `
        <div class="modal" id="contentsModal" ${state.ui.contentsOpen ? "" : "hidden"}>
          <section class="modal-panel contents-modal-panel" role="dialog" aria-modal="true" aria-labelledby="contentsTitle">
