                          <div class="contents-slide-actions-menu" role="menu" aria-label="Page ${index + 1} actions">
                            <label class="contents-slide-name-field">Page Name<input data-contents-slide-name data-index="${index}" value="${escapeHtml(slide.title)}" aria-label="Page ${index + 1} name"></label>
                            <button type="button" role="menuitem" data-action="contents-save-slide-name" data-index="${index}">Save Name</button>
