    function renderDemoPreviewModal() {
      if (MODE !== "builder" || !demoPreviewOpen || !demoPreviewHtml) return "";
      return `
        <div class="modal" id="demoPreviewModal">
          <section class="modal-panel demo-preview-modal-panel" role="dialog" aria-modal="true" aria-labelledby="demoPreviewTitle">
