              <button type="button" data-action="preview-slides" aria-pressed="${demoPreviewMode === "tutorial"}">Slides</button>
            </div>
            <div class="modal-body">
              <iframe class="demo-preview-frame" title="${demoPreviewMode === "tutorial" ? "Interactive slides preview" : "Current video or autoplay demo preview"}" allow="autoplay; fullscreen" srcdoc="${escapeHtml(demoPreviewHtml)}"></iframe>
            </div>
          </section>
        </div>
