    function syncMainMediaImage(image) {
      const naturalWidth = Math.max(0, Math.round(image.naturalWidth || 0));
      const naturalHeight = Math.max(0, Math.round(image.naturalHeight || 0));
      if (!naturalWidth || !naturalHeight) return;
      image.setAttribute("width", String(naturalWidth));
      image.setAttribute("height", String(naturalHeight));
      const layer = image.closest(".media-layer");
      layer?.style.setProperty("--media-natural-width", `${naturalWidth}px`);
      layer?.style.setProperty("--media-natural-height", `${naturalHeight}px`);
      const stage = image.closest("[data-stage]");
      const slide = state.tutorial.slides.find((item) => item.id === image.dataset.slideId);
      if (image.classList.contains("scroll-slide-page-image")) {
        requestAnimationFrame(() => syncScrollSlideUi(image.closest("[data-scroll-slide]")));
      }
      if (!slide || slide.media.naturalWidth === naturalWidth && slide.media.naturalHeight === naturalHeight) return;
      slide.media.naturalWidth = naturalWidth;
      slide.media.naturalHeight = naturalHeight;
      scheduleSave();
    }

    function syncScrollSlideUi(viewport = root.querySelector("[data-scroll-slide]")) {
      if (!viewport) return;
      const maxScroll = Math.max(0, viewport.scrollHeight - viewport.clientHeight);
      const atBottom = maxScroll <= 1 || viewport.scrollTop >= maxScroll - 2;
      const caret = viewport.closest("[data-stage]")?.querySelector(".scroll-slide-caret");
      if (caret) {
        caret.hidden = atBottom;
        caret.setAttribute("aria-hidden", String(atBottom));
      }
      syncScrollHotspotInView(viewport);
    }

    function syncScrollHotspotInView(viewport) {
      const slide = currentSlide();
      if (slide?.kind !== "scroll" || drag || popupDrag) return;
      const viewportBounds = viewport.getBoundingClientRect();
      const fixedHeaderBounds = viewport.closest("[data-stage]")?.querySelector("[data-fixed-browser-header]")?.getBoundingClientRect();
      const headerHeight = fixedHeaderBounds
        ? Math.max(0, Math.min(viewportBounds.bottom, fixedHeaderBounds.bottom) - viewportBounds.top)
        : 0;
      const visibleTop = viewportBounds.top + headerHeight;
      const visibleBottom = viewportBounds.bottom;
      const targetY = visibleTop + (visibleBottom - visibleTop) * .38;
      const candidates = [...viewport.querySelectorAll(".hotspot-object[data-id]")]
        .map((marker) => {
          const bounds = marker.getBoundingClientRect();
          const visiblePixels = Math.max(0, Math.min(bounds.bottom, visibleBottom) - Math.max(bounds.top, visibleTop));
          const visibleRatio = visiblePixels / Math.max(1, bounds.height);
          return { marker, bounds, visibleRatio, distance: Math.abs((bounds.top + bounds.bottom) / 2 - targetY) };
        })
        .filter((entry) => entry.visibleRatio >= .35)
        .sort((a, b) => a.distance - b.distance);
      const hotspotId = candidates[0]?.marker.dataset.id || "";
      const expandedId = scrollExpandedHotspots.get(slide.id) || "";
      if (!hotspotId && !expandedId) return;
      if (hotspotId === expandedId && (!hotspotId || state.ui.activeHotspotId === hotspotId)) return;
      if (hotspotId) {
        scrollExpandedHotspots.set(slide.id, hotspotId);
        state.ui.activeHotspotId = hotspotId;
      } else {
        scrollExpandedHotspots.delete(slide.id);
      }
      viewport.querySelectorAll(".hotspot-object[data-id]").forEach((marker) => {
        marker.classList.toggle("is-active", marker.dataset.id === hotspotId);
      });
      const sidebar = root.querySelector(".slide-sidebar");
      if (sidebar) sidebar.outerHTML = renderSidebar(slide);
    }

    function restoreScrollSlidePosition(slide = currentSlide()) {
      if (slide?.kind !== "scroll") return;
      const viewport = root.querySelector(`[data-scroll-slide="${CSS.escape(slide.id)}"]`);
      if (!viewport) return;
      const offsetUnits = Number(scrollSlidePositions.get(slide.id)) || 0;
      viewport.scrollTop = offsetUnits / 100 * (viewport.clientWidth / SCENE_ASPECT);
      requestAnimationFrame(() => syncScrollSlideUi(viewport));
    }

    function onScrollSlide(event) {
      const viewport = event.target?.closest?.("[data-scroll-slide]");
      if (!viewport || event.target !== viewport) return;
      const offsetUnits = viewport.scrollTop / Math.max(viewport.clientWidth / SCENE_ASPECT, 1) * 100;
      scrollSlidePositions.set(viewport.dataset.scrollSlide, offsetUnits);
      syncScrollSlideUi(viewport);
    }

    function scrollPageDown(button) {
      const viewport = button?.closest("[data-stage]")?.querySelector("[data-scroll-slide]");
      if (!viewport) return;
      viewport.scrollBy({
        top: Math.max(120, viewport.clientHeight * .76),
        behavior: window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ? "auto" : "smooth"
      });
    }

    function waitForPlayerMedia(media) {
      if (!media) return Promise.resolve();
      const isImage = media.matches("img");
      const isVideo = media.matches("video");
      if (isImage && media.complete) {
        return media.naturalWidth > 0 && typeof media.decode === "function"
          ? media.decode().catch(() => {})
          : Promise.resolve();
      }
      if (isVideo && media.readyState >= 2) return Promise.resolve();
      return new Promise((resolve) => {
        let settled = false;
        const loadEvent = isVideo ? "loadeddata" : "load";
        const finish = () => {
          if (settled) return;
          settled = true;
          window.clearTimeout(timeout);
          media.removeEventListener(loadEvent, handleLoad);
          media.removeEventListener("error", finish);
          resolve();
        };
        const handleLoad = () => {
          if (isImage && typeof media.decode === "function") media.decode().catch(() => {}).finally(finish);
          else finish();
        };
        const timeout = window.setTimeout(finish, 3500);
        media.addEventListener(loadEvent, handleLoad, { once: true });
        media.addEventListener("error", finish, { once: true });
      });
    }

    function playerSlideVisualUrls(slide) {
      if (!slide) return [];
      const urls = [];
      const add = (value) => {
        const url = String(value || "").trim();
        if (url && !urls.includes(url)) urls.push(url);
      };
      if (slide.media?.type !== "audio" && slide.kind !== "video" && slide.media?.type !== "video") add(slide.media?.url);
      slide.annotations.forEach((annotation) => {
        if (["shape", "image", "gif"].includes(annotation.type)) add(resolveAnnotationAssetSrc(annotation.src));
        else if (annotation.type === "video") add(resolveAnnotationAssetSrc(VIDEO_ANNOTATION_IMAGE));
        else if (annotation.type === "link") add(resolveAnnotationAssetSrc(LINK_ANNOTATION_IMAGE));
        else if (annotation.type === "audio") {
          add(resolveAnnotationAssetSrc(AUDIO_PLAY_IMAGE));
          add(resolveAnnotationAssetSrc(AUDIO_PAUSE_IMAGE));
        }
      });
      slide.hotspots.forEach((_, index) => add(hotspotStyle(index).image));
      return urls;
    }

    function preloadNextPlayerMedia() {
      if (MODE !== "player") return;
      const nextSlide = state.tutorial.slides[state.ui.slideIndex + 1];
      if (!nextSlide) {
        playerPreloadedMedia = null;
        return;
      }
      const isVideo = nextSlide.kind === "video" || nextSlide.media.type === "video";
      const preloaders = [];
      if (isVideo) {
        const videoUrl = String(nextSlide.media?.url || "").trim();
        const video = document.createElement("video");
        video.preload = "auto";
        video.muted = true;
        if (videoUrl) {
          video.src = videoUrl;
          video.load();
          preloaders.push(video);
        }
      }
      playerSlideVisualUrls(nextSlide).forEach((url) => {
        const image = new Image();
        image.decoding = "async";
        image.loading = "eager";
        image.src = url;
        preloaders.push(image);
      });
      playerPreloadedMedia = preloaders;
    }

    function preparePlayerSlideVisuals(slide = currentSlide()) {
      if (MODE !== "player") return Promise.resolve();
      const body = root.querySelector(".tutorial-body");
      const slideId = slide?.id || "";
      if (!body || !slideId) return Promise.resolve();
      if (playerVisualReadySlideId === slideId) {
        body.classList.remove("is-slide-media-pending");
        body.classList.add("is-slide-media-ready");
        return Promise.resolve();
      }
      body.classList.add("is-slide-media-pending");
      body.classList.remove("is-slide-media-ready");
      const media = Array.from(body.querySelectorAll("[data-main-media-image], [data-main-video], .stage .annotation-asset-frame > img, .stage .hotspot-object .object-frame > img"));
      return Promise.all(media.map(waitForPlayerMedia)).then(() => {
        if (!body.isConnected || currentSlide()?.id !== slideId) return;
        body.classList.remove("is-slide-media-pending");
        body.classList.add("is-slide-media-ready");
        playerVisualReadySlideId = slideId;
        preloadNextPlayerMedia();
      });
    }

    function syncMagnifierScenes() {
      root.querySelectorAll("[data-magnifier-lens]").forEach((lens) => {
        const host = lens.querySelector("[data-magnifier-scene-host]");
        const source = lens.closest("[data-stage], .contents-preview-stage");
        if (!host || !source) return;
        const lensZ = Number(lens.dataset.magnifierZ) || Number(lens.style.getPropertyValue("--z")) || 0;
        const clone = source.cloneNode(true);
        clone.querySelectorAll("[data-magnifier-lens], [data-builder-only], .main-video-controls, .resize-handle, .markup-point-handle, .rotate-handle, .flip-handle, .move-handle, .magnifier-controls").forEach((node) => node.remove());
        clone.querySelectorAll(".stage-object, .contents-preview-object").forEach((node) => {
          const objectZ = Number(node.style.getPropertyValue("--z")) || 0;
          if (objectZ >= lensZ) node.remove();
        });
        clone.querySelectorAll(".is-selected, .is-locked, .is-grouped, .is-attention").forEach((node) => {
          node.classList.remove("is-selected", "is-locked", "is-grouped", "is-attention");
        });
        clone.querySelectorAll("[contenteditable], [tabindex], [data-action]").forEach((node) => {
          node.removeAttribute("contenteditable");
          node.removeAttribute("tabindex");
          node.removeAttribute("data-action");
        });
        clone.querySelectorAll("video, audio").forEach((media) => {
          media.muted = true;
          media.removeAttribute("controls");
        });
        clone.removeAttribute("data-stage");
        clone.removeAttribute("aria-label");
        clone.className = source.matches("[data-stage]") ? "stage magnifier-scene" : "contents-preview-stage magnifier-scene";
        host.replaceChildren(clone);
      });
    }

    function syncRuntimeMedia() {
      const mainImage = root.querySelector("[data-main-media-image]");
      if (mainImage) {
        const syncImage = () => syncMainMediaImage(mainImage);
        if (mainImage.complete && mainImage.naturalWidth > 0) syncImage();
        else mainImage.addEventListener("load", syncImage, { once: true });
      }
      playerVisualReadyPromise = preparePlayerSlideVisuals();
      syncMainVideo();
      syncMagnifierScenes();
      restoreScrollSlidePosition();
      if (!state.ui.videoModalId) return;
      const annotation = state.tutorial.slides.flatMap((slide) => slide.annotations).find((item) => item.id === state.ui.videoModalId);
      const youtube = youtubeVideoInfo(annotation?.url);
      if (youtube) {
        setVideoModalAspect(youtube.isShort ? 9 : 16, youtube.isShort ? 16 : 9);
        return;
      }
      const video = document.getElementById("videoModalMedia");
      if (!video) return;
      const updateAspect = () => setVideoModalAspect(video.videoWidth || 16, video.videoHeight || 9);
      video.addEventListener("play", updateDirectVideoControls);
      video.addEventListener("pause", updateDirectVideoControls);
      video.addEventListener("ended", updateDirectVideoControls);
      video.addEventListener("durationchange", updateDirectVideoControls);
      video.addEventListener("timeupdate", updateDirectVideoControls);
      video.addEventListener("loadedmetadata", updateAspect, { once: true });
      video.addEventListener("loadedmetadata", updateDirectVideoControls);
      video.addEventListener("error", () => {
        showToast("This video URL could not be played. Use a direct video file or a YouTube watch, share, or Shorts URL.");
      }, { once: true });
      updateAspect();
      updateDirectVideoControls();
      video.play().catch(() => updateDirectVideoControls());
    }

    function syncMainVideo() {
      const video = root.querySelector("[data-main-video]");
      if (!video) return;
      const update = () => {
        updateMainVideoControls(video);
        updateDemoPlaybackUi();
      };
      const markPlaying = () => {
        if (IS_DEMO_PLAYER) {
          demoStarted = true;
          demoPlaying = true;
        }
        update();
      };
      const markPaused = () => {
        if (IS_DEMO_PLAYER) demoPlaying = false;
        update();
      };
      const syncDimensions = () => syncMainVideoDimensions(video);
      video.addEventListener("play", markPlaying);
      video.addEventListener("pause", markPaused);
      video.addEventListener("ended", markPaused);
      video.addEventListener("volumechange", update);
      video.addEventListener("durationchange", update);
      video.addEventListener("timeupdate", update);
      video.addEventListener("loadedmetadata", update);
      video.addEventListener("loadedmetadata", syncDimensions);
      if (video.readyState >= 1) syncDimensions();
      if (IS_DEMO_PLAYER) {
        video.loop = true;
        video.muted = !demoVideoSoundEnabled;
        if (demoPlaying) {
          video.play().catch(() => {
            demoPlaying = false;
            updateDemoPlaybackUi();
          });
        } else {
          video.pause();
        }
      }
      update();
    }

    function syncMainVideoDimensions(video) {
      const naturalWidth = Math.max(0, Math.round(video.videoWidth || 0));
      const naturalHeight = Math.max(0, Math.round(video.videoHeight || 0));
      if (!naturalWidth || !naturalHeight) return;
      video.setAttribute("width", String(naturalWidth));
      video.setAttribute("height", String(naturalHeight));
      video.closest(".main-video-frame")?.style.setProperty("--video-source-aspect", `${naturalWidth} / ${naturalHeight}`);
      const slide = currentSlide();
      if (slide?.kind !== "video"
          || slide.media.naturalWidth === naturalWidth
          && slide.media.naturalHeight === naturalHeight) return;
      slide.media.naturalWidth = naturalWidth;
      slide.media.naturalHeight = naturalHeight;
      scheduleSave();
    }

