      const reservedHeight = media.querySelector(".video-modal-controls") ? 235 : 190;
      const availableHeight = Math.max(200, window.innerHeight - reservedHeight);
      const maxWidth = Math.min(980, Math.max(200, availableHeight * aspect));
      panel.style.setProperty("--video-modal-max-width", `${maxWidth}px`);
