    function formatVideoTime(seconds) {
      const safe = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
      return `${Math.floor(safe / 60)}:${String(safe % 60).padStart(2, "0")}`;
    }

    function parseShapeCsvRow(line) {
      const cells = [];
      let value = "";
      let quoted = false;
      for (let index = 0; index < line.length; index += 1) {
        const character = line[index];
        if (character === '"') {
          if (quoted && line[index + 1] === '"') {
            value += '"';
            index += 1;
          } else {
            quoted = !quoted;
          }
        } else if (character === "," && !quoted) {
          cells.push(value.trim());
          value = "";
        } else {
          value += character;
        }
      }
      cells.push(value.trim());
      return cells;
    }

    async function loadShapes() {
      try {
        const response = await fetch(SHAPES_CSV_URL, { cache: "no-store" });
        if (!response.ok) throw new Error(`Shape catalog returned ${response.status}.`);
        const rows = (await response.text()).split(/\r?\n/).map((line) => {
          const cells = parseShapeCsvRow(line);
          const grouped = cells.length >= 3;
          const group = (grouped ? cells[0] : "SHAPES").replace(/\u00a0/g, " ").trim();
          const name = (grouped ? cells[1] : cells[0]).replace(/\u00a0/g, " ").trim();
          const rawUrl = (grouped ? cells[2] : cells[1] || "").trim();
          if (!name || !/^https?:\/\//i.test(rawUrl)) return null;
          return { group: group || "SHAPES", name, url: normalizeShapeAssetUrl(name, rawUrl) };
        }).filter(Boolean);
        if (rows.length) {
          shapes = rows;
          render();
        }
      } catch (_) {
        showToast("Hosted shape list could not be reached. Using the built-in backup list.");
      }
    }

    async function loadDraftImages() {
      if (draftImagesLoading || MODE !== "builder" || !/^https?:$/.test(location.protocol)) return;
      draftImagesLoading = true;
      try {
        const groups = await Promise.all(DRAFT_FOLDERS.map(async ({ label, folder }) => {
          try {
            const directoryUrl = new URL(`tutorials/${encodeURIComponent(folder)}/`, location.href);
            const response = await fetch(directoryUrl, { cache: "no-store" });
            if (!response.ok) throw new Error(`Folder returned ${response.status}.`);
            const directory = new DOMParser().parseFromString(await response.text(), "text/html");
            const filenames = [...directory.querySelectorAll('a[href]')]
              .map((link) => {
                const href = link.getAttribute("href") || "";
                if (!href || href === ".." || href.startsWith("?") || href.endsWith("/")) return "";
                try {
                  return decodeURIComponent(new URL(href, directoryUrl).pathname.split("/").filter(Boolean).pop() || "");
                } catch (_) {
                  return "";
                }
              })
              .filter((filename) => /\.(?:avif|bmp|gif|jpe?g|png|svg|webp)$/i.test(filename));
            const entries = [...new Set(filenames)].sort((a, b) => a.localeCompare(b)).map((name) => ({
              name,
              label: name.replace(/\.[^.]+$/, "").toUpperCase(),
              type: /\.gif$/i.test(name) ? "gif" : "image",
              url: publicMediaUrl(["tutorials", folder, name])
            }));
            return { label, folder, entries, loaded: true, available: true };
          } catch (_) {
            return { label, folder, entries: [], loaded: true, available: false };
          }
        }));
        const signature = JSON.stringify(groups);
        if (signature !== draftImageSignature) {
          draftImageGroups = groups;
          draftImageSignature = signature;
          render();
        }
      } finally {
        draftImagesLoading = false;
      }
    }

