      const hotspot = currentSlide().hotspots.find((item) => item.id === id);
      if (!hotspot) return;
      if (currentSlide().kind === "scroll") scrollExpandedHotspots.set(currentSlide().id, id);
      if (state.ui.activeHotspotId !== id) stopAudio();
      state.ui.activeHotspotId = id;
      state.ui.selectedKind = "hotspot";
      state.ui.selectedId = id;
      multiSelection = [selectionKey("hotspot", id)];
      const stageWrap = root.querySelector(".stage-wrap");
      if (stageWrap) stageWrap.outerHTML = renderStage(currentSlide());
      const readerNav = root.querySelector(".reader-nav");
      if (readerNav) readerNav.outerHTML = renderReaderNav();
      const toolbar = root.querySelector(".builder-toolbar");
      if (toolbar) toolbar.outerHTML = renderToolbar(currentSlide(), hotspot);
      syncSelectedObjectUi("hotspot", id, hotspot);
      root.querySelectorAll(".hotspot-row").forEach((row) => {
        row.classList.toggle("is-active", row.dataset.id === id);
        row.setAttribute("aria-expanded", String(row.dataset.id === id));
      });
      root.querySelectorAll(".hotspot-entry").forEach((entry) => {
        entry.classList.toggle("is-active", entry.dataset.id === id);
      });
      root.querySelectorAll(".hotspot-detail-panel").forEach((detail) => detail.remove());
      root.querySelector(`.hotspot-entry[data-id="${CSS.escape(id)}"]`)?.insertAdjacentHTML("beforeend", renderHotspotDetail(hotspot));
      syncRuntimeMedia();
      drawAttentionToHotspot(id);
      scheduleSave();
    }

    function selectHotspotFromAction(event, actionNode, id) {
      const object = actionNode.closest("[data-object]");
      const hotspotId = id || actionNode.closest("[data-id]")?.dataset.id;
      if (MODE === "builder" && (object || event.shiftKey)) {
        selectObject("hotspot", hotspotId, event.shiftKey);
        drawAttentionToHotspot(hotspotId);
        return;
      }
      activateHotspot(hotspotId);
    }

    function mixedBodyCaret(editor) {
      if (!editor) return null;
      const selection = window.getSelection();
      if (!selection?.rangeCount || !selection.isCollapsed) return null;
      const anchorNode = selection.anchorNode;
      const anchorElement = anchorNode?.nodeType === 1 ? anchorNode : anchorNode?.parentElement;
      if (!anchorElement || !editor.contains(anchorElement)) return null;
      let line = anchorElement.closest?.(".mixed-body-line");
      if ((!line || line.parentElement !== editor) && anchorElement === editor) {
        const lineIndex = clamp(selection.anchorOffset, 0, Math.max(0, editor.children.length - 1));
        line = editor.children[lineIndex]?.closest?.(".mixed-body-line") || editor.querySelector(".mixed-body-line:first-child");
      }
      if (!line || line.parentElement !== editor) return null;
      let offset = 0;
      if (anchorNode && line.contains(anchorNode)) {
        try {
          const beforeCaret = document.createRange();
          beforeCaret.selectNodeContents(line);
          beforeCaret.setEnd(anchorNode, selection.anchorOffset);
          offset = beforeCaret.toString().length;
        } catch (_) {
          offset = 0;
        }
      }
      return { line, offset };
    }

    function selectedMixedBodyLines(editor, useRememberedSelection = true) {
      const lines = Array.from(editor?.querySelectorAll(":scope > .mixed-body-line") || []);
      if (!editor || !lines.length) return [];
      const selection = window.getSelection();
      const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
      const anchorElement = selection?.anchorNode?.nodeType === 1
        ? selection.anchorNode
        : selection?.anchorNode?.parentElement;
      if (range && anchorElement && editor.contains(anchorElement)) {
        const caret = mixedBodyCaret(editor);
        if (caret) return [caret.line];
        const selected = lines.filter((line) => {
          try { return range.intersectsNode(line); }
          catch (_) { return false; }
        });
        if (selected.length) return selected;
      }
      if (useRememberedSelection
          && lastMixedBodySelection?.editor === editor
          && lastMixedBodySelection.lines.every((line) => line.isConnected)) {
        return lastMixedBodySelection.lines;
      }
      return [lines[0]];
    }

    function lineListKind(line) {
      if (line?.dataset.listKind) return line.dataset.listKind;
      return line?.dataset.pipe === "true" ? "pipe" : "plain";
    }

    function setLineListKind(line, kind) {
      if (!line) return;
      line.dataset.listKind = kind;
      line.dataset.pipe = String(kind === "pipe");
      line.classList.toggle("is-pipe", kind === "pipe");
      line.classList.toggle("is-numbered", kind === "numbered");
    }

    function updateBodyListToggleState(editor, lines = selectedMixedBodyLines(editor, false)) {
      if (!editor || !lines.length) return;
      const container = editor.closest(".body-field, .hotspot-detail-panel, .slide-intro-card__body-field, .standalone-callout-card__body-field");
      container?.querySelectorAll(".body-list-toggle").forEach((button) => {
        const active = lines.every((line) => lineListKind(line) === button.dataset.listKind);
        button.classList.toggle("is-active", active);
        button.setAttribute("aria-pressed", String(active));
      });
    }

    function rememberMixedBodySelection() {
      if (MODE !== "builder") return;
      const selection = window.getSelection();
      const anchorElement = selection?.anchorNode?.nodeType === 1
        ? selection.anchorNode
        : selection?.anchorNode?.parentElement;
      const editor = anchorElement?.closest?.(".mixed-body-editor");
      if (!editor) return;
      const lines = selectedMixedBodyLines(editor, false);
      if (!lines.length) return;
      const caret = mixedBodyCaret(editor);
      lastMixedBodySelection = {
        editor,
        lines,
        focusLine: caret?.line || lines[0],
        caretOffset: caret?.offset || 0
      };
      updateBodyListToggleState(editor, lines);
    }

    function toggleMixedBodyListLines(editor, button, kind) {
      if (!editor) return false;
      const lines = selectedMixedBodyLines(editor);
      if (!lines.length) return false;
      const remembered = lastMixedBodySelection?.editor === editor ? lastMixedBodySelection : null;
      const focusLine = remembered?.focusLine && lines.includes(remembered.focusLine)
        ? remembered.focusLine
        : lines[0];
      const caretOffset = focusLine === remembered?.focusLine ? remembered.caretOffset || 0 : 0;
      const makeList = !lines.every((line) => lineListKind(line) === kind);
      lines.forEach((line) => setLineListKind(line, makeList ? kind : "plain"));
      updateBodyListToggleState(editor, lines);
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      editor.focus({ preventScroll: true });
      placeCaretInMixedBodyLine(focusLine, caretOffset);
      lastMixedBodySelection = { editor, lines, focusLine, caretOffset };
      if (button) {
        button.classList.toggle("is-active", makeList);
        button.setAttribute("aria-pressed", String(makeList));
      }
      const listLabel = kind === "numbered" ? "numbered list" : "pipe bullets";
      commit(makeList ? `Added ${listLabel} to the selected lines.` : "Changed the selected lines to paragraphs.", false);
      return true;
    }

    function toggleSlidePipeList(id, button) {
      const slide = currentSlide();
      if (!slide || slide.id !== id) return;
      const editor = button?.closest(".body-field")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, "pipe")) slide.descriptionListStyle = "";
    }

    function toggleSlideNumberedList(id, button) {
      const slide = currentSlide();
      if (!slide || slide.id !== id) return;
      const editor = button?.closest(".body-field")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, "numbered")) slide.descriptionListStyle = "";
    }

    function toggleHotspotPipeList(id, button) {
      const hotspot = currentSlide().hotspots.find((item) => item.id === id);
      if (!hotspot) return;
      if (state.ui.activeHotspotId !== id) stopAudio();
      state.ui.activeHotspotId = id;
      state.ui.selectedKind = "hotspot";
      state.ui.selectedId = id;
      const editor = button?.closest(".hotspot-detail-panel")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, "pipe")) hotspot.bodyListStyle = "";
    }

    function toggleHotspotNumberedList(id, button) {
      const hotspot = currentSlide().hotspots.find((item) => item.id === id);
      if (!hotspot) return;
      if (state.ui.activeHotspotId !== id) stopAudio();
      state.ui.activeHotspotId = id;
      state.ui.selectedKind = "hotspot";
      state.ui.selectedId = id;
      const editor = button?.closest(".hotspot-detail-panel")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, "numbered")) hotspot.bodyListStyle = "";
    }

    function toggleIntroBodyList(id, button, kind) {
      const intro = slideIntroCard();
      if (!intro || intro.id !== id) return;
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = id;
      const editor = button?.closest(".slide-intro-card__body-field")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, kind)) intro.introBodyListStyle = "";
    }

    function toggleCalloutBodyList(id, button, kind) {
      const callout = currentSlide().annotations.find((item) => item.id === id && item.type === "callout");
      if (!callout) return;
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = id;
      multiSelection = [selectionKey("annotation", id)];
      const editor = button?.closest(".standalone-callout-card__body-field")?.querySelector(".mixed-body-editor");
      if (toggleMixedBodyListLines(editor, button, kind)) callout.calloutBodyListStyle = "";
    }

    function activateAnnotationForEditing(id) {
      const annotation = currentSlide().annotations.find((item) => item.id === id);
      if (!annotation) return;
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = id;
      syncSelectedObjectUi("annotation", id, annotation);
      const toolbar = root.querySelector(".builder-toolbar");
      if (toolbar) toolbar.outerHTML = renderToolbar(currentSlide(), annotation);
      scheduleSave();
    }

    function syncSelectedObjectUi(kind, id, item) {
      multiSelection = [selectionKey(kind, id)];
      root.querySelectorAll("[data-object].is-selected").forEach((object) => {
        object.classList.remove("is-selected");
        object.querySelectorAll(".resize-handle,.markup-point-handle,.rotate-handle,.flip-handle,.move-handle").forEach((handle) => handle.remove());
      });
      root.querySelectorAll('[data-object][data-kind="hotspot"]').forEach((object) => {
        object.classList.toggle("is-active", kind === "hotspot" && object.dataset.id === id);
      });
      const selected = root.querySelector(`[data-object][data-kind="${kind}"][data-id="${CSS.escape(id)}"]`);
      if (!selected) return;
      selected.classList.add("is-selected");
      if (!item.locked) selected.insertAdjacentHTML("beforeend", renderHandles(item));
      requestAnimationFrame(syncSelectionControls);
    }

    function onChange(event) {
      const target = event.target;
      if (target.matches("[data-word-color]")) {
        applyWordColor(target.dataset.wordColor, target.value);
        return;
      }
      if (target.matches("[data-browser-field]")) {
        const key = target.dataset.browserField;
        if (["browserUrl", "gptName"].includes(key)) currentSlide()[key] = target.value.trim();
        commit(key === "browserUrl" ? "Updated the fixed browser URL." : "Updated the fixed GPT name.");
        return;
      }
      if (target.id === "toolbarTutorialTitle") {
        target.value = target.value.toUpperCase();
        state.tutorial.title = target.value;
        commit("Updated tutorial title.");
        return;
      }
      if (target.id === "projectSelect") {
        if (target.value && target.value !== PROJECT_ID) openProject(target.value);
        return;
      }
      if (target.id === "annotation-video-label") {
        toolbarAnnotationDraft = {
          ...toolbarAnnotationDraft,
          videoTitle: target.value
        };
        return;
      }
      if (target.id === "annotation-link-input") {
        toolbarAnnotationDraft = { ...toolbarAnnotationDraft, mode: "link", value: target.value };
        return;
      }
      if (target.id === "mediaDropFolder") {
        state.meta.mediaFolder = target.value;
        markTouched("mediaFolder");
        mediaDropState = mediaSiteDirectoryHandle ? "ready" : "disconnected";
        commit("Updated the media tutorial folder.");
        return;
      }
      if (target.matches("[data-demo-seek]")) {
        commitDemoSeek(target.value);
        return;
      }
      if (target.id === "demoTimingMode") {
        currentSlide().demo.timing = ["default", "manual", "audio"].includes(target.value) ? target.value : "default";
        commit("Updated this slide's demo timing.");
        return;
      }
      if (target.id === "demoDefaultDuration") {
        state.meta.demoDefaultDuration = clamp(Number(target.value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION);
        commit("Updated the default demo duration.");
        return;
      }
      if (target.id === "demoSlideDuration") {
        currentSlide().demo.duration = clamp(Number(target.value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION);
        commit("Updated this slide's manual duration.");
        return;
      }
      if (target.id === "demoManualDuration") {
        const value = String(target.value || "").trim();
        currentSlide().demo.manualDuration = value
          ? clamp(Number(value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION)
          : null;
        syncDemoAudioTiming();
        commit(value ? "Updated this slide's manual timing override." : "Cleared this slide's manual timing override.");
        return;
      }
      if (target.id === "scrollViewportWidth") {
        currentSlide().scrollViewportWidth = clamp(Number(target.value), SCROLL_VIEWPORT_MIN_WIDTH, 100);
        commit("Updated the scroll viewport width.");
        return;
      }
      if (target.id === "scrollHeaderHeight") {
        currentSlide().scrollHeaderHeight = clamp(Number(target.value), 0, SCROLL_MAX_HEADER_HEIGHT);
        commit(currentSlide().scrollHeaderHeight > 0 ? "Updated the frozen scroll header." : "Turned off the frozen scroll header.");
        return;
      }
      if (target.id === "insertedImageCornerSlider") {
        recordUndoStep();
        scheduleSave();
        return;
      }
      if (target.id === "insertedImageCornerPreset") {
        setInsertedImageCornerRadius(target.value);
        return;
      }
      if (target.matches("[data-magnifier-shape]")) {
        setSelectedMagnifierShape(target.value);
        return;
      }
      if (target.id === "demoSlideAudioUrl") {
        currentSlide().demo.audioUrl = target.value.trim();
        syncDemoAudioTiming();
        commit("Updated this slide's narration audio.", false);
        return;
      }
      if (target.id === "shapeSelect" && target.value) {
        const shape = shapes.find((item) => item.url === target.value);
        addImageAnnotation("shape", target.value, shape?.name || "Shape");
      }
      if (target.matches("[data-markup-shape]") && target.value) {
        addMarkup(`${target.dataset.markupShape}-${target.value}`);
        target.value = "";
      }
      if (target.id === "selectedOpacity") {
        const selected = selectedObject();
        if (selected) {
          selected.opacity = clamp(Number(target.value) / 100, .1, 1);
          commit("Updated opacity.", false);
        }
      }
      if (target.id === "markupCornerRadius") {
        const selected = selectedObject();
        if (selected?.type === "markup" && normalizeMarkupKind(selected.markup).startsWith("square-")) {
          selected.markupCornerRadius = clamp(Number(target.value), 0, 43);
          commit("Updated square corner roundness.", false);
        }
      }
      if (target.id === "markupWidth") {
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.strokeWidth = clamp(Number(target.value), 1, 10);
          commit("Updated markup width.", false);
        }
      }
      if (target.id === "markupTransparency") {
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.opacity = clamp(1 - Number(target.value) / 100, .1, 1);
          commit("Updated markup transparency.", false);
        }
      }
      if (target.id === "textCharacterSpacing") {
        const selected = selectedTextAnnotation();
        if (selected) {
          selected.textLetterSpacing = clamp(Number(target.value), -2, 12);
          commit(`Set text character spacing to ${selected.textLetterSpacing}px.`, false);
        }
      }
      if (target.id === "textLineHeight") {
        const selected = selectedTextAnnotation();
        if (selected) {
          selected.textLineHeight = clamp(Number(target.value), TEXT_LINE_HEIGHT_MIN, TEXT_LINE_HEIGHT_MAX);
          commit(`Set text line height to ${selected.textLineHeight}.`, false);
        }
      }
      if (target.id === "markupColor") {
        markupColorDefault = target.value;
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.markupColor = target.value;
          commit("Updated markup color.");
        }
      }
      if (target.id === "markupFillColor") {
        markupFillColorDefault = target.value;
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.fillColor = target.value;
          commit("Updated markup fill color.");
        }
      }
      if (target.id === "textAnnotationColor") {
        const selected = selectedObject();
        if (selected?.type === "text") {
          selected.textColor = target.value;
          commit("Updated text color.");
        }
      }
      if (target.id === "coverColor") {
        const selected = selectedObject();
        if (selected?.type === "cover") {
          selected.fillColor = target.value;
          commit("Updated cover color.");
        }
      }
      if (target.id === "backgroundColor") {
        currentSlide().media.matte = target.value;
        commit("Updated the slide background color.");
      }
      if (target.id === "blurStrength") {
        const selected = selectedObject();
        if (selected?.type === "blur") {
          selected.blurStrength = clamp(Number(target.value), 1, 30);
          commit("Updated blur strength.");
        }
      }
      if (target.id === "mainMediaUrl") {
        const value = normalizeMainMediaInput(target);
        currentSlide().media.url = value === mediaBase() ? "" : value;
        currentSlide().media.type = currentSlide().kind === "video" ? "video" : currentSlide().kind === "scroll" ? "image" : detectMediaType(target.value);
        refreshMainMediaLayer();
        commit("Updated the slide media URL.", false);
      }
      if (target.id === "videoSlideTitle") {
        currentSlide().title = target.value.trim() || "VIDEO PAGE";
        commit("Updated the video slide title.");
      }
      if (target.matches("[data-meta]")) {
        const key = target.dataset.meta;
        const previousMediaBase = key === "mediaFolder" ? mediaBase() : "";
	        state.meta[key] = target.type === "checkbox"
	          ? target.checked
	          : key === "order"
	            ? Number(target.value || 10)
	            : target.value;
        markTouched(key);
        state.meta.publicUrl = publicUrl();
        if (previousMediaBase) syncMediaUrlSeeds(previousMediaBase);
        commit(`Updated ${key}.`);
      }
    }

    function onInput(event) {
      if (event.target.matches("[data-word-color]")) return;
      const wordEditor = event.target.closest?.('[contenteditable="true"][data-bind]');
      if (wordEditor) queueMicrotask(() => {
        if (wordEditor.isConnected) { captureWordFormatting(wordEditor); scheduleSave(); }
      });
      requestAnimationFrame(syncSelectionControls);
      const target = event.target;
      if (target.id === "shadowHeightSlider") {
        const item = selectedObject();
        if (!item) return;
        item.shadowHeight = clamp(Number(target.value), 0, 40);
        item.imageShadow = item.shadowHeight > 0;
        root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`)?.style.setProperty("--object-shadow", item.imageShadow ? `drop-shadow(0 ${item.shadowHeight}px ${Math.max(1,item.shadowHeight*.45)}px rgba(0,0,0,.28))` : "none");
        root.querySelector("#shadowHeightValue").textContent = String(item.shadowHeight);
        scheduleSave();
        return;
      }
      if (target.id === "selectedObjectColor") {
        applySelectedObjectColor(target.value);
        return;
      }
      if (target.id === "insertedImageCornerSlider") {
        const image = selectedCornerAnnotation();
        if (!image) return;
        const radius = clamp(Number(target.value) || 0, 0, 50);
        if (image.type === "markup") {
          image.markupCornerRadius = radius * 43 / 50;
          applyLiveMarkupCornerRadii(image, root.querySelector(`[data-object][data-id="${CSS.escape(image.id)}"]`));
        } else image.cornerRadius = radius;
        root.querySelector(`[data-object][data-id="${CSS.escape(image.id)}"]`)?.style.setProperty("--corner-radius", `${radius}%`);
        const output = root.querySelector("#insertedImageCornerValue");
        if (output) output.textContent = `${radius}%`;
        const preset = root.querySelector("#insertedImageCornerPreset");
        if (preset) {
          preset.querySelectorAll("[data-custom-radius]").forEach(option => option.remove());
          if (![0, 3, 10, 50].includes(radius)) {
            const option = document.createElement("option");
            option.value = String(radius);
            option.textContent = `${radius}%`;
            option.dataset.customRadius = "true";
            preset.append(option);
          }
          preset.value = String(radius);
        }
        scheduleSave();
        return;
      }
      if (target.matches("[data-browser-field]")) {
        const key = target.dataset.browserField;
        if (["browserUrl", "gptName"].includes(key)) currentSlide()[key] = target.value;
        scheduleSave();
        return;
      }
      if (target.id === "toolbarTutorialTitle") {
        target.value = target.value.toUpperCase();
        state.tutorial.title = target.value;
        scheduleSave();
        return;
      }
      if (target.id === "annotation-video-label") {
        toolbarAnnotationDraft = {
          ...toolbarAnnotationDraft,
          videoTitle: target.value
        };
        return;
      }
      if (target.id === "annotation-link-input") {
        toolbarAnnotationDraft = { ...toolbarAnnotationDraft, mode: "link", value: target.value };
        return;
      }
      if (target.id === "mediaDropFolder") {
        const previousMediaBase = mediaBase();
        state.meta.mediaFolder = target.value;
        markTouched("mediaFolder");
        syncMediaUrlSeeds(previousMediaBase);
        mediaDropState = mediaSiteDirectoryHandle ? "ready" : "disconnected";
        updateMediaDropZone();
        scheduleSave();
        return;
      }
      if (target.matches("[data-demo-seek]")) {
        previewDemoSeek(target.value);
        return;
      }
      if (target.id === "demoDefaultDuration") {
        state.meta.demoDefaultDuration = clamp(Number(target.value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION);
        scheduleSave();
        return;
      }
      if (target.id === "demoSlideDuration") {
        currentSlide().demo.duration = clamp(Number(target.value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION);
        scheduleSave();
        return;
      }
      if (target.id === "demoManualDuration") {
        const value = String(target.value || "").trim();
        currentSlide().demo.manualDuration = value
          ? clamp(Number(value) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION)
          : null;
        syncDemoAudioTiming();
        scheduleSave();
        return;
      }
      if (target.id === "scrollViewportWidth") {
        currentSlide().scrollViewportWidth = clamp(Number(target.value), SCROLL_VIEWPORT_MIN_WIDTH, 100);
        const stage = root.querySelector("[data-stage]");
        stage?.style.setProperty("--scroll-viewport-width", `${currentSlide().scrollViewportWidth}%`);
        scheduleSave();
        return;
      }
      if (target.id === "scrollHeaderHeight") {
        currentSlide().scrollHeaderHeight = clamp(Number(target.value), 0, SCROLL_MAX_HEADER_HEIGHT);
        const stage = root.querySelector("[data-stage]");
        stage?.style.setProperty("--scroll-header-height", `${currentSlide().scrollHeaderHeight * SCENE_HEIGHT / SCENE_WIDTH}cqw`);
        stage?.querySelector(".scroll-slide-sticky-header")?.setAttribute("data-enabled", String(currentSlide().scrollHeaderHeight > 0));
        scheduleSave();
        return;
      }
      if (target.id === "demoSlideAudioUrl") {
        currentSlide().demo.audioUrl = target.value.trim();
        syncDemoAudioTiming();
        scheduleSave();
        return;
      }
      if (target.id === "mainMediaUrl") {
        const value = normalizeMainMediaInput(target);
        currentSlide().media.url = value === mediaBase() ? "" : value;
        currentSlide().media.type = currentSlide().kind === "video" ? "video" : currentSlide().kind === "scroll" ? "image" : detectMediaType(value);
        window.clearTimeout(mainMediaPreviewTimer);
        mainMediaPreviewTimer = window.setTimeout(refreshMainMediaLayer, 180);
        scheduleSave();
        return;
      }
      if (target.id === "videoSlideTitle") {
        currentSlide().title = target.value;
        scheduleSave();
        return;
      }
      if (target.matches("[data-main-video-timeline]")) {
        const video = root.querySelector("[data-main-video]");
        if (video) {
          video.currentTime = clamp(Number(target.value), 0, Number.isFinite(video.duration) ? video.duration : 0);
          updateMainVideoControls(video);
        }
        return;
      }
      if (target.id === "videoTimeline") {
        const video = document.getElementById("videoModalMedia");
        if (video) {
          video.currentTime = clamp(Number(target.value), 0, Number.isFinite(video.duration) ? video.duration : 0);
          updateDirectVideoControls();
        }
        return;
      }
      if (target.matches("[data-audio-timeline]")) {
        const audio = window.__tutorialAudio;
        if (audio && activeAudio === target.dataset.id) {
          const duration = Number.isFinite(audio.duration) ? audio.duration : 0;
          audio.currentTime = clamp(Number(target.value), 0, duration);
          updateAudioTimeline(target.dataset.id);
        }
        return;
      }
      if (target.id === "selectedOpacity") {
        const selected = selectedObject();
        if (selected) {
          selected.opacity = clamp(Number(target.value) / 100, .1, 1);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--opacity", selected.opacity);
          scheduleSave();
        }
      }
      if (target.id === "markupCornerRadius") {
        const selected = selectedObject();
        if (selected?.type === "markup" && normalizeMarkupKind(selected.markup).startsWith("square-")) {
          selected.markupCornerRadius = clamp(Number(target.value), 0, 43);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--markup-corner-radius", selected.markupCornerRadius);
          applyLiveMarkupCornerRadii(selected, element);
          scheduleSave();
        }
      }
      if (target.id === "markupWidth") {
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.strokeWidth = clamp(Number(target.value), 1, 10);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--markup-width", selected.strokeWidth);
          scheduleSave();
        }
      }
      if (target.id === "markupTransparency") {
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.opacity = clamp(1 - Number(target.value) / 100, .1, 1);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--opacity", selected.opacity);
          scheduleSave();
        }
      }
      if (target.id === "textCharacterSpacing") {
        const selected = selectedTextAnnotation();
        if (selected) {
          selected.textLetterSpacing = clamp(Number(target.value), -2, 12);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--text-letter-spacing", `${selected.textLetterSpacing}px`);
          scheduleSave();
        }
      }
      if (target.id === "textLineHeight") {
        const selected = selectedTextAnnotation();
        if (selected) {
          selected.textLineHeight = clamp(Number(target.value), TEXT_LINE_HEIGHT_MIN, TEXT_LINE_HEIGHT_MAX);
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--text-line-height", selected.textLineHeight);
          scheduleSave();
        }
      }
      if (target.id === "markupColor") {
        markupColorDefault = target.value;
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.markupColor = target.value;
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--markup-color", selected.markupColor);
          scheduleSave();
        }
      }
      if (target.id === "markupFillColor") {
        markupFillColorDefault = target.value;
        const selected = selectedObject();
        if (selected?.type === "markup") {
          selected.fillColor = target.value;
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--markup-fill-color", selected.fillColor);
          scheduleSave();
        }
      }
      if (target.id === "textAnnotationColor") {
        const selected = selectedObject();
        if (selected?.type === "text") {
          selected.textColor = target.value;
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"] .object-frame`);
          if (element) element.style.color = selected.textColor;
          scheduleSave();
        }
      }
      if (target.id === "coverColor") {
        const selected = selectedObject();
        if (selected?.type === "cover") {
          selected.fillColor = target.value;
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--cover-color", selected.fillColor);
          scheduleSave();
        }
      }
      if (target.id === "backgroundColor") {
        currentSlide().media.matte = target.value;
        root.querySelector("[data-stage]")?.style.setProperty("--stage-matte", target.value);
        scheduleSave();
      }
      if (target.id === "blurStrength") {
        const selected = selectedObject();
        const value = clamp(Number(target.value), 1, 30);
        const output = document.getElementById("blurStrengthValue");
        if (output) output.textContent = `${value}px`;
        if (selected?.type === "blur") {
          selected.blurStrength = value;
          const element = root.querySelector(`[data-object][data-id="${CSS.escape(selected.id)}"]`);
          element?.style.setProperty("--blur-strength", `${value}px`);
          scheduleSave();
        }
      }
      if (target.matches("[data-meta]")) {
        const key = target.dataset.meta;
        const previousMediaBase = key === "mediaFolder" ? mediaBase() : "";
	        state.meta[key] = target.type === "checkbox"
	          ? target.checked
	          : key === "order"
	            ? Number(target.value || 10)
	            : target.value;
        markTouched(key);
        state.meta.publicUrl = publicUrl();
        if (previousMediaBase) syncMediaUrlSeeds(previousMediaBase);
        if (key !== "publicUrl" && !state.meta.touched.publicUrl) {
          const publicUrlField = root.querySelector('[data-meta="publicUrl"]');
          if (publicUrlField) publicUrlField.value = state.meta.publicUrl;
        }
        scheduleSave();
      }
      const editable = target.isContentEditable ? target : target.closest?.('[contenteditable="true"]');
      if (!editable) return;
      const binding = editable.dataset.bind || "";
      const value = editable.classList.contains("mixed-body-editor")
        ? (() => {
          let numberedIndex = 0;
          return Array.from(editable.querySelectorAll(":scope > .mixed-body-line"))
          .map((line) => {
            const text = line.innerText.replace(/\r/g, "").replace(/\n+$/, "");
            const kind = lineListKind(line);
            if (kind === "numbered") return `${++numberedIndex}. ${text}`;
            numberedIndex = 0;
            return kind === "pipe" ? `| ${text}` : text;
          })
          .join("\n");
        })()
        : editable.innerText.replace(/\n+$/, "");
      if (binding === "tutorial.title") {
        const previousMediaBase = mediaBase();
        state.tutorial.title = value.toUpperCase();
        applySmartDefaults();
        syncMediaUrlSeeds(previousMediaBase);
        scheduleSave();
      } else if (binding.startsWith("slide.title:")) {
        currentSlide().title = value;
        scheduleSave();
      } else if (binding.startsWith("slide.description:")) {
        currentSlide().description = value;
        scheduleSave();
      } else if (binding.startsWith("hotspot.title:")) {
        const item = currentSlide().hotspots.find((hotspot) => hotspot.id === binding.split(":")[1]);
        if (item) {
          item.title = value;
          item.autoTitle = false;
        }
        scheduleSave();
      } else if (binding.startsWith("hotspot.body:")) {
        const item = currentSlide().hotspots.find((hotspot) => hotspot.id === binding.split(":")[1]);
        if (item) item.body = value;
        scheduleSave();
      } else if (binding.startsWith("annotation.text:")) {
        const item = currentSlide().annotations.find((annotation) => annotation.id === binding.split(":")[1]);
        if (item) item.text = value;
        scheduleSave();
      } else if (binding.startsWith("annotation.introTitle:")) {
        const item = currentSlide().annotations.find((annotation) => annotation.id === binding.split(":")[1]);
        if (item?.type === "slide-intro") item.introTitle = value;
        scheduleSave();
      } else if (binding.startsWith("annotation.introBody:")) {
        const item = currentSlide().annotations.find((annotation) => annotation.id === binding.split(":")[1]);
        if (item?.type === "slide-intro") item.introBody = value;
        scheduleSave();
      } else if (binding.startsWith("annotation.calloutTitle:")) {
        const item = currentSlide().annotations.find((annotation) => annotation.id === binding.split(":")[1]);
        if (item?.type === "callout") item.calloutTitle = value;
        scheduleSave();
      } else if (binding.startsWith("annotation.calloutBody:")) {
        const item = currentSlide().annotations.find((annotation) => annotation.id === binding.split(":")[1]);
        if (item?.type === "callout") item.calloutBody = value;
        scheduleSave();
      }
      if (binding.startsWith("annotation.text:")
        || binding.startsWith("annotation.introTitle:")
        || binding.startsWith("annotation.introBody:")
        || binding.startsWith("annotation.calloutTitle:")
        || binding.startsWith("annotation.calloutBody:")) {
        scheduleTextCardAutoFit();
      }
    }

    function normalizeMainMediaInput(target) {
      let value = target.value.trim();
      const base = mediaBase();
      const appended = value.slice(base.length);
      if (value.startsWith(base) && /^https?:\/\//i.test(appended)) {
        value = appended;
        target.value = value;
      }
      return value;
    }

    function onFocusIn(event) {
      const target = event.target;
      positionShapeNavigation(target.closest?.("[data-shape-menu]"));
      if (target.id === "mainMediaUrl" && !currentSlide().media.url && target.value === mediaBase()) {
        target.select();
      }
    }

    function syncLiveEditableBeforeRender(target = document.activeElement) {
      const editable = target?.isContentEditable
        ? target
        : target?.closest?.('[contenteditable="true"]');
      if (!editable || !root.contains(editable)) return false;
      editable.dispatchEvent(new Event("input", { bubbles: true }));
      return true;
    }

    function onFocusOut(event) {
      if (event.target.isContentEditable) {
        syncLiveEditableBeforeRender(event.target);
        commit("", false);
      }
    }

    function refreshMainMediaLayer() {
      if (currentSlide()?.kind === "scroll") {
        const stageWrap = root.querySelector(".stage-wrap");
        if (stageWrap) stageWrap.outerHTML = renderStage(currentSlide());
        syncRuntimeMedia();
        return;
      }
      const layer = root.querySelector(".media-layer");
      if (!layer) return;
      layer.outerHTML = renderMainMedia(currentSlide());
      syncRuntimeMedia();
    }

    function selectObject(kind, id, additive = false) {
      if (MODE !== "builder") return;
      if (kind !== "annotation" || id !== imageCropEditId) imageCropEditId = "";
      syncObjectSelection();
      const key = selectionKey(kind, id);
      const clickedEntry = selectionEntry(key);
      if (!clickedEntry) return;
      const groupedEntries = kind === "annotation" ? objectGroupEntriesForItem(clickedEntry.item) : [];
      const candidateKeys = groupedEntries.length > 1 ? groupedEntries.map(({ key: groupKey }) => groupKey) : [key];
      if (kind === "hotspot" && state.ui.activeHotspotId !== id) stopAudio();
      if (additive) {
        if (candidateKeys.every((candidateKey) => multiSelection.includes(candidateKey))) {
          multiSelection = multiSelection.filter((entry) => !candidateKeys.includes(entry));
        } else {
          multiSelection.push(...candidateKeys.filter((candidateKey) => !multiSelection.includes(candidateKey)));
        }
      } else if (!multiSelection.includes(key)) {
        multiSelection = candidateKeys;
      }
      const primary = additive && !multiSelection.includes(key)
        ? selectionEntry(multiSelection[multiSelection.length - 1])
        : selectionEntry(key);
      state.ui.selectedKind = primary?.kind || null;
      state.ui.selectedId = primary?.id || null;
      if (kind === "hotspot" && multiSelection.includes(key)) state.ui.activeHotspotId = id;
      render();
    }

    function onPointerDown(event) {
      if (MODE !== "builder" || event.button !== 0) return;
      if (event.target.closest(".builder-toolbar button") && document.activeElement?.isContentEditable) {
        syncLiveEditableBeforeRender();
        event.preventDefault();
        return;
      }
      if (event.target.closest(".body-list-toggle")) {
        rememberMixedBodySelection();
        event.preventDefault();
        return;
      }
      syncLiveEditableBeforeRender();
      const popupResizeHandle = event.target.closest("[data-popup-resize-handle]");
      if (popupResizeHandle) {
        const popup = popupResizeHandle.closest(".slide-sidebar.is-demo-popup");
        const body = popup?.closest(".tutorial-body.is-demo-centered-slide");
        const hotspot = currentSlide().hotspots.find((item) => item.id === popupResizeHandle.dataset.id);
        if (!popup || !body || !hotspot) return;
        const rect = body.getBoundingClientRect();
        const popupRect = popup.getBoundingClientRect();
        const left = clamp((popupRect.left - rect.left) / Math.max(rect.width, 1) * 100, 0, 100);
        const right = clamp((popupRect.right - rect.left) / Math.max(rect.width, 1) * 100, 0, 100);
        const top = clamp((popupRect.top - rect.top) / Math.max(rect.height, 1) * 100, 0, 100);
        const bottom = clamp((popupRect.bottom - rect.top) / Math.max(rect.height, 1) * 100, 0, 100);
        popupDrag = {
          mode: "resize",
          id: hotspot.id,
          handle: popupResizeHandle.dataset.handle || "se",
          rect,
          popup,
          startX: event.clientX,
          startY: event.clientY,
          original: { left, right, top, bottom },
          minW: clamp(180 / Math.max(rect.width, 1) * 100, 12, 50),
          minH: clamp(120 / Math.max(rect.height, 1) * 100, 10, 50)
        };
        hotspot.popupX = (left + right) / 2;
        hotspot.popupY = (top + bottom) / 2;
        hotspot.popupW = Math.max(popupDrag.minW, right - left);
        hotspot.popupH = Math.max(popupDrag.minH, bottom - top);
        popup.classList.remove("demo-popup-left", "demo-popup-right", "demo-popup-top", "demo-popup-bottom");
        popup.classList.add("is-custom-position", "is-custom-size");
        popup.style.setProperty("--popup-x", `${hotspot.popupX}%`);
        popup.style.setProperty("--popup-y", `${hotspot.popupY}%`);
        popup.style.setProperty("--popup-width", `${hotspot.popupW}%`);
        popup.style.setProperty("--popup-height", `${hotspot.popupH}%`);
        popupResizeHandle.setPointerCapture?.(event.pointerId);
        event.preventDefault();
        return;
      }
      const popupHandle = event.target.closest("[data-popup-drag-handle]");
      if (popupHandle) {
        const popup = popupHandle.closest(".slide-sidebar.is-demo-popup");
        const body = popup?.closest(".tutorial-body.is-demo-centered-slide");
        const hotspot = currentSlide().hotspots.find((item) => item.id === popupHandle.dataset.id);
        if (!popup || !body || !hotspot) return;
        const rect = body.getBoundingClientRect();
        const popupRect = popup.getBoundingClientRect();
        popupDrag = {
          mode: "move",
          id: hotspot.id,
          rect,
          popup,
          minX: clamp(popupRect.width / Math.max(rect.width, 1) * 50 + 1, 2, 48),
          minY: clamp(popupRect.height / Math.max(rect.height, 1) * 50 + 1, 2, 48)
        };
        hotspot.popupX = clamp((popupRect.left + popupRect.width / 2 - rect.left) / Math.max(rect.width, 1) * 100, popupDrag.minX, 100 - popupDrag.minX);
        hotspot.popupY = clamp((popupRect.top + popupRect.height / 2 - rect.top) / Math.max(rect.height, 1) * 100, popupDrag.minY, 100 - popupDrag.minY);
        popup.classList.remove("demo-popup-left", "demo-popup-right", "demo-popup-top", "demo-popup-bottom");
        popup.classList.add("is-custom-position");
        popup.style.setProperty("--popup-x", `${hotspot.popupX}%`);
        popup.style.setProperty("--popup-y", `${hotspot.popupY}%`);
        popupHandle.setPointerCapture?.(event.pointerId);
        event.preventDefault();
        return;
      }
      const objectElement = event.target.closest("[data-object]");
      if (!objectElement) return;
      if (event.target.closest('input,select,textarea,[contenteditable="true"]')) return;
      const deferredBodyDrag = Boolean(event.target.closest("button,a"));
      if (event.shiftKey) return;
      const kind = objectElement.dataset.kind;
      const id = objectElement.dataset.id;
      const wasSelected = isObjectSelected(kind, id);
      const slide = currentSlide();
      const item = kind === "hotspot"
        ? slide.hotspots.find((entry) => entry.id === id)
        : slide.annotations.find((entry) => entry.id === id);
      const groupedEntries = kind === "annotation" ? objectGroupEntriesForItem(item, slide) : [];
      const clipFrameDragEntries = kind === "annotation" && item?.type === "clip-frame"
        ? [
            { key: selectionKey("annotation", item.id), kind: "annotation", id: item.id, item },
            ...clipFrameMembers(item, slide).map((member) => ({ key: selectionKey("annotation", member.id), kind: "annotation", id: member.id, item: member }))
          ]
        : [];
      const selectionEntries = wasSelected ? selectedObjects() : [];
      const dragCandidates = [...selectionEntries, ...clipFrameDragEntries, ...groupedEntries];
      const dragGroupEntries = [...new Map(dragCandidates.flatMap((entry) =>
        entry.item.type === "clip-frame"
          ? [entry, ...clipFrameMembers(entry.item, slide).map((member) => ({ key: selectionKey("annotation", member.id), kind: "annotation", id: member.id, item: member }))]
          : [entry]).map((entry) => [entry.key, entry])).values()];
      multiSelection = selectionEntries.length > 1 ? selectionEntries.map(({ key }) => key) : groupedEntries.length > 1
        ? groupedEntries.map(({ key }) => key)
        : [selectionKey(kind, id)];
      state.ui.selectedKind = kind;
      state.ui.selectedId = id;
      if (kind === "hotspot") {
        if (state.ui.activeHotspotId !== id) stopAudio();
        state.ui.activeHotspotId = id;
      }
      if (!item || item.locked) return;
      if (kind === "annotation" && item.type === "text" && !event.target.closest("[data-handle]")) return;
      objectElement.classList.add("is-selected");
      const stage = objectElement.closest("[data-stage]");
      const rect = stage.getBoundingClientRect();
      drag = {
        id, kind,
        wasSelected,
        moved: false,
        deferredBodyDrag,
        captureElement: objectElement,
        pointerId: event.pointerId,
        captured: !deferredBodyDrag,
        handle: event.target.closest("[data-handle]")?.dataset.handle
          || (kind === "annotation" && isCroppableAnnotation(item) && imageCropEditId === id ? "crop-pan" : "move"),
        startX: event.clientX,
        startY: event.clientY,
        rect,
        objectRect: objectElement.getBoundingClientRect(),
        startAngle: Math.atan2(
          event.clientY - (objectElement.getBoundingClientRect().top + objectElement.getBoundingClientRect().height / 2),
          event.clientX - (objectElement.getBoundingClientRect().left + objectElement.getBoundingClientRect().width / 2)
        ),
        original: { x: item.x, y: item.y, w: item.w, h: item.h, rotation: item.rotation || 0, cropX: item.cropX ?? 50, cropY: item.cropY ?? 50, cropWindow: item.cropWindow ? { ...item.cropWindow } : null },
        groupOriginals: dragGroupEntries.length > 1
          ? dragGroupEntries
            .filter(({ item: groupItem }) => !groupItem.locked)
            .map(({ item: groupItem }) => ({ item: groupItem, x: groupItem.x, y: groupItem.y }))
          : []
      };
      if (!deferredBodyDrag) {
        objectElement.setPointerCapture?.(event.pointerId);
        event.preventDefault();
      }
    }

    function onPointerMove(event) {
      if (drag) requestAnimationFrame(syncSelectionControls);
      if (popupDrag) {
        const hotspot = currentSlide().hotspots.find((item) => item.id === popupDrag.id);
        if (!hotspot) return;
        if (popupDrag.mode === "resize") {
          const dx = (event.clientX - popupDrag.startX) / Math.max(popupDrag.rect.width, 1) * 100;
          const dy = (event.clientY - popupDrag.startY) / Math.max(popupDrag.rect.height, 1) * 100;
          const handle = popupDrag.handle;
          let { left, right, top, bottom } = popupDrag.original;
          if (handle.includes("w")) left = clamp(left + dx, 0, right - popupDrag.minW);
          if (handle.includes("e")) right = clamp(right + dx, left + popupDrag.minW, 100);
          if (handle.includes("n")) top = clamp(top + dy, 0, bottom - popupDrag.minH);
          if (handle.includes("s")) bottom = clamp(bottom + dy, top + popupDrag.minH, 100);
          hotspot.popupX = (left + right) / 2;
          hotspot.popupY = (top + bottom) / 2;
          hotspot.popupW = right - left;
          hotspot.popupH = bottom - top;
          popupDrag.popup.style.setProperty("--popup-width", `${hotspot.popupW}%`);
          popupDrag.popup.style.setProperty("--popup-height", `${hotspot.popupH}%`);
        } else {
          hotspot.popupX = clamp((event.clientX - popupDrag.rect.left) / Math.max(popupDrag.rect.width, 1) * 100, popupDrag.minX, 100 - popupDrag.minX);
          hotspot.popupY = clamp((event.clientY - popupDrag.rect.top) / Math.max(popupDrag.rect.height, 1) * 100, popupDrag.minY, 100 - popupDrag.minY);
        }
        popupDrag.popup.style.setProperty("--popup-x", `${hotspot.popupX}%`);
        popupDrag.popup.style.setProperty("--popup-y", `${hotspot.popupY}%`);
        scheduleSave();
        event.preventDefault();
        return;
      }
      if (!drag) return;
      const item = selectedObject();
      if (!item || item.id !== drag.id) return;
      const dx = (event.clientX - drag.startX) / drag.rect.width * 100;
      const dy = (event.clientY - drag.startY) / drag.rect.height * 100;
      const verticalMax = stageVerticalPositionMax(currentSlide());
      const pointerDistance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
      if (drag.deferredBodyDrag && !drag.moved && pointerDistance < 5) return;
      if (pointerDistance >= 5 || Math.abs(dx) > .2 || Math.abs(dy) > .2) drag.moved = true;
      if (drag.deferredBodyDrag && drag.moved) {
        if (!drag.captured) {
          drag.captureElement?.setPointerCapture?.(drag.pointerId);
          drag.captured = true;
        }
        window.getSelection()?.removeAllRanges();
        event.preventDefault();
      }
      if (drag.handle === "crop-pan" && isCroppableAnnotation(item) && item.cropEnabled) {
        const cropDx = (event.clientX - drag.startX) / Math.max(drag.objectRect.width, 1) * 100;
        const cropDy = (event.clientY - drag.startY) / Math.max(drag.objectRect.height, 1) * 100;
        item.cropX = clamp(drag.original.cropX - cropDx, 0, 100);
        item.cropY = clamp(drag.original.cropY - cropDy, 0, 100);
        if (drag.original.cropWindow) {
          item.cropWindow.left = drag.original.cropWindow.left + cropDx;
          item.cropWindow.top = drag.original.cropWindow.top + cropDy;
        }
        const element = root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`);
        if (element) element.style.cssText = objectStyle(item);
        scheduleSave();
        event.preventDefault();
        return;
      }
      if (drag.handle === "rotate" && (["shape", "text", "slide-intro", "callout"].includes(item.type) || (item.type === "markup" && isRotatableMarkup(item.markup)))) {
        const centerX = drag.objectRect.left + drag.objectRect.width / 2;
        const centerY = drag.objectRect.top + drag.objectRect.height / 2;
        const currentAngle = Math.atan2(event.clientY - centerY, event.clientX - centerX);
        const degrees = drag.original.rotation + (currentAngle - drag.startAngle) * 180 / Math.PI;
        item.rotation = ((degrees + 180) % 360 + 360) % 360 - 180;
        const element = root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`);
        if (element) element.style.cssText = objectStyle(item);
        scheduleSave();
        return;
      }
      if (drag.handle.startsWith("markup-") && item.type === "markup" && isPathMarkup(item.markup)) {
        const pointName = drag.handle.replace("markup-", "");
        item.markupPoints = normalizeMarkupPoints(item.markupPoints, item.markup);
        item.markupPoints[pointName] = {
          x: clamp((event.clientX - drag.objectRect.left) / Math.max(drag.objectRect.width, 1) * 100, 2, 98),
          y: clamp((event.clientY - drag.objectRect.top) / Math.max(drag.objectRect.height, 1) * 100, 2, 98)
        };
        const element = root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`);
        applyLiveMarkupShape(item, element);
        scheduleSave();
        return;
      }
      if (drag.handle === "move" && drag.groupOriginals.length > 1) {
        // Clamp one shared delta, not each object separately, to retain spacing.
        const bounds = drag.groupOriginals.map((original) => {
          const low = fitStageObjectBounds({ ...original.item, x: -1e6, y: -1e6 });
          const high = fitStageObjectBounds({ ...original.item, x: 1e6, y: 1e6 });
          return { minX: low.x - original.x, maxX: high.x - original.x, minY: low.y - original.y, maxY: high.y - original.y };
        });
        const groupDx = clamp(dx, Math.max(...bounds.map(b => b.minX)), Math.min(...bounds.map(b => b.maxX)));
        const groupDy = clamp(dy, Math.max(...bounds.map(b => b.minY)), Math.min(...bounds.map(b => b.maxY)));
        drag.groupOriginals.forEach((original) => {
          original.item.x = original.x + groupDx;
          original.item.y = original.y + groupDy;
          const groupElement = root.querySelector(`[data-object][data-id="${CSS.escape(original.item.id)}"]`);
          const slot = original.item.type ? -1 : hotspotSlotIndex(original.item.id);
          if (groupElement) groupElement.style.cssText = objectStyle(original.item) + (slot >= 0 ? `;--hotspot-color:${hotspotStyle(slot).color}` : "");
          if (original.item.type === "clip-frame") applyLiveClipFrameScene(original.item);
        });
        if (item.type === "clip-frame") applyLiveClipFrameScene(item);
        scheduleSave();
        return;
      }
      if (drag.handle === "move") {
        const minX = drag.kind === "annotation" ? STAGE_ANNOTATION_MIN_X : STAGE_OBJECT_MIN_POSITION;
        const maxX = drag.kind === "annotation" ? STAGE_ANNOTATION_MAX_X : STAGE_OBJECT_MAX_POSITION;
        item.x = clamp(drag.original.x + dx, minX, maxX);
        item.y = clamp(drag.original.y + dy, STAGE_OBJECT_MIN_POSITION, verticalMax);
      } else if (drag.kind === "annotation") {
        const changesWidth = drag.handle.includes("e") || drag.handle.includes("w");
        const changesHeight = drag.handle.includes("n") || drag.handle.includes("s");
        const directionX = drag.handle.includes("e") ? 1 : -1;
        const directionY = drag.handle.includes("s") ? 1 : -1;
        if (changesWidth) {
          item.w = clamp(drag.original.w + dx * directionX, item.cropWindow ? 1 : 5, item.type === "cover" ? 100 : 95);
          item.x = clamp(drag.original.x + (item.w - drag.original.w) / 2 * directionX, STAGE_ANNOTATION_MIN_X, STAGE_ANNOTATION_MAX_X);
        }
        if (changesHeight) {
          item.h = clamp(drag.original.h + dy * directionY, item.cropWindow ? 1 : 4, 95);
          item.y = clamp(drag.original.y + (item.h - drag.original.h) / 2 * directionY, STAGE_OBJECT_MIN_POSITION, verticalMax);
        }
        if ((changesWidth || changesHeight) && ["text", "slide-intro", "callout"].includes(item.type)) item.manualTextFrame = true;
        if (item.cropWindow && imageCropEditId !== item.id && changesWidth && changesHeight) {
          const ratio = Math.abs(dx / drag.original.w) >= Math.abs(dy / drag.original.h)
            ? item.w / drag.original.w : item.h / drag.original.h;
          const scale = clamp(ratio, Math.max(1 / drag.original.w, 1 / drag.original.h), Math.min(95 / drag.original.w, 95 / drag.original.h));
          item.w = drag.original.w * scale;
          item.h = drag.original.h * scale;
          item.x = drag.original.x + (item.w - drag.original.w) / 2 * directionX;
          item.y = drag.original.y + (item.h - drag.original.h) / 2 * directionY;
        }
      } else {
        const directionX = drag.handle.includes("e") ? 1 : -1;
        const directionY = drag.handle.includes("s") ? 1 : -1;
        const aspect = drag.original.w / Math.max(drag.original.h, 1);
        const proposedW = clamp(drag.original.w + dx * directionX, 5, 95);
        const proposedHFromW = proposedW / aspect;
        const proposedH = clamp(Math.abs(dy) > Math.abs(dx) ? drag.original.h + dy * directionY : proposedHFromW, 4, 95);
        item.w = clamp(proposedH * aspect, 5, 95);
        item.h = proposedH;
        item.x = clamp(drag.original.x + (item.w - drag.original.w) / 2 * directionX, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        item.y = clamp(drag.original.y + (item.h - drag.original.h) / 2 * directionY, STAGE_OBJECT_MIN_POSITION, verticalMax);
      }
      fitStageObjectBounds(item);
      if (imageCropEditId === item.id && drag.original.cropWindow && /^[nesw]+$/.test(drag.handle)) {
        const original = drag.original;
        const crop = original.cropWindow;
        const leftDelta = (item.x - item.w / 2) - (original.x - original.w / 2);
        const topDelta = (item.y - item.h / 2) - (original.y - original.h / 2);
        item.cropWindow = {
          width: crop.width * original.w / item.w,
          height: crop.height * original.h / item.h,
          left: (crop.left * original.w - leftDelta * 100) / item.w,
          top: (crop.top * original.h - topDelta * 100) / item.h
        };
      }
      const element = root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`);
      const slotIndex = drag.kind === "hotspot" ? hotspotSlotIndex(item.id) : -1;
      const slotColor = slotIndex >= 0 ? hotspotStyle(slotIndex).color : "";
      if (element) element.style.cssText = objectStyle(item) + (slotColor ? `;--hotspot-color:${slotColor}` : "");
      if (item.type === "markup") applyLiveMarkupCornerRadii(item, element);
      if (item.type === "clip-frame") applyLiveClipFrameScene(item);
      scheduleSave();
    }

    function applyLiveClipFrameScene(frame) {
      const frameElement = root.querySelector(`[data-clip-frame][data-id="${CSS.escape(frame.id)}"]`);
      const scene = frameElement?.querySelector(":scope > .clip-frame-viewport > .clip-frame-scene");
      if (scene) scene.style.cssText = clipFrameSceneStyle(frame);
    }

    function applyLiveMarkupShape(item, element) {
      if (!item || !element || item.type !== "markup" || !isPathMarkup(item.markup)) return;
      element.querySelector('[data-markup-primary="true"]')?.setAttribute("d", markupPath(item));
      const arrowSvg = element.querySelector("svg[data-arrow-points]");
      if (arrowSvg) {
        arrowSvg.dataset.arrowPoints = JSON.stringify(normalizeMarkupPoints(item.markupPoints, item.markup));
        updateArrowGeometry(arrowSvg);
      }
      const points = normalizeMarkupPoints(item.markupPoints, item.markup);
      for (const [name, handle] of [["start", "markup-start"], ["curve", "markup-curve"], ["end", "markup-end"]]) {
        const node = element.querySelector(`[data-handle="${handle}"]`);
        if (!node) continue;
        node.style.left = `${points[name].x}%`;
        node.style.top = `${points[name].y}%`;
      }
    }

    function onPointerUp() {
      if (popupDrag) {
        const message = popupDrag.mode === "resize" ? "Resized hotspot text box." : "Updated hotspot text box position.";
        popupDrag = null;
        commit(message);
        return;
      }
      if (!drag) return;
      const completedDrag = drag;
      drag = null;
      if (completedDrag.deferredBodyDrag && !completedDrag.moved) return;
      const annotation = completedDrag.kind === "annotation"
        ? currentSlide().annotations.find((item) => item.id === completedDrag.id)
        : null;
      if (!completedDrag.moved && completedDrag.wasSelected && annotation?.type === "video") {
        openVideo(annotation.id);
        return;
      }
      if (completedDrag.moved) {
        suppressObjectClickId = completedDrag.id;
        window.setTimeout(() => {
          if (suppressObjectClickId === completedDrag.id) suppressObjectClickId = "";
        }, 300);
      }
      commit(completedDrag.handle === "crop-pan" ? "Repositioned the inserted image crop." : "Updated object position or size.");
    }

    function onDoubleClick(event) {
      const object = event.target.closest('[data-object][data-kind="annotation"]');
      if (!object) return;
      const annotation = currentSlide().annotations.find((item) => item.id === object.dataset.id);
      if (annotation?.type === "video") openVideo(annotation.id);
      if (annotation?.type === "link") openLink(annotation.url);
    }

    function placeCaretInMixedBodyLine(line, offset = 0) {
      const selection = window.getSelection();
      if (!selection || !line) return;
      line.normalize();
      const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
      let textNode = walker.nextNode(), remaining = Math.max(0, offset);
      while (textNode && remaining > textNode.length) {
        const next = walker.nextNode();
        if (!next) { remaining = textNode.length; break; }
        remaining -= textNode.length;
        textNode = next;
      }
      const range = document.createRange();
      if (textNode) {
        range.setStart(textNode, clamp(remaining, 0, textNode.textContent.length));
      } else {
        range.setStart(line, 0);
      }
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);
    }

    function insertMixedBodyLine(event, editor) {
      event.preventDefault();
      const selection = window.getSelection();
      const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
      const rangeElement = range?.startContainer?.nodeType === 1
        ? range.startContainer
        : range?.startContainer?.parentElement;
      let line = rangeElement?.closest?.(".mixed-body-line");
      if (!line || line.parentElement !== editor) line = editor.querySelector(".mixed-body-line:last-child");
      if (!line) {
        line = document.createElement("div");
        line.className = "mixed-body-line";
        line.dataset.listKind = "plain";
        line.dataset.pipe = "false";
        editor.append(line);
      }

      if (range && !range.collapsed && line.contains(range.startContainer) && line.contains(range.endContainer)) {
        range.deleteContents();
      }

      let offset = line.innerText.replace(/\r/g, "").replace(/\n+$/, "").length;
      if (range && line.contains(range.startContainer)) {
        const beforeCaret = document.createRange();
        beforeCaret.selectNodeContents(line);
        beforeCaret.setEnd(range.startContainer, range.startOffset);
        offset = beforeCaret.toString().length;
      }

      const text = line.innerText.replace(/\r/g, "").replace(/\n+$/, "");
      const currentKind = lineListKind(line);
      if (currentKind !== "plain" && !text) {
        setLineListKind(line, "plain");
        placeCaretInMixedBodyLine(line);
        editor.dispatchEvent(new Event("input", { bubbles: true }));
        updateBodyListToggleState(editor, [line]);
        return;
      }

      const nextLine = document.createElement("div");
      nextLine.className = "mixed-body-line";
      setLineListKind(nextLine, currentKind);
      line.removeAttribute("data-placeholder");
      const tail = document.createRange();
      tail.selectNodeContents(line);
      if (range && line.contains(range.startContainer)) tail.setStart(range.startContainer, range.startOffset);
      else tail.collapse(false);
      nextLine.append(tail.extractContents());
      line.after(nextLine);

      placeCaretInMixedBodyLine(nextLine);
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      lastMixedBodySelection = { editor, lines: [nextLine] };
      updateBodyListToggleState(editor, [nextLine]);
    }

    function onKeyDown(event) {
      if (handleShapeNavigationKey(event)) return;
      if (event.target.id === "projectNameInput") {
        if (event.key === "Enter") {
          event.preventDefault();
          confirmProjectNameDialog();
          return;
        }
        if (event.key === "Escape") {
          event.preventDefault();
          closeProjectNameDialog();
          return;
        }
      }
      if (event.target.id === "annotation-link-input") {
        if (event.key === "Enter") {
          event.preventDefault();
          const value = event.target.value;
          if (addAnnotationFromUrl("link", value, "")) resetToolbarAnnotationInput();
          return;
        }
        if (event.key === "Escape") {
          event.preventDefault();
          resetToolbarAnnotationInput();
          return;
        }
      }
      const mixedBodyEditor = MODE === "builder" && !event.shiftKey && event.key === "Enter"
        ? event.target.closest?.(".mixed-body-editor")
        : null;
      if (mixedBodyEditor) {
        insertMixedBodyLine(event, mixedBodyEditor);
        return;
      }
      const saveShortcut = MODE === "builder"
        && (event.ctrlKey || event.metaKey)
        && !event.altKey
        && event.key.toLowerCase() === "s";
      if (saveShortcut) {
        event.preventDefault();
        const saved = saveStateNow();
        showToast(saved
          ? IS_PROJECT_APP ? `Saving ${currentProject?.name || "this draft"} to this Mac.` : `Saved browser draft for ${DRAFT_FILENAME}.`
          : draftStorageError);
        return;
      }
      const undoShortcut = MODE === "builder"
        && (event.ctrlKey || event.metaKey)
        && !event.altKey
        && !event.shiftKey
        && event.key.toLowerCase() === "z";
      if (undoShortcut) {
        event.preventDefault();
        undoLastChange();
        return;
      }
      const typingTarget = event.target.isContentEditable || event.target.closest?.("input,textarea,select");
      const selectedShortcutText = selectedTextAnnotation();
      const textAdjustmentDirection = ["-", "_"].includes(event.key) || ["Minus", "NumpadSubtract"].includes(event.code)
        ? -1
        : ["=", "+"].includes(event.key) || ["Equal", "NumpadAdd"].includes(event.code)
          ? 1
          : 0;
      const textAdjustmentShortcut = MODE === "builder"
        && event.ctrlKey
        && !event.metaKey
        && textAdjustmentDirection
        && selectedShortcutText;
      if (textAdjustmentShortcut) {
        event.preventDefault();
        if (event.altKey) {
          adjustSelectedAnnotationLetterSpacing(textAdjustmentDirection * .5);
        } else if (event.shiftKey) {
          adjustSelectedAnnotationLineHeight(textAdjustmentDirection * TEXT_LINE_HEIGHT_STEP);
        } else {
          adjustSelectedAnnotationTextSize(textAdjustmentDirection * TEXT_FONT_SIZE_STEP);
        }
        return;
      }
      const formatPropertyShortcut = MODE === "builder"
        && (event.ctrlKey || event.metaKey)
        && event.shiftKey
        && !event.altKey
        && !(event.ctrlKey && event.metaKey)
        && ["c", "v"].includes(event.key.toLowerCase())
        && state.ui.selectedKind === "annotation"
        && ["text", "markup"].includes(selectedObject()?.type);
      if (formatPropertyShortcut) {
        event.preventDefault();
        if (event.key.toLowerCase() === "c") copySelectedFormatProperties();
        else pasteSelectedFormatProperties();
        return;
      }
      const objectGroupShortcut = MODE === "builder"
        && !typingTarget
        && event.ctrlKey
        && !event.metaKey
        && !event.altKey
        && event.key.toLowerCase() === "g";
      if (objectGroupShortcut) {
        event.preventDefault();
        toggleSelectedObjectGroup(!event.shiftKey);
        return;
      }
      const arrangementShortcut = MODE === "builder"
        && !typingTarget
        && event.ctrlKey
        && !event.metaKey
        && !event.altKey
        && !event.shiftKey
        && ["l", "m", "p", "h", "c"].includes(event.key.toLowerCase());
      if (arrangementShortcut) {
        event.preventDefault();
        const arrangementMode = {
          l: "left",
          m: "middle",
          p: "vertical",
          h: "horizontal",
          c: "center"
        }[event.key.toLowerCase()];
        arrangeSelected(arrangementMode);
        return;
      }
      const builderControlShortcut = MODE === "builder"
        && !typingTarget
        && (event.ctrlKey || event.metaKey)
        && !event.altKey
        && !(event.ctrlKey && event.metaKey)
        && !event.shiftKey;
      if (builderControlShortcut && event.key.toLowerCase() === "d") {
        event.preventDefault();
        duplicateSelectedItems();
        return;
      }
      if (builderControlShortcut && event.metaKey && event.key.toLowerCase() === "c" && selectedObjects().length) {
        event.preventDefault();
        copySelectedItemsToBuilderClipboard();
        return;
      }
      if (builderControlShortcut && event.metaKey && event.key.toLowerCase() === "v") {
        event.preventDefault();
        pasteBuilderClipboard();
        return;
      }
      const arrowNudge = MODE === "builder"
        && !typingTarget
        && !event.ctrlKey
        && !event.metaKey
        && !event.altKey
        && ["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key);
      if (arrowNudge && selectedObjects().some(({ item }) => !item.locked)) {
        event.preventDefault();
        const step = event.shiftKey ? 2 : .5;
        nudgeSelectedObjects(
          event.key === "ArrowLeft" ? -step : event.key === "ArrowRight" ? step : 0,
          event.key === "ArrowUp" ? -step : event.key === "ArrowDown" ? step : 0
        );
        return;
      }
      const typingInsideSelectedStageObject = Boolean(
        event.target.closest?.('[contenteditable="true"]')?.closest?.(".stage-object.is-selected")
      );
      const layerShortcut = MODE === "builder"
        && (!typingTarget || typingInsideSelectedStageObject)
        && !event.ctrlKey
        && !event.metaKey
        && !event.altKey
        && !event.shiftKey
        && (event.key === "[" || event.key === "]");
      if (layerShortcut && selectedObject()) {
        event.preventDefault();
        moveSelectedZ(event.key === "[" ? "back" : "front");
        return;
      }
      const deleteShortcut = MODE === "builder"
        && !typingTarget
        && !event.ctrlKey
        && !event.metaKey
        && !event.altKey
        && (event.key === "Delete" || event.key === "Backspace");
      if (deleteShortcut && state.ui.selectedKind === "annotation" && state.ui.selectedId) {
        event.preventDefault();
        deleteSelected();
        return;
      }
      if (deleteShortcut && state.ui.selectedKind === "hotspot" && state.ui.selectedId) {
        event.preventDefault();
        showToast("Use the hotspot delete button.");
        return;
      }
      if (event.key === "Escape") {
        if (projectDialogMode) closeProjectNameDialog();
        else if (demoPreviewOpen) closeDemoPreview();
        else if (state.ui.videoModalId) closeVideo();
        else if (slideNarrationPanelSlideId || draftMoreOpen) {
          slideNarrationPanelSlideId = "";
          draftMoreOpen = false;
          render();
        }
        else if (state.ui.contentsOpen) closeContents();
        else if (IS_DEMO_EMBED) {
          event.preventDefault();
          window.parent.postMessage({ type: "ANNOTATION_TOOL_MODAL_CLOSE" }, location.origin);
        }
        else closeSiteNavigation();
        return;
      }
      if (event.key === "Tab" && (demoPreviewOpen || state.ui.videoModalId || state.ui.contentsOpen)) {
        const modal = document.querySelector(demoPreviewOpen ? "#demoPreviewModal" : state.ui.videoModalId ? "#videoModal" : "#contentsModal");
        const focusable = Array.from(modal?.querySelectorAll('button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])') || [])
          .filter((node) => !node.hidden);
        if (focusable.length) {
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
          } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
          }
        }
      }
      if ((event.key === "Enter" || event.key === " ") && event.target.closest?.('.annotation-video[data-id]')) {
        event.preventDefault();
        openVideo(event.target.closest('.annotation-video').dataset.id);
        return;
      }
      if ((event.key === "Enter" || event.key === " ")
          && !event.target.isContentEditable
          && !event.target.closest?.("button,a,input,select,textarea")) {
        const hotspotTrigger = event.target.closest?.('[data-action="activate-hotspot"][data-id]');
        if (hotspotTrigger) {
          event.preventDefault();
          activateHotspot(hotspotTrigger.dataset.id);
        }
      }
    }

    function addHotspot() {
      const slide = currentSlide();
      if (slide.kind === "video") return;
      const index = slide.hotspots.length;
      const hotspot = normalizeHotspot({
        id: uid("hotspot"),
        title: `HOTSPOT ${index + 1}`,
        autoTitle: true,
        body: "",
        color: hotspotStyle(index).color,
        x: 48 + index * 3,
        y: scrollViewportOffsetUnits(slide) + 38 + index * 3,
        w: HOTSPOT_DEFAULT_WIDTH,
        h: HOTSPOT_DEFAULT_HEIGHT,
        z: 20 + index
      }, index, slide);
      fitStageObjectBounds(hotspot, slide);
      slide.hotspots.push(hotspot);
      stopAudio();
      state.ui.activeHotspotId = hotspot.id;
      state.ui.selectedKind = "hotspot";
      state.ui.selectedId = hotspot.id;
      commit("Added hotspot.");
    }

    function renumberHotspots(slide = currentSlide()) {
      slide.hotspots.forEach((item, index) => {
        item.color = hotspotStyle(index).color;
        if (item.autoTitle) item.title = `HOTSPOT ${index + 1}`;
      });
    }

    function activateHotspot(id) {
      if (!id) return;
      if (currentSlide()?.kind === "scroll") scrollExpandedHotspots.set(currentSlide().id, id);
      if (state.ui.activeHotspotId !== id) stopAudio();
      state.ui.activeHotspotId = id;
      if (MODE === "builder") {
        state.ui.selectedKind = "hotspot";
        state.ui.selectedId = id;
      }
      render();
      drawAttentionToHotspot(id);
      if (MODE === "builder") scheduleSave();
    }

    function drawAttentionToHotspot(id, scrollRow = true) {
      if (!id) return;
      window.clearTimeout(hotspotAttentionTimer);
      root.querySelectorAll(".hotspot-object.is-attention").forEach((element) => {
        element.classList.remove("is-attention");
      });
      const escapedId = CSS.escape(id);
      const marker = root.querySelector(`.hotspot-object[data-id="${escapedId}"]`);
      const entry = root.querySelector(`.hotspot-entry[data-id="${escapedId}"]`);
      if (marker) {
        revealScrollSlideObject(marker);
        void marker.offsetWidth;
        marker.classList.add("is-attention");
      }
      if (scrollRow) entry?.querySelector(".hotspot-row")?.scrollIntoView({ block: "nearest" });
      hotspotAttentionTimer = window.setTimeout(() => {
        root.querySelectorAll(".hotspot-object.is-attention").forEach((element) => {
          element.classList.remove("is-attention");
        });
      }, 850);
    }

    function revealScrollSlideObject(element) {
      const viewport = element?.closest?.("[data-scroll-slide]");
      if (!viewport) return;
      const viewportBounds = viewport.getBoundingClientRect();
      const objectBounds = element.getBoundingClientRect();
      const padding = Math.min(48, viewportBounds.height * .12);
      const above = objectBounds.top < viewportBounds.top + padding;
      const below = objectBounds.bottom > viewportBounds.bottom - padding;
      if (!above && !below) return;
      const top = viewport.scrollTop + objectBounds.top - viewportBounds.top
        - (viewportBounds.height - objectBounds.height) / 2;
      viewport.scrollTo({
        top: Math.max(0, top),
        behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"
      });
    }

    function moveHotspot(id, direction) {
      const list = currentSlide().hotspots;
      const index = list.findIndex((item) => item.id === id);
      const target = index + direction;
      if (index < 0 || target < 0 || target >= list.length) return;
      stopAudio();

      // This is deliberately a content swap, not an array reorder. IDs, marker
      // numbers, artwork, colors, geometry, stacking, locks, and groups stay in
      // their numbered slots.
      const sourceTitle = list[index].title;
      const sourceBody = list[index].body;
      const sourceAutoTitle = list[index].autoTitle;
      list[index].title = list[target].title;
      list[index].body = list[target].body;
      list[index].autoTitle = list[target].autoTitle;
      list[target].title = sourceTitle;
      list[target].body = sourceBody;
      list[target].autoTitle = sourceAutoTitle;
      renumberHotspots(currentSlide());

      const targetId = list[target].id;
      state.ui.activeHotspotId = targetId;
      state.ui.selectedKind = "hotspot";
      state.ui.selectedId = targetId;
      commit("Moved hotspot title and body; numbered marker stayed fixed.");
    }

    function assignNewAnnotationToActiveHotspot(annotation) {
      if (!annotation) return annotation;
      const slide = currentSlide();
      if (slide?.kind === "scroll") {
        annotation.y += scrollViewportOffsetUnits(slide);
        fitStageObjectBounds(annotation, slide);
      }
      if (annotation.type === "slide-intro") return annotation;
      const hotspot = activeHotspot();
      annotation.hotspotGroupId = hotspot?.id || "";
      return annotation;
    }

    function addText(style) {
      const slide = currentSlide();
      const isImpactLabel = ["impact-label", "impact-label-reversed"].includes(style);
      const annotation = normalizeAnnotation({
        id: uid("text"),
        type: "text",
        text: isImpactLabel ? "NEW LABEL" : "new note",
        textStyle: style,
        textColor: document.getElementById("textAnnotationColor")?.value || "#000000",
        textFontSize: ["hand", "impact-label", "impact-label-reversed"].includes(style) ? 24 : 18,
        textAlign: "left",
        x: 50, y: 42, w: isImpactLabel ? 32 : 24, h: 12,
        z: topZ() + 1
      }, slide.annotations.length);
      slide.annotations.push(assignNewAnnotationToActiveHotspot(annotation));
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = annotation.id;
