            textFontSize: source.textFontSize,
            textLetterSpacing: source.textLetterSpacing,
            textLineHeight: source.textLineHeight,
            textAlign: source.textAlign
          }
        : {
            type: "markup",
            style: normalizeMarkupKind(source.markup).split("-").slice(1).join("-"),
            markupColor: source.markupColor,
            fillColor: source.fillColor,
            strokeWidth: source.strokeWidth,
            opacity: source.opacity,
            markupCornerRadius: source.markupCornerRadius
