      const targets = selectedObjects()
        .filter(({ kind, item }) => kind === "annotation" && item.type === formatPropertiesClipboard.type)
        .map(({ item }) => item);
      if (!targets.length) {
        showToast(`Select one or more ${formatPropertiesClipboard.type === "text" ? "text" : "Circle, Line, Square, or Arrow"} annotations first.`);
        return false;
      }
      targets.forEach((annotation) => {
        if (formatPropertiesClipboard.type === "text") {
          annotation.textStyle = formatPropertiesClipboard.textStyle;
          annotation.textColor = formatPropertiesClipboard.textColor;
          annotation.textFontSize = formatPropertiesClipboard.textFontSize;
          annotation.textLetterSpacing = formatPropertiesClipboard.textLetterSpacing;
          annotation.textLineHeight = formatPropertiesClipboard.textLineHeight;
          annotation.textAlign = formatPropertiesClipboard.textAlign;
          return;
        }
        annotation.markupColor = formatPropertiesClipboard.markupColor;
        annotation.fillColor = formatPropertiesClipboard.fillColor;
        annotation.strokeWidth = formatPropertiesClipboard.strokeWidth;
        annotation.opacity = formatPropertiesClipboard.opacity;
        annotation.markupCornerRadius = formatPropertiesClipboard.markupCornerRadius;
        const shape = normalizeMarkupKind(annotation.markup).split("-")[0];
        const allowedStyles = ["circle", "square"].includes(shape) ? CLOSED_MARKUP_STYLES : MARKUP_STYLES;
        if (allowedStyles.some(({ key }) => key === formatPropertiesClipboard.style)) {
          annotation.markup = `${shape}-${formatPropertiesClipboard.style}`;
        }
      });
      const formatName = formatPropertiesClipboard.type === "text" ? "text" : "shape";
      commit(`Applied ${formatName} formatting to ${targets.length} ${targets.length === 1 ? "annotation" : "annotations"}.`);
