    function createOrSelectClipFrame() {
      const slide = currentSlide();
      const selection = selectedObjects();
      if (!selection.length || selection.some(({ kind }) => kind !== "annotation")) {
        showToast("Select one or more images, shapes, or other annotations first.");
        return;
      }
      const selectedFrames = selection.filter(({ item }) => item.type === "clip-frame");
      const members = selection.filter(({ item }) => !["clip-frame", "slide-intro", "magnifier"].includes(item.type));
      if (selectedFrames.length > 1 || !members.length) {
        showToast("Select the items to clip, or one clip frame plus the items to add.");
        return;
      }
      let frame = selectedFrames[0]?.item || null;
      if (!frame) {
        const existingFrameIds = [...new Set(members.map(({ item }) => item.clipFrameId).filter(Boolean))];
        if (existingFrameIds.length === 1) {
          frame = slide.annotations.find((item) => item.id === existingFrameIds[0] && item.type === "clip-frame") || null;
        }
      }
      if (frame) {
        const added = members.filter(({ item }) => item.clipFrameId !== frame.id);
        added.forEach(({ item }) => { item.clipFrameId = frame.id; });
        state.ui.selectedKind = "annotation";
        state.ui.selectedId = frame.id;
        multiSelection = [selectionKey("annotation", frame.id)];
        if (added.length) {
          commit(`Added ${added.length} ${added.length === 1 ? "item" : "items"} to the clip frame.`);
        } else {
          render();
          showToast("Selected the clip frame. Its contents remain independently movable.");
        }
        return;
      }
      const padding = 4;
      const left = clamp(Math.min(...members.map(({ item }) => item.x - item.w / 2)) - padding, 0, 95);
      const right = clamp(Math.max(...members.map(({ item }) => item.x + item.w / 2)) + padding, left + 5, 100);
      const top = clamp(Math.min(...members.map(({ item }) => item.y - item.h / 2)) - padding, 0, 96);
      const bottom = clamp(Math.max(...members.map(({ item }) => item.y + item.h / 2)) + padding, top + 4, 100);
      frame = normalizeAnnotation({
        id: uid("clip-frame"),
        type: "clip-frame",
        label: "Clipped frame",
        clipFrameShape: "rounded",
        x: (left + right) / 2,
        y: (top + bottom) / 2,
        w: right - left,
        h: bottom - top,
        z: topZ() + 1
      }, slide.annotations.length);
      members.forEach(({ item }) => { item.clipFrameId = frame.id; });
      slide.annotations.push(frame);
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = frame.id;
      multiSelection = [selectionKey("annotation", frame.id)];
      commit(`Clipped ${members.length} ${members.length === 1 ? "item" : "items"} inside a movable rounded frame.`);
    }

