    function releaseSelectedClipFrame() {
      const slide = currentSlide();
      const frame = selectedClipFrame();
      if (!frame) return;
      const members = clipFrameMembers(frame, slide);
      members.forEach((item) => { item.clipFrameId = ""; });
      slide.annotations = slide.annotations.filter((item) => item.id !== frame.id);
      state.ui.selectedKind = members[0] ? "annotation" : null;
      state.ui.selectedId = members[0]?.id || null;
      multiSelection = members.map((item) => selectionKey("annotation", item.id));
      commit(`Released ${members.length} ${members.length === 1 ? "item" : "items"} from the clip frame.`);
    }

    function usesLargeAnnotationStartSize(value) {
      return /(?:^|\/)(?:shapes-text|bubbles|shapes)(?:\/|$)/i.test(String(value || "").split(/[?#]/, 1)[0]);
    }

    function naturalAnnotationStartSize(naturalWidth, naturalHeight, src = "") {
      const aspect = Math.max(0.01, Number(naturalWidth) / Math.max(1, Number(naturalHeight)));
      const stageAspect = 5 / 3;
      const largeAsset = usesLargeAnnotationStartSize(src);
      const maxWidth = largeAsset ? 58 : 40;
      const maxHeight = largeAsset ? 32 : 30;
      let width = maxWidth;
      let height = width * stageAspect / aspect;
      if (height > maxHeight) {
        height = maxHeight;
        width = height * aspect / stageAspect;
      }
      return {
        w: clamp(width, 5, maxWidth),
        h: clamp(height, 4, maxHeight)
      };
    }

    function sizeNewImageAnnotationFromAsset(annotation, slide, stateAfterInsert) {
      const probe = new Image();
      probe.onload = () => {
        if (!slide.annotations.some((item) => item.id === annotation.id)) return;
        if (annotation.w !== 22 || annotation.h !== 16) return;
        if (historySnapshot() !== stateAfterInsert) return;
        const size = naturalAnnotationStartSize(probe.naturalWidth, probe.naturalHeight, annotation.src);
        annotation.w = size.w;
        annotation.h = size.h;
        fitStageObjectBounds(annotation);
        committedSnapshot = historySnapshot();
        scheduleSave();
        render();
      };
      probe.src = resolveAnnotationAssetSrc(annotation.src);
    }

    function addImageAnnotation(type, src, label) {
      const slide = currentSlide();
      const annotation = normalizeAnnotation({
        id: uid(type),
        type,
        src,
        label,
        x: 50, y: 48, w: 22, h: 16,
        z: topZ() + 1
      }, slide.annotations.length);
      slide.annotations.push(assignNewAnnotationToActiveHotspot(annotation));
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = annotation.id;
      commit(`Added ${label || type}.`);
      sizeNewImageAnnotationFromAsset(annotation, slide, historySnapshot());
    }

    function addMarkup(kind) {
