        x: 50, y: 48,
        w: isPathMarkup(markup) ? 34 : 22,
        h: isPathMarkup(markup) ? 18 : 22,
        strokeWidth: isPathMarkup(markup) ? 3 : 4,
        markupPoints: isPathMarkup(markup) ? normalizeMarkupPoints(null, markup) : null,
        z: topZ() + 1
      }, slide.annotations.length);
      slide.annotations.push(assignNewAnnotationToActiveHotspot(annotation));
      state.ui.selectedKind = "annotation";
