    function addAnnotationFromUrl(type, value, videoLabel = "") {
      if (!["image", "video", "gif", "audio", "link"].includes(type)) return false;
      const cleanValue = String(value || "").trim();
      if (!cleanValue || cleanValue === mediaBase() || cleanValue === "https://") {
        showToast(`Add the ${type} URL first.`);
        return false;
      }
      const normalizedValue = normalizeHostedAnnotationUrl(type, cleanValue);
      if (type === "image" || type === "gif") {
        addImageAnnotation(type, normalizedValue, type === "gif" ? "GIF" : "Image");
        return true;
      }
      const slide = currentSlide();
      const annotation = normalizeAnnotation({
        id: uid(type),
        type,
        url: normalizedValue,
        label: type === "video" ? videoLabel || "Video" : type === "audio" ? "Audio" : "Link",
        x: 50,
        y: type === "audio" ? 76 : 48,
        w: type === "audio" ? 30 : type === "video" ? 24 : 12,
        h: type === "audio" ? 30 : type === "video" ? 22 : 12,
        z: topZ() + 1
      }, slide.annotations.length);
      slide.annotations.push(assignNewAnnotationToActiveHotspot(annotation));
      state.ui.selectedKind = "annotation";
      state.ui.selectedId = annotation.id;
      commit(`Added ${type} annotation.`);
      return true;
    }

    function toolbarAnnotationTypeLabel(type) {
      return ({ image: "image", video: "video", gif: "GIF", audio: "audio", link: "link" })[type] || "";
    }

