          value: toolbarAnnotationDraft.value,
          label: "Video popup title",
          placeholder: "VIDEO POPUP TITLE",
          title: "Optional title for the next video annotation"
        };
      }
      const label = toolbarAnnotationTypeLabel(mode);
      return {
        mode,
        value: toolbarAnnotationDraft.value,
        label: `${label} annotation URL`,
        placeholder: `PASTE ${label.toUpperCase()} URL + PRESS RETURN`,
        title: `Paste the full ${label} URL and press Return`
      };
