      if (!input) return;
      input.value = toolbarAnnotationDraft.mode === "link" ? toolbarAnnotationDraft.value : "https://";
    }

    function toolbarVideoLabel() {
      const input = document.getElementById("annotation-video-label");
      return String(input?.value ?? toolbarAnnotationDraft.videoTitle ?? "").trim();
    }

    function activateToolbarAnnotationUrl(type) {
      if (type !== "link") return;
      const input = document.getElementById("annotation-link-input");
      const value = String(input?.value || "").trim();
      toolbarAnnotationDraft = {
        ...toolbarAnnotationDraft,
        mode: "link",
        value: value || "https://"
      };
      if (addAnnotationFromUrl("link", value, "")) {
        resetToolbarAnnotationInput();
        return;
      }
      applyToolbarAnnotationInputDraft();
      const activeInput = document.getElementById("annotation-link-input");
      if (!activeInput) return;
      activeInput.focus();
      activeInput.setSelectionRange(activeInput.value.length, activeInput.value.length);
    }

    function resetToolbarAnnotationInput(clearVideoTitle = false) {
      const videoTitle = clearVideoTitle ? "" : String(toolbarAnnotationDraft.videoTitle || "");
      toolbarAnnotationDraft = { mode: "link", value: "https://", videoTitle };
      const videoInput = document.getElementById("annotation-video-label");
      if (videoInput && clearVideoTitle) videoInput.value = "";
      applyToolbarAnnotationInputDraft();
    }

    function addUrlAnnotation(type) {
      const input = document.getElementById(`annotation-${type}-url`);
      const value = input?.value.trim() || "";
      const videoLabel = toolbarVideoLabel();
      if (!addAnnotationFromUrl(type, value, videoLabel)) input?.focus();
    }

    function topZ() {
      const slide = currentSlide();
      return Math.max(1, ...slide.hotspots.map((item) => item.z), ...slide.annotations.map((item) => item.z));
    }

    function moveSelectedZ(direction) {
      const selection = selectedObjects();
      if (!selection.length) return;
      const slide = currentSlide();
      const layers = [
        ...slide.annotations.map((entry, index) => ({ item: entry, domOrder: index })),
        ...slide.hotspots.map((entry, index) => ({ item: entry, domOrder: slide.annotations.length + index }))
      ].sort((a, b) => a.item.z - b.item.z || a.domOrder - b.domOrder);
      const selectedItems = new Set(selection.map(({ item }) => item));
      const selectedLayers = layers.filter(({ item }) => selectedItems.has(item));
      const unselectedLayers = layers.filter(({ item }) => !selectedItems.has(item));
      const reorderedLayers = direction === "front"
        ? [...unselectedLayers, ...selectedLayers]
        : [...selectedLayers, ...unselectedLayers];
      const moved = reorderedLayers.some((entry, index) => entry !== layers[index]);
      if (!moved) {
        showToast(direction === "front"
          ? `${selection.length === 1 ? "Object is" : "Objects are"} already at the front.`
          : `${selection.length === 1 ? "Object is" : "Objects are"} already at the back.`);
        return;
      }
      reorderedLayers.forEach((entry, index) => {
        entry.item.z = index + 1;
      });
      commit(direction === "front"
        ? `Brought ${selection.length === 1 ? "object" : `${selection.length} objects`} to the front.`
        : `Sent ${selection.length === 1 ? "object" : `${selection.length} objects`} to the back.`);
    }

    function toggleSelectedLock() {
      const entries = selectedObjects();
      if (!entries.length) return;
      const lockItems = !entries.every(({ item }) => item.locked);
      entries.forEach(({ item }) => {
        item.locked = lockItems;
      });
      const scrollHotspotSelection = currentSlide()?.kind === "scroll" && entries.every(({ kind }) => kind === "hotspot");
      commit(lockItems
        ? scrollHotspotSelection
          ? `Locked ${entries.length === 1 ? "scroll hotspot" : `${entries.length} scroll hotspots`} in place. Scroll hotspots stay visible and open automatically when they enter view.`
          : `Locked ${entries.length === 1 ? "item" : `${entries.length} items`} and kept ${entries.length === 1 ? "it" : "them"} visible.`
        : `Unlocked ${entries.length === 1 ? "item" : `${entries.length} items`}.`);
    }

    function toggleSelectedHotspotGroup() {
      const grouping = hotspotGroupingSelection();
      if (!grouping.valid) {
        showToast("Select exactly one hotspot plus one or more annotations, then click Group with hotspot.");
        return;
      }
      const { hotspot, annotations } = grouping;
      const removeGroup = annotations.every(({ item }) => item.hotspotGroupId === hotspot.id);
      annotations.forEach(({ item }) => {
        item.hotspotGroupId = removeGroup ? "" : hotspot.id;
      });
      state.ui.activeHotspotId = hotspot.id;
      commit(removeGroup
        ? `Ungrouped ${annotations.length === 1 ? "annotation" : `${annotations.length} annotations`} from ${hotspot.title || "this hotspot"}.`
        : `Grouped ${annotations.length === 1 ? "annotation" : `${annotations.length} annotations`} with ${hotspot.title || "this hotspot"}.`);
    }

    function toggleSelectedObjectGroup(forceGrouped = null) {
      let grouping = objectGroupingSelection();
      if (forceGrouped === false && !grouping.grouped) {
        const existingGroup = objectGroupEntriesForItem(selectedObject());
        if (existingGroup.length >= 2) {
          grouping = {
            annotations: existingGroup,
            valid: true,
            grouped: true,
            groupId: existingGroup[0].item.objectGroupId
          };
        }
      }
      if (!grouping.valid) {
        showToast(forceGrouped === false
          ? "Select an item in an existing group first."
          : "Shift-select at least two annotations, such as text and a shape, then group them.");
        return;
      }
      if (forceGrouped === true && grouping.grouped) {
        showToast("Those items are already grouped.");
        return;
      }
      if (forceGrouped === false && !grouping.grouped) {
        showToast("The selected items are not one existing group.");
        return;
      }
      if (grouping.grouped) {
        grouping.annotations.forEach(({ item }) => {
          item.objectGroupId = "";
        });
        multiSelection = grouping.annotations.map(({ key }) => key);
        commit(`Ungrouped ${grouping.annotations.length} items.`);
        return;
      }
      const groupId = uid("object-group");
      grouping.annotations.forEach(({ item }) => {
        item.objectGroupId = groupId;
      });
      multiSelection = grouping.annotations.map(({ key }) => key);
      commit(`Grouped ${grouping.annotations.length} items so they move together.`);
    }

    function toggleShapeFlip(id) {
      const shape = currentSlide().annotations.find((item) => item.id === id && item.type === "shape");
      if (!shape) return;
      shape.flipX = !shape.flipX;
      commit(shape.flipX ? "Flipped shape side to side." : "Restored shape direction.");
    }

    function arrangeSelected(mode) {
      const arrangement = arrangementEntries();
      const entries = arrangement.entries;
      const verticalMax = stageVerticalPositionMax(currentSlide());
      const distribution = mode === "horizontal" || mode === "vertical";
      const minimum = distribution ? 3 : 2;
      if (entries.length < minimum) {
        if (entries.length === 1 && !distribution) {
          const item = entries[0].item;
          const pageHeight = verticalMax;
          if (mode === "left") item.x = item.w / 2;
          if (mode === "center") item.x = 50;
          if (mode === "right") item.x = 100 - item.w / 2;
          if (mode === "top") item.y = item.h / 2;
          if (mode === "middle") item.y = pageHeight / 2;
          if (mode === "bottom") item.y = pageHeight - item.h / 2;
          commit("Aligned selected item to the slide.");
          return;
        }
        showToast(distribution ? "Select at least three unlocked items." : "Select at least two unlocked items.");
        return;
      }
      if (mode === "left") {
        const left = Math.min(...entries.map(({ item }) => item.x - item.w / 2));
        entries.forEach(({ item }) => {
          item.x = clamp(left + item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "center") {
        const left = Math.min(...entries.map(({ item }) => item.x - item.w / 2));
        const right = Math.max(...entries.map(({ item }) => item.x + item.w / 2));
        const center = (left + right) / 2;
        entries.forEach(({ item }) => {
          item.x = clamp(center, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "right") {
        const right = Math.max(...entries.map(({ item }) => item.x + item.w / 2));
        entries.forEach(({ item }) => {
          item.x = clamp(right - item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "top") {
        const top = Math.min(...entries.map(({ item }) => item.y - item.h / 2));
        entries.forEach(({ item }) => {
          item.y = clamp(top + item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "middle") {
        const top = Math.min(...entries.map(({ item }) => item.y - item.h / 2));
        const bottom = Math.max(...entries.map(({ item }) => item.y + item.h / 2));
        const middle = (top + bottom) / 2;
        entries.forEach(({ item }) => {
          item.y = clamp(middle, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "bottom") {
        const bottom = Math.max(...entries.map(({ item }) => item.y + item.h / 2));
        entries.forEach(({ item }) => {
          item.y = clamp(bottom - item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "horizontal") {
        const ordered = entries.slice().sort((a, b) => a.item.x - b.item.x);
        const start = ordered[0].item.x - ordered[0].item.w / 2;
        const last = ordered[ordered.length - 1].item;
        const end = last.x + last.w / 2;
        const totalWidth = ordered.reduce((sum, { item }) => sum + item.w, 0);
        const gap = (end - start - totalWidth) / (ordered.length - 1);
        let cursor = start;
        ordered.forEach(({ item }) => {
          item.x = clamp(cursor + item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
          cursor += item.w + gap;
        });
      } else if (mode === "vertical") {
        const ordered = entries.slice().sort((a, b) => a.item.y - b.item.y);
        const start = ordered[0].item.y - ordered[0].item.h / 2;
        const last = ordered[ordered.length - 1].item;
        const end = last.y + last.h / 2;
        const totalHeight = ordered.reduce((sum, { item }) => sum + item.h, 0);
        const gap = (end - start - totalHeight) / (ordered.length - 1);
        let cursor = start;
        ordered.forEach(({ item }) => {
          item.y = clamp(cursor + item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
          cursor += item.h + gap;
        });
      }
      entries.forEach(({ item }) => fitStageObjectBounds(item));
      const target = arrangement.usesAllHotspots ? "all hotspots" : "selected items";
      const messages = {
        left: `Aligned ${target} left.`,
        center: `Aligned ${target} to center.`,
        top: `Aligned ${target} to top.`,
        middle: `Aligned ${target} to middle.`,
        bottom: `Aligned ${target} to bottom.`,
        horizontal: `Distributed ${target} horizontally.`,
        vertical: `Distributed ${target} vertically.`
      };
      commit(messages[mode]);
    }

    function duplicateSelectedItems() {
      const slide = currentSlide();
      const selection = selectedObjects();
      if (!selection.length) {
        showToast("Select an item to duplicate.");
        return;
      }
      if (selection.some(({ kind, item }) => kind === "annotation" && item.type === "slide-intro")) {
        showToast("A slide can have only one intro card.");
        return;
      }

      const selectedHotspots = selection.filter(({ kind }) => kind === "hotspot");
      const selectedAnnotations = selection.filter(({ kind }) => kind === "annotation");
      const hotspotIdMap = new Map(selectedHotspots.map(({ item }) => [item.id, uid("hotspot")]));
      const annotationIdMap = new Map(selectedAnnotations.map(({ item }) => [item.id, uid(item.type)]));
      const groupCounts = selectedAnnotations.reduce((counts, { item }) => {
        if (item.objectGroupId) counts.set(item.objectGroupId, (counts.get(item.objectGroupId) || 0) + 1);
        return counts;
      }, new Map());
      const objectGroupIdMap = new Map(
        [...groupCounts].filter(([, count]) => count > 1).map(([groupId]) => [groupId, uid("object-group")])
      );
      let nextZ = topZ();
      const offset = 2.5;

      const duplicateHotspots = selectedHotspots.map(({ item }, index) => {
        const copy = clone(item);
        copy.id = hotspotIdMap.get(item.id);
        copy.x = Number(copy.x || 0) + offset;
        copy.y = Number(copy.y || 0) + offset;
        copy.z = ++nextZ;
        copy.locked = false;
        copy.hotspotGroupId = hotspotIdMap.get(item.hotspotGroupId) || item.hotspotGroupId || "";
        return fitStageObjectBounds(normalizeHotspot(copy, slide.hotspots.length + index));
      });

      const duplicateAnnotations = selectedAnnotations.map(({ item }, index) => {
        const copy = clone(item);
        copy.id = annotationIdMap.get(item.id);
        copy.x = Number(copy.x || 0) + offset;
        copy.y = Number(copy.y || 0) + offset;
        copy.z = ++nextZ;
        copy.locked = false;
        copy.hotspotGroupId = hotspotIdMap.get(item.hotspotGroupId) || item.hotspotGroupId || "";
        copy.objectGroupId = objectGroupIdMap.get(item.objectGroupId) || "";
        copy.clipFrameId = annotationIdMap.get(item.clipFrameId) || item.clipFrameId || "";
        return fitStageObjectBounds(normalizeAnnotation(copy, slide.annotations.length + index));
      });

      slide.hotspots.push(...duplicateHotspots);
      slide.annotations.push(...duplicateAnnotations);
      if (duplicateHotspots.length) renumberHotspots(slide);

      const duplicateKeys = [
        ...duplicateHotspots.map((item) => selectionKey("hotspot", item.id)),
        ...duplicateAnnotations.map((item) => selectionKey("annotation", item.id))
      ];
      multiSelection = duplicateKeys;
      const primaryKind = state.ui.selectedKind;
      const primaryDuplicateId = primaryKind === "hotspot"
        ? hotspotIdMap.get(state.ui.selectedId)
        : annotationIdMap.get(state.ui.selectedId);
      const fallback = duplicateKeys.length ? selectionEntry(duplicateKeys[duplicateKeys.length - 1]) : null;
      state.ui.selectedKind = primaryDuplicateId ? primaryKind : fallback?.kind || null;
      state.ui.selectedId = primaryDuplicateId || fallback?.id || null;
      if (hotspotIdMap.has(state.ui.activeHotspotId)) {
        state.ui.activeHotspotId = hotspotIdMap.get(state.ui.activeHotspotId);
      }
      commit(`Duplicated ${selection.length} selected ${selection.length === 1 ? "item" : "items"}.`);
    }

    function copySelectedItemsToBuilderClipboard() {
      const selection = selectedObjects();
      if (!selection.length) {
        showToast("Select an item to copy.");
        return false;
      }
      objectClipboard = {
        sourceSlideId: currentSlide().id,
        hotspots: selection.filter(({ kind }) => kind === "hotspot").map(({ item }) => clone(item)),
        annotations: selection.filter(({ kind }) => kind === "annotation").map(({ item }) => clone(item)),
        primaryKind: state.ui.selectedKind,
        primaryId: state.ui.selectedId,
        activeHotspotId: state.ui.activeHotspotId
      };
      objectClipboardPasteCount = 0;
      showToast(`Copied ${selection.length} selected ${selection.length === 1 ? "item" : "items"}.`);
      return true;
    }

    function pasteBuilderClipboard() {
      if (!objectClipboard || (!objectClipboard.hotspots.length && !objectClipboard.annotations.length)) {
        showToast("Copy an item in the builder first.");
        return false;
      }
      const slide = currentSlide();
      if (slide.kind === "video" && objectClipboard.hotspots.length) {
        showToast("Hotspots cannot be pasted onto a video slide.");
        return false;
      }
      if (objectClipboard.annotations.some((item) => item.type === "slide-intro") && slideIntroCard(slide)) {
        showToast("This slide already has an intro card.");
        return false;
      }

      objectClipboardPasteCount += 1;
      const offset = Math.min(2.5 * objectClipboardPasteCount, 15);
      const hotspotIdMap = new Map(objectClipboard.hotspots.map((item) => [item.id, uid("hotspot")]));
      const annotationIdMap = new Map(objectClipboard.annotations.map((item) => [item.id, uid(item.type)]));
      const groupCounts = objectClipboard.annotations.reduce((counts, item) => {
        if (item.objectGroupId) counts.set(item.objectGroupId, (counts.get(item.objectGroupId) || 0) + 1);
        return counts;
      }, new Map());
      const objectGroupIdMap = new Map(
        [...groupCounts].filter(([, count]) => count > 1).map(([groupId]) => [groupId, uid("object-group")])
      );
      let nextZ = topZ();

      const pastedHotspots = objectClipboard.hotspots.map((source, index) => {
        const copy = clone(source);
        copy.id = hotspotIdMap.get(source.id);
        copy.x = Number(copy.x || 0) + offset;
        copy.y = Number(copy.y || 0) + offset;
        copy.z = ++nextZ;
        copy.locked = false;
        copy.hotspotGroupId = hotspotIdMap.get(source.hotspotGroupId)
          || (slide.hotspots.some((item) => item.id === source.hotspotGroupId) ? source.hotspotGroupId : "");
        return fitStageObjectBounds(normalizeHotspot(copy, slide.hotspots.length + index));
      });

      const pastedAnnotations = objectClipboard.annotations.map((source, index) => {
        const copy = clone(source);
        copy.id = annotationIdMap.get(source.id);
        copy.x = Number(copy.x || 0) + offset;
        copy.y = Number(copy.y || 0) + offset;
        copy.z = ++nextZ;
        copy.locked = false;
        copy.hotspotGroupId = hotspotIdMap.get(source.hotspotGroupId)
          || (slide.hotspots.some((item) => item.id === source.hotspotGroupId) ? source.hotspotGroupId : "");
        copy.objectGroupId = objectGroupIdMap.get(source.objectGroupId) || "";
        copy.clipFrameId = annotationIdMap.get(source.clipFrameId)
          || (slide.annotations.some((item) => item.id === source.clipFrameId) ? source.clipFrameId : "");
        return fitStageObjectBounds(normalizeAnnotation(copy, slide.annotations.length + index));
      });

      slide.hotspots.push(...pastedHotspots);
      slide.annotations.push(...pastedAnnotations);
      if (pastedHotspots.length) renumberHotspots(slide);
      const pastedKeys = [
        ...pastedHotspots.map((item) => selectionKey("hotspot", item.id)),
        ...pastedAnnotations.map((item) => selectionKey("annotation", item.id))
      ];
      multiSelection = pastedKeys;
      const primaryId = objectClipboard.primaryKind === "hotspot"
        ? hotspotIdMap.get(objectClipboard.primaryId)
        : annotationIdMap.get(objectClipboard.primaryId);
      const fallback = pastedKeys.length ? selectionEntry(pastedKeys[pastedKeys.length - 1]) : null;
      state.ui.selectedKind = primaryId ? objectClipboard.primaryKind : fallback?.kind || null;
      state.ui.selectedId = primaryId || fallback?.id || null;
      if (hotspotIdMap.has(objectClipboard.activeHotspotId)) {
        state.ui.activeHotspotId = hotspotIdMap.get(objectClipboard.activeHotspotId);
      }
      imageCropEditId = "";
      commit(`Pasted ${pastedKeys.length} ${pastedKeys.length === 1 ? "item" : "items"}.`);
      return true;
    }

    function deleteSelected() {
      const slide = currentSlide();
      if (!state.ui.selectedId) return;
      let message = "Deleted selected object.";
      stopAudio();
      if (state.ui.selectedKind === "hotspot") {
        const deletedHotspotId = state.ui.selectedId;
        slide.hotspots = slide.hotspots.filter((item) => item.id !== deletedHotspotId);
        renumberHotspots(slide);
        [...slide.hotspots, ...slide.annotations].forEach((item) => {
          if (item.hotspotGroupId === deletedHotspotId) item.hotspotGroupId = "";
        });
        state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
      } else {
        const deletedAnnotation = slide.annotations.find((item) => item.id === state.ui.selectedId);
        if (deletedAnnotation?.type === "clip-frame") {
          const released = clipFrameMembers(deletedAnnotation, slide);
          released.forEach((item) => { item.clipFrameId = ""; });
          message = `Deleted the clip frame and kept ${released.length} ${released.length === 1 ? "item" : "items"}.`;
        }
        slide.annotations = slide.annotations.filter((item) => item.id !== state.ui.selectedId);
        if (deletedAnnotation?.objectGroupId) {
          const remainingGroup = slide.annotations.filter((item) => item.objectGroupId === deletedAnnotation.objectGroupId);
          if (remainingGroup.length < 2) remainingGroup.forEach((item) => { item.objectGroupId = ""; });
        }
        if (deletedAnnotation?.type === "slide-intro") {
          state.ui.activeHotspotId = slide.hotspots[0]?.id || null;
        }
      }
      state.ui.selectedId = null;
      state.ui.selectedKind = null;
      commit(message);
    }

    async function addSlide(kind) {
      stopAudio();
      const previousSlide = currentSlide();
      const slide = createSlide(kind);
      slide.browserUrl = String(previousSlide?.browserUrl || "");
      slide.gptName = String(previousSlide?.gptName || "");
      state.tutorial.slides.splice(state.ui.slideIndex + 1, 0, slide);
      state.ui.slideIndex += 1;
      state.ui.activeHotspotId = null;
      state.ui.selectedKind = null;
      state.ui.selectedId = null;
      multiSelection = [];
      imageCropEditId = "";
      commit(kind === "video" ? "Added video slide." : kind === "scroll" ? "Added scroll slide." : "Added image slide.");
      await selectExistingMediaFile(kind);
    }

    async function replaceSlideMedia(kind) {
      stopAudio();
      await selectExistingMediaFile(kind);
    }

    function duplicateSlide() {
      if (state.ui.slideIndex === 0) return;
      stopAudio();
      const duplicate = clone(currentSlide());
      duplicate.id = uid(duplicate.kind);
      const hotspotIdMap = new Map(duplicate.hotspots.map((item) => [item.id, uid("hotspot")]));
      const objectGroupIdMap = new Map(
        duplicate.annotations
          .map((item) => item.objectGroupId)
          .filter(Boolean)
          .map((groupId) => [groupId, uid("object-group")])
      );
      const annotationIdMap = new Map(duplicate.annotations.map((item) => [item.id, uid(item.type)]));
      duplicate.hotspots = duplicate.hotspots.map((item) => ({
        ...item,
        id: hotspotIdMap.get(item.id),
        hotspotGroupId: hotspotIdMap.get(item.hotspotGroupId) || ""
      }));
      duplicate.annotations = duplicate.annotations.map((item) => ({
        ...item,
        id: annotationIdMap.get(item.id),
        hotspotGroupId: hotspotIdMap.get(item.hotspotGroupId) || "",
        objectGroupId: objectGroupIdMap.get(item.objectGroupId) || "",
        clipFrameId: annotationIdMap.get(item.clipFrameId) || ""
      }));
      state.tutorial.slides.splice(state.ui.slideIndex + 1, 0, duplicate);
      state.ui.slideIndex += 1;
      state.ui.activeHotspotId = duplicate.hotspots[0]?.id || null;
      state.ui.selectedKind = null;
      state.ui.selectedId = null;
      commit("Duplicated slide.");
    }

    function deleteSlide() {
      if (state.ui.slideIndex === 0) return;
      const slideNumber = state.ui.slideIndex;
      const slideTitle = currentSlide().title || `Slide ${slideNumber}`;
      if (!window.confirm(`Delete slide ${slideNumber}: ${slideTitle}?\n\nLater slide numbers will move up.`)) return;
      stopAudio();
      state.tutorial.slides.splice(state.ui.slideIndex, 1);
      // Keep the user among the editable slides whenever a later slide moves into
      // the deleted slide's position. Only move backward when the last slide was
      // deleted. This avoids unexpectedly landing on the locked cover slide.
      state.ui.slideIndex = clamp(state.ui.slideIndex, 0, state.tutorial.slides.length - 1);
      state.ui.activeHotspotId = slideIntroCard(currentSlide()) ? null : currentSlide().hotspots[0]?.id || null;
      state.ui.selectedKind = null;
      state.ui.selectedId = null;
      multiSelection = [];
      commit(state.ui.slideIndex === 0 ? "Deleted the only editable slide." : "Deleted slide. The next slide moved into its place.");
    }

    function moveSlide(direction) {
      const index = state.ui.slideIndex;
      const target = index + direction;
      if (index <= 0 || target <= 0 || target >= state.tutorial.slides.length) return;
      const [slide] = state.tutorial.slides.splice(index, 1);
      state.tutorial.slides.splice(target, 0, slide);
      state.ui.slideIndex = target;
      commit(direction < 0
        ? "Moved this slide earlier. The neighboring slide moved later."
        : "Moved this slide later. The neighboring slide moved earlier.");
    }

    function selectedInsertedImage() {
      if (state.ui.selectedKind !== "annotation") return null;
      const annotation = currentSlide().annotations.find((item) => item.id === state.ui.selectedId);
      return isCroppableAnnotation(annotation) ? annotation : null;
    }

    function selectedShadowAnnotation() {
      return selectedObject() || null;
    }

    function toggleInsertedImageCrop() {
      const image = selectedInsertedImage();
      if (!image) {
        showToast("Select an image, GIF, or shape first.");
        return;
      }
      if (imageCropEditId === image.id) {
        imageCropEditId = "";
        commit("Finished cropping the selected image or shape.");
        return;
      }
      if (!image.cropWindow) {
        const element = root.querySelector(`[data-object][data-id="${CSS.escape(image.id)}"] .annotation-asset-frame`);
        const img = element?.querySelector("img");
        if (!img?.naturalWidth || !element.clientWidth || !element.clientHeight) {
          showToast("Wait for the image to load before cropping.");
          return;
        }
        const w = element.clientWidth, h = element.clientHeight;
        const fit = (image.cropEnabled ? Math.max : Math.min)(w / img.naturalWidth, h / img.naturalHeight);
        const scale = image.cropEnabled ? image.cropScale || 1 : 1;
        const baseW = img.naturalWidth * fit, baseH = img.naturalHeight * fit;
        image.cropWindow = {
          width: baseW * scale / w * 100,
          height: baseH * scale / h * 100,
          left: ((w - baseW) * (image.cropEnabled ? image.cropX / 100 : .5) * scale + w * (1-scale)/2) / w * 100,
          top: ((h - baseH) * (image.cropEnabled ? image.cropY / 100 : .5) * scale + h * (1-scale)/2) / h * 100
        };
      }
      image.cropEnabled = true;
      image.cropScale = clamp(image.cropScale || 1, OVERLAY_CROP_MIN_SCALE, OVERLAY_CROP_MAX_SCALE);
      imageCropEditId = image.id;
      commit("Crop mode: drag the side or corner handles inward. Drag the image itself to reposition it, then click Done Crop.");
    }

    function toggleInsertedImageShadow() {
      const image = selectedShadowAnnotation();
      if (!image) {
        showToast("Select an image, GIF, shape, or markup annotation first.");
        return;
      }
      image.imageShadow = !image.imageShadow;
      commit(image.imageShadow ? "Added a lifted shadow." : "Removed the shadow.");
    }

    function zoomInsertedImageCrop(amount) {
      const image = selectedInsertedImage();
      if (!image?.cropEnabled) return;
      if (image.cropWindow) {
        const factor = amount > 0 ? 1.1 : 1 / 1.1;
        image.cropWindow.left = 50 + (image.cropWindow.left - 50) * factor;
        image.cropWindow.top = 50 + (image.cropWindow.top - 50) * factor;
        image.cropWindow.width *= factor;
        image.cropWindow.height *= factor;
      }
      image.cropScale = clamp((image.cropScale || 1) + amount, OVERLAY_CROP_MIN_SCALE, OVERLAY_CROP_MAX_SCALE);
      imageCropEditId = image.id;
      commit(amount > 0 ? "Cropped closer into the inserted image." : "Showed more of the inserted image.");
    }

    function selectedCornerAnnotation() {
      const item = state.ui.selectedKind === "annotation" ? selectedObject() : null;
      return isCroppableAnnotation(item) || (item?.type === "markup" && normalizeMarkupKind(item.markup).startsWith("square-")) ? item : null;
    }

    function setInsertedImageCornerRadius(value) {
      const image = selectedCornerAnnotation();
      if (!image) return;
      if (image.type === "markup") {
        image.markupCornerRadius = clamp(Number(value) || 0, 0, 50) * 43 / 50;
        commit(`Set rectangle corner rounding to ${value}%.`);
        return;
      }
      image.cornerRadius = clamp(Number(value) || 0, 0, 50);
      const label = image.cornerRadius === 0
        ? "square"
        : image.cornerRadius === 3 ? "soft" : image.cornerRadius === 10 ? "rounded" : image.cornerRadius === 50 ? "circular" : `${image.cornerRadius}% rounding`;
      commit(`Set inserted image corners to ${label}.`);
    }

    function resetInsertedImageEdit() {
      const image = selectedInsertedImage();
      if (!image) return;
      Object.assign(image, { cropEnabled: false, cropWindow: null, cropX: 50, cropY: 50, cropScale: 1, cornerRadius: 0 });
      if (imageCropEditId === image.id) imageCropEditId = "";
      commit("Reset the selected image or shape crop and corners.");
    }

    function setMediaFit(value) {
      currentSlide().media.fit = ["match", "contain", "cover"].includes(value) ? value : "contain";
      commit(`Set media to ${value}.`);
    }

    function nudgeMedia(dx, dy) {
      const media = currentSlide().media;
      media.x = clamp(media.x + dx, -40, 40);
      media.y = clamp(media.y + dy, -40, 40);
      commit("Moved main media.");
    }

    function nudgeSelectedObjects(dx, dy) {
      const entries = selectedObjects().filter(({ item }) => !item.locked);
      if (!entries.length) return;
      const verticalMax = stageVerticalPositionMax(currentSlide());
      entries.forEach(({ item }) => {
        const minX = item.type ? STAGE_ANNOTATION_MIN_X : STAGE_OBJECT_MIN_POSITION;
        const maxX = item.type ? STAGE_ANNOTATION_MAX_X : STAGE_OBJECT_MAX_POSITION;
        item.x = clamp((Number(item.x) || 0) + dx, minX, maxX);
        item.y = clamp((Number(item.y) || 0) + dy, STAGE_OBJECT_MIN_POSITION, verticalMax);
        fitStageObjectBounds(item);
        const element = root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`);
        if (element) element.style.cssText = objectStyle(item);
        if (item.type === "clip-frame") applyLiveClipFrameScene(item);
      });
      recordUndoStep();
      scheduleSave();
    }

    function zoomMedia(amount) {
      currentSlide().media.scale = clamp(currentSlide().media.scale + amount, MEDIA_MIN_SCALE, MEDIA_MAX_SCALE);
      commit("Resized main media.");
    }

    function resetMedia() {
      Object.assign(currentSlide().media, { x: 0, y: 0, scale: 1 });
      commit("Reset main media.");
    }

    function applyDefaultBackground() {
      stopAudio();
      const slide = createSlide("image");
      Object.assign(slide.media, {
        url: DEVICE_FRAME_URL,
        type: "image",
        fit: "contain",
        matte: "#ffffff",
        x: -3,
        y: 15,
        scale: 1.95,
        naturalWidth: 17178,
        naturalHeight: 11983
      });
      state.tutorial.slides.splice(state.ui.slideIndex + 1, 0, slide);
      state.ui.slideIndex += 1;
      state.ui.activeHotspotId = null;
      state.ui.selectedKind = null;
      state.ui.selectedId = null;
      multiSelection = [];
      imageCropEditId = "";
      commit("Added a new default-background slide at 195% size, 3% left and 15% down.");
    }

    function coverSlide() {
      return state.tutorial.slides.find((slide) => slide.kind === "cover") || state.tutorial.slides[0];
    }

    async function replaceCoverBackground() {
      stopAudio();
      const cover = coverSlide();
      if (!cover) {
        showToast("The cover slide is unavailable.");
        return;
      }
      await selectExistingMediaFile("image", cover.id);
    }

    function applyDefaultCoverBackground() {
      stopAudio();
      const cover = coverSlide();
      if (!cover) {
        showToast("The cover slide is unavailable.");
        return;
      }
      Object.assign(cover.media, {
        url: DEVICE_FRAME_URL,
        type: "image",
        fit: "contain",
        matte: "#ffffff",
        x: -3,
        y: 15,
        scale: 1.95,
        naturalWidth: 17178,
        naturalHeight: 11983
      });
      commit("Applied the default background to the cover at 195% size, 3% left and 15% down.");
    }

    function demoSlideDurationMs(slide = currentSlide()) {
      const seconds = slide?.demo?.manualDuration !== null && slide?.demo?.manualDuration !== undefined
        ? slide.demo.manualDuration
        : state.meta.demoDefaultDuration;
      return clamp(Number(seconds) || DEMO_DEFAULT_DURATION, DEMO_MIN_DURATION, DEMO_MAX_DURATION) * 1000;
    }

    function syncDemoAudioTiming(slide = currentSlide()) {
      const hasAudio = Boolean(String(slide?.demo?.audioUrl || "").trim());
      const hasManualOverride = slide?.demo?.manualDuration !== null
        && slide?.demo?.manualDuration !== undefined
        && slide?.demo?.manualDuration !== "";
      slide.demo.timing = hasManualOverride ? "manual" : hasAudio ? "audio" : "default";
      const timingSelect = root.querySelector("#demoTimingMode");
      if (timingSelect) timingSelect.value = slide.demo.timing;
      const durationInput = root.querySelector("#demoSlideDuration");
      if (durationInput) durationInput.disabled = slide.demo.timing !== "manual";
    }

    function demoSlideProgress() {
      if (!demoStarted) return 0;
      const slide = currentSlide();
      if (slide?.demo?.timing === "audio" && demoAudio && Number.isFinite(demoAudio.duration) && demoAudio.duration > 0) {
        return clamp(demoAudio.currentTime / demoAudio.duration, 0, 1);
      }
      if (demoTotalMs <= 0) return 0;
      const remaining = demoPlaying && demoDeadline
        ? Math.max(0, demoDeadline - performance.now())
        : demoRemainingMs;
      return clamp(1 - (remaining / demoTotalMs), 0, 1);
    }

    function demoOverallProgress() {
      if (demoFinished) return 100;
      const count = Math.max(1, state.tutorial.slides.length);
      return clamp(((state.ui.slideIndex + demoSlideProgress()) / count) * 100, 0, 100).toFixed(1);
    }

    function formatDemoTime(seconds) {
      const value = Math.max(0, Number(seconds) || 0);
      const minutes = Math.floor(value / 60);
      const remainder = Math.floor(value % 60);
      return `${minutes}:${String(remainder).padStart(2, "0")}`;
    }

    function demoProgressText() {
      return `${Math.round(Number(demoOverallProgress()))}% complete`;
    }

    function updateDemoPlaybackUi() {
      if (!IS_DEMO_PLAYER || demoSeekPreview !== null) return;
      const mainVideo = slideHasMainVideo(currentSlide()) ? root.querySelector("[data-main-video]") : null;
      if (mainVideo) {
        const duration = Number.isFinite(mainVideo.duration) ? mainVideo.duration : 0;
        updateDemoVideoControls(mainVideo, duration, clamp(mainVideo.currentTime || 0, 0, duration));
        return;
      }
      const seek = root.querySelector("[data-demo-seek]");
      const toggle = root.querySelector('[data-action="demo-toggle"]');
      const value = String(demoOverallProgress());
      const text = demoProgressText();
      if (seek) {
        seek.value = value;
        seek.setAttribute("aria-valuetext", text);
      }
      if (toggle) {
        const playLabel = demoStarted && demoPlaying ? "Pause" : demoFinished ? "Replay" : "Play";
        toggle.innerHTML = icon(demoStarted && demoPlaying ? "pause" : "play");
        toggle.setAttribute("title", playLabel);
        toggle.setAttribute("aria-label", `${playLabel} demo`);
        toggle.setAttribute("aria-pressed", String(demoStarted && demoPlaying));
      }
    }

    function clearDemoTimers() {
      window.clearTimeout(demoTimer);
      window.clearInterval(demoProgressTimer);
      demoTimer = 0;
      demoProgressTimer = 0;
      demoDeadline = 0;
    }

    function ensureDemoAudio() {
      if (!demoAudio) {
        demoAudio = new Audio();
        demoAudio.preload = "metadata";
      }
      return demoAudio;
    }

    function primeDemoAudio() {
      if (demoAudioPrimed) return;
      const audioSlide = state.tutorial.slides.find((slide) => String(slide?.demo?.audioUrl || "").trim());
      const url = String(audioSlide?.demo?.audioUrl || "").trim();
      if (!url) return;
      const audio = ensureDemoAudio();
      let absoluteUrl = url;
      try { absoluteUrl = new URL(url, location.href).href; } catch (_) {}
      audio.pause();
      audio.src = absoluteUrl;
      audio.muted = true;
      audio.load();
      let settled = false;
      demoAudioPrimePromise = new Promise((resolve) => {
        const finish = (primed) => {
          if (settled) return;
          settled = true;
          window.clearTimeout(timeout);
          audio.pause();
          try { audio.currentTime = 0; } catch (_) {}
          audio.muted = false;
          demoAudioPrimed = primed;
          resolve();
        };
        const timeout = window.setTimeout(() => finish(false), 1500);
        try {
          const playRequest = audio.play();
          if (playRequest && typeof playRequest.then === "function") playRequest.then(() => finish(true)).catch(() => finish(false));
          else finish(true);
        } catch (_) {
          finish(false);
        }
      });
    }

    function prepareDemoAudio(slide, fraction = 0, resume = false) {
      const url = String(slide?.demo?.audioUrl || "").trim();
      if (!url) return null;
      const audio = ensureDemoAudio();
      let absoluteUrl = url;
      try { absoluteUrl = new URL(url, location.href).href; } catch (_) {}
      if (!resume || audio.src !== absoluteUrl) {
        audio.pause();
        audio.src = absoluteUrl;
        audio.load();
      }
      const applyFraction = () => {
        if (fraction > 0 && Number.isFinite(audio.duration) && audio.duration > 0) {
          audio.currentTime = clamp(fraction, 0, .999) * audio.duration;
        } else if (!resume && fraction <= 0) {
          audio.currentTime = 0;
        }
        if (slide.demo.timing === "audio" && Number.isFinite(audio.duration) && audio.duration > 0) {
          demoTotalMs = audio.duration * 1000;
          demoRemainingMs = Math.max(0, (audio.duration - audio.currentTime) * 1000);
        }
        updateDemoPlaybackUi();
      };
      if (audio.readyState >= 1) applyFraction();
      else audio.addEventListener("loadedmetadata", applyFraction, { once: true });
      return audio;
    }

    function scheduleDemoTimer(milliseconds) {
      const delay = Math.max(0, Number(milliseconds) || 0);
      window.clearTimeout(demoTimer);
      demoRemainingMs = delay;
      demoDeadline = performance.now() + delay;
      demoTimer = window.setTimeout(advanceDemoPlayback, delay);
    }

    function startDemoProgressTicker() {
      window.clearInterval(demoProgressTimer);
      demoProgressTimer = window.setInterval(updateDemoPlaybackUi, 120);
      updateDemoPlaybackUi();
    }

    async function startDemoSlidePlayback({ fraction = 0, resume = false } = {}) {
      if (!IS_DEMO_PLAYER || !demoPlaying) return;
      const playbackRequest = ++demoPlaybackRequest;
      clearDemoTimers();
      const slide = currentSlide();
      const slideId = slide.id;
      await playerVisualReadyPromise;
      if (!IS_DEMO_PLAYER || !demoPlaying || playbackRequest !== demoPlaybackRequest || currentSlide()?.id !== slideId) return;
      if (slideHasMainVideo(slide)) {
        const video = root.querySelector("[data-main-video]");
        if (!video) return;
        video.loop = true;
        video.muted = !demoVideoSoundEnabled;
        if (!resume) {
          const duration = Number.isFinite(video.duration) ? video.duration : 0;
          video.currentTime = duration > 0 ? clamp(fraction, 0, .999) * duration : 0;
        }
        try {
          await video.play();
        } catch (_) {
          demoPlaying = false;
        }
        startDemoProgressTicker();
        updateDemoPlaybackUi();
        return;
      }
      await demoAudioPrimePromise;
      if (!IS_DEMO_PLAYER || !demoPlaying || playbackRequest !== demoPlaybackRequest || currentSlide()?.id !== slideId) return;
      const timing = slide.demo.timing;
      if (resume && demoAudioEndDelayActive) {
        scheduleDemoTimer(demoRemainingMs || DEMO_AUDIO_END_DELAY_MS);
        startDemoProgressTicker();
        return;
      }
      if (!resume) demoAudioEndDelayActive = false;
      if (!resume) {
        demoTotalMs = demoSlideDurationMs(slide);
        demoRemainingMs = demoTotalMs * (1 - clamp(fraction, 0, .999));
      }
      const audio = prepareDemoAudio(slide, fraction, resume);
      if (audio) {
        const slideId = slide.id;
        audio.onended = () => {
          if (demoPlaying && currentSlide()?.id === slideId && timing === "audio") {
            demoAudioEndDelayActive = true;
            scheduleDemoTimer(DEMO_AUDIO_END_DELAY_MS);
          }
        };
        audio.onerror = () => {
          if (!demoPlaying || currentSlide()?.id !== slideId) return;
          demoAudioEndDelayActive = false;
          if (timing === "audio") {
            demoTotalMs = demoSlideDurationMs(slide);
            scheduleDemoTimer(demoTotalMs * (1 - clamp(fraction, 0, .999)));
          }
          updateDemoPlaybackUi();
        };
        audio.play().catch(() => {
          demoAudioEndDelayActive = false;
          if (timing === "audio" && demoPlaying) {
            demoTotalMs = demoSlideDurationMs(slide);
            scheduleDemoTimer(demoRemainingMs || demoTotalMs);
          }
          updateDemoPlaybackUi();
        });
      }
      if (timing !== "audio" || !audio) scheduleDemoTimer(demoRemainingMs || demoTotalMs);
      startDemoProgressTicker();
    }

    function stopDemoSlidePlayback({ captureRemaining = true } = {}) {
      demoPlaybackRequest += 1;
      if (captureRemaining && demoDeadline) demoRemainingMs = Math.max(0, demoDeadline - performance.now());
      clearDemoTimers();
      if (demoAudio) {
        demoAudio.pause();
        demoAudio.onended = null;
        demoAudio.onerror = null;
      }
      root.querySelectorAll("[data-main-video]").forEach((video) => video.pause());
    }

    function pauseDemoPlayback() {
      if (!demoStarted || !demoPlaying) return;
      demoPlaying = false;
      stopDemoSlidePlayback({ captureRemaining: true });
      updateDemoPlaybackUi();
    }

    function resumeDemoPlayback() {
      if (!demoStarted || demoPlaying) return;
      if (demoFinished) {
        restartDemoPlayback();
        return;
      }
      primeDemoAudio();
      demoPlaying = true;
      startDemoSlidePlayback({ resume: true });
      updateDemoPlaybackUi();
    }

    function setDemoSlide(index, { fraction = 0, play = demoPlaying } = {}) {
      stopDemoSlidePlayback();
      demoAudioEndDelayActive = false;
      state.ui.slideIndex = clamp(index, 0, state.tutorial.slides.length - 1);
      const slide = currentSlide();
      state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
      if (slide.kind === "scroll") {
        scrollSlidePositions.set(slide.id, 0);
        if (state.ui.activeHotspotId) scrollExpandedHotspots.set(slide.id, state.ui.activeHotspotId);
      }
      state.ui.selectedKind = null;
      state.ui.selectedId = null;
      state.ui.contentsOpen = false;
      state.ui.videoModalId = null;
      demoFinished = false;
      demoPlaying = Boolean(play);
      demoTotalMs = demoSlideDurationMs(slide);
      demoRemainingMs = demoTotalMs * (1 - clamp(fraction, 0, .999));
      render();
      if (demoPlaying) startDemoSlidePlayback({ fraction });
      else prepareDemoAudio(slide, fraction, false);
      updateDemoPlaybackUi();
    }

    function advanceDemoPlayback() {
      stopDemoSlidePlayback();
      demoAudioEndDelayActive = false;
      if (state.ui.slideIndex >= state.tutorial.slides.length - 1) {
        demoFinished = true;
        demoPlaying = false;
        demoRemainingMs = 0;
        updateDemoPlaybackUi();
        return;
      }
      setDemoSlide(state.ui.slideIndex + 1, { fraction: 0, play: true });
    }

    function restartDemoPlayback() {
      if (slideHasMainVideo(currentSlide())) {
        const video = root.querySelector("[data-main-video]");
        if (!video) return;
        demoStarted = true;
        demoFinished = false;
        demoPlaying = true;
        video.currentTime = 0;
        video.muted = !demoVideoSoundEnabled;
        video.loop = true;
        video.play().catch(() => {
          demoPlaying = false;
          updateDemoPlaybackUi();
        });
        startDemoProgressTicker();
        updateDemoPlaybackUi();
        return;
      }
      demoStarted = true;
      demoFinished = false;
      demoPlaying = true;
      primeDemoAudio();
      setDemoSlide(0, { fraction: 0, play: true });
    }

    function toggleDemoPlayback() {
      if (!demoVideoGateDismissed && demoVideoTargetIndex() >= 0) startDemoVideoWithSound();
      else if (slideHasMainVideo(currentSlide())) toggleDemoMainVideo();
      else if (!demoStarted || demoFinished) restartDemoPlayback();
      else if (demoPlaying) pauseDemoPlayback();
      else resumeDemoPlayback();
    }

    function toggleDemoMainVideo() {
      const video = root.querySelector("[data-main-video]");
      if (!video) return;
      demoStarted = true;
      demoFinished = false;
      if (video.paused) {
        if (Number.isFinite(video.duration) && video.currentTime >= video.duration) video.currentTime = 0;
        demoPlaying = true;
        video.play().catch(() => {
          demoPlaying = false;
          updateDemoPlaybackUi();
        });
        startDemoProgressTicker();
      } else {
        video.pause();
        demoPlaying = false;
        clearDemoTimers();
      }
      updateDemoPlaybackUi();
    }

    function startDemoVideoWithSound() {
      const targetIndex = demoVideoTargetIndex();
      if (targetIndex < 0) return;
      demoVideoGateDismissed = true;
      demoVideoSoundEnabled = true;
      demoStarted = true;
      demoFinished = false;
      demoPlaying = true;
      if (targetIndex !== state.ui.slideIndex) setDemoSlide(targetIndex, { play: false });
      const video = root.querySelector("[data-main-video]");
      if (!video) return;
      demoPlaying = true;
      root.querySelector(".demo-video-sound-gate")?.remove();
      video.loop = true;
      video.muted = false;
      video.currentTime = 0;
      const playRequest = video.play();
      if (playRequest && typeof playRequest.catch === "function") {
        playRequest.catch(() => {
          demoPlaying = false;
          updateDemoPlaybackUi();
          showToast("Use the play button to start this video with sound.");
        });
      }
      startDemoProgressTicker();
      updateDemoPlaybackUi();
    }

    function toggleDemoVideoSound() {
      const video = root.querySelector("[data-main-video]");
      if (!video) return;
      demoVideoGateDismissed = true;
      demoVideoSoundEnabled = video.muted;
      video.muted = !demoVideoSoundEnabled;
      root.querySelector(".demo-video-sound-gate")?.remove();
      updateDemoPlaybackUi();
    }

    function previewDemoSeek(value) {
      if (slideHasMainVideo(currentSlide())) {
        const video = root.querySelector("[data-main-video]");
        if (!video) return;
        video.currentTime = clamp(Number(value), 0, Number.isFinite(video.duration) ? video.duration : 0);
        updateDemoPlaybackUi();
        return;
      }
      const preview = clamp(Number(value), 0, 100);
      if (demoSeekPreview === null) {
        demoSeekResumeAfter = demoPlaying;
        demoSeekPreview = preview;
        pauseDemoPlayback();
      } else {
        demoSeekPreview = preview;
      }
    }

    function commitDemoSeek(value) {
      if (slideHasMainVideo(currentSlide())) {
        const video = root.querySelector("[data-main-video]");
        if (!video) return;
        video.currentTime = clamp(Number(value), 0, Number.isFinite(video.duration) ? video.duration : 0);
        updateDemoPlaybackUi();
        return;
      }
      const percent = clamp(Number(value), 0, 100);
      const count = Math.max(1, state.tutorial.slides.length);
      const position = percent >= 100 ? count - Number.EPSILON : (percent / 100) * count;
      const index = Math.min(count - 1, Math.floor(position));
      const fraction = clamp(position - index, 0, .999);
      const shouldResume = demoSeekResumeAfter;
      demoSeekPreview = null;
      demoSeekResumeAfter = false;
      demoStarted = true;
      setDemoSlide(index, { fraction, play: shouldResume });
    }

    function readerNext() {
      if (MODE === "builder") stopSlideNarrationPreview();
      if (IS_DEMO_PLAYER) {
        const slide = currentSlide();
        if (slide.kind === "scroll") {
          if (state.ui.slideIndex < state.tutorial.slides.length - 1) setDemoSlide(state.ui.slideIndex + 1, { play: demoPlaying });
          return;
        }
        const index = slide.hotspots.findIndex((item) => item.id === state.ui.activeHotspotId);
        if (slide.hotspots.length && index < slide.hotspots.length - 1) {
          state.ui.activeHotspotId = slide.hotspots[Math.max(0, index + 1)].id;
          render();
          drawAttentionToHotspot(state.ui.activeHotspotId);
          updateDemoPlaybackUi();
        } else if (state.ui.slideIndex < state.tutorial.slides.length - 1) {
          setDemoSlide(state.ui.slideIndex + 1, { play: demoPlaying });
        }
        return;
      }
      const slide = currentSlide();
      if (slide.kind === "scroll") {
        if (state.ui.slideIndex < state.tutorial.slides.length - 1) jumpSlide(state.ui.slideIndex + 1);
        return;
      }
      if (slide.hotspots.length) {
        const index = slide.hotspots.findIndex((item) => item.id === state.ui.activeHotspotId);
        if (index < slide.hotspots.length - 1) {
          stopAudio();
          const nextHotspotId = slide.hotspots[index + 1].id;
          state.ui.activeHotspotId = nextHotspotId;
          state.ui.selectedKind = null;
          state.ui.selectedId = null;
          multiSelection = [];
          render();
          drawAttentionToHotspot(nextHotspotId);
          return;
        }
      }
      if (state.ui.slideIndex < state.tutorial.slides.length - 1) jumpSlide(state.ui.slideIndex + 1);
    }

    function readerBack() {
      if (MODE === "builder") stopSlideNarrationPreview();
      if (IS_DEMO_PLAYER) {
        const slide = currentSlide();
        if (slide.kind === "scroll") {
          if (state.ui.slideIndex > 0) setDemoSlide(state.ui.slideIndex - 1, { play: demoPlaying });
          return;
        }
        const index = slide.hotspots.findIndex((item) => item.id === state.ui.activeHotspotId);
        if (index === 0 && slideIntroCard(slide)) {
          state.ui.activeHotspotId = null;
          render();
          updateDemoPlaybackUi();
        } else if (index > 0) {
          state.ui.activeHotspotId = slide.hotspots[index - 1].id;
          render();
          drawAttentionToHotspot(state.ui.activeHotspotId);
          updateDemoPlaybackUi();
        } else if (state.ui.slideIndex > 0) {
          setDemoSlide(state.ui.slideIndex - 1, { play: demoPlaying });
          const previous = currentSlide();
          if (previous.hotspots.length) {
            state.ui.activeHotspotId = previous.hotspots[previous.hotspots.length - 1].id;
            render();
            updateDemoPlaybackUi();
          }
        }
        return;
      }
      const slide = currentSlide();
      if (slide.kind === "scroll") {
        if (state.ui.slideIndex > 0) jumpSlide(state.ui.slideIndex - 1, true);
        return;
      }
      if (slide.hotspots.length) {
        const index = slide.hotspots.findIndex((item) => item.id === state.ui.activeHotspotId);
        if (index === 0 && slideIntroCard(slide)) {
          stopAudio();
          state.ui.activeHotspotId = null;
          state.ui.selectedKind = null;
          state.ui.selectedId = null;
          multiSelection = [];
          render();
          return;
        }
        if (index > 0) {
          stopAudio();
          const previousHotspotId = slide.hotspots[index - 1].id;
          state.ui.activeHotspotId = previousHotspotId;
          state.ui.selectedKind = null;
          state.ui.selectedId = null;
          multiSelection = [];
          render();
          drawAttentionToHotspot(previousHotspotId);
          return;
        }
      }
      if (state.ui.slideIndex > 0) {
        jumpSlide(state.ui.slideIndex - 1, true);
      }
    }

    function jumpSlide(index, useLastHotspot = false) {
      if (MODE === "builder") stopSlideNarrationPreview();
      if (IS_DEMO_PLAYER) {
        const shouldResume = demoPlaying || demoMenuResumeAfter;
        demoMenuResumeAfter = false;
        demoStarted = true;
        setDemoSlide(index, { play: shouldResume });
        return;
      }
      stopAudio();
      state.ui.slideIndex = clamp(index, 0, state.tutorial.slides.length - 1);
      const slide = currentSlide();
      const lastHotspot = slide.hotspots[slide.hotspots.length - 1];
      state.ui.activeHotspotId = useLastHotspot
        ? lastHotspot?.id || null
        : slideIntroCard(slide)
          ? null
          : slide.hotspots[0]?.id || null;
