    async function toggleSlideNarrationPreview() {
      const slide = currentSlide();
      const url = String(slide?.demo?.audioUrl || "").trim();
      if (!url) {
        showToast("Choose slide narration audio first.");
        return;
      }
      if (slideNarrationPreviewAudio
          && slideNarrationPreviewSlideId === slide.id
          && slideNarrationPreviewPlaying) {
        slideNarrationPreviewAudio.pause();
        slideNarrationPreviewPlaying = false;
        render();
        return;
      }
      if (!slideNarrationPreviewAudio || slideNarrationPreviewSlideId !== slide.id) {
        stopSlideNarrationPreview();
        const audio = new Audio();
        audio.preload = "auto";
        audio.src = url;
        slideNarrationPreviewAudio = audio;
        slideNarrationPreviewSlideId = slide.id;
        audio.addEventListener("ended", () => {
          if (slideNarrationPreviewAudio !== audio) return;
          slideNarrationPreviewPlaying = false;
          try { audio.currentTime = 0; } catch (_) {}
          render();
        });
        audio.addEventListener("error", () => {
          if (slideNarrationPreviewAudio !== audio) return;
          stopSlideNarrationPreview();
          render();
          showToast("The slide narration audio could not be played. Check the uploaded audio file.");
        });
      }
      const audio = slideNarrationPreviewAudio;
      try {
        audio.currentTime = 0;
        await audio.play();
        if (slideNarrationPreviewAudio !== audio || currentSlide()?.id !== slide.id) {
          audio.pause();
          return;
        }
        slideNarrationPreviewPlaying = true;
        render();
      } catch (_) {
        slideNarrationPreviewPlaying = false;
        render();
        showToast("The browser could not start this slide narration audio.");
      }
    }

    function stopAudio() {
      if (window.__tutorialAudio) {
