    function rewindAudio(id) {
      if (window.__tutorialAudio && activeAudio === id) window.__tutorialAudio.currentTime = 0;
      else {
        const annotation = currentSlide().annotations.find((item) => item.id === id);
        if (!annotation?.url) return;
        stopAudio();
        window.__tutorialAudio = createTutorialAudio(annotation.url, id);
        activeAudio = id;
        audioPlaying = false;
        window.__tutorialAudio.currentTime = 0;
      }
      render();
    }

    function createTutorialAudio(url, id) {
      const audio = new Audio();
      audio.preload = "metadata";
      audio.crossOrigin = "anonymous";
      audio.src = normalizeHostedAnnotationUrl("audio", url);
      const updateTimeline = () => {
        if (window.__tutorialAudio === audio && activeAudio === id) updateAudioTimeline(id);
      };
      audio.addEventListener("loadedmetadata", updateTimeline);
      audio.addEventListener("durationchange", updateTimeline);
      audio.addEventListener("timeupdate", updateTimeline);
      audio.addEventListener("ended", () => {
        if (window.__tutorialAudio !== audio || activeAudio !== id) return;
        activeAudio = null;
        audioPlaying = false;
        render();
      });
      return audio;
    }

    function updateAudioTimeline(id) {
      const audio = window.__tutorialAudio;
      const timeline = root.querySelector(`[data-audio-timeline][data-id="${CSS.escape(id)}"]`);
      if (!audio || activeAudio !== id || !timeline) return;
      const duration = Number.isFinite(audio.duration) ? audio.duration : 0;
      const currentTime = clamp(audio.currentTime, 0, duration);
      timeline.max = String(duration);
      timeline.value = String(currentTime);
      timeline.setAttribute("aria-valuetext", `${formatVideoTime(currentTime)} of ${formatVideoTime(duration)}`);
    }

    function audioFailureMessage(audio) {
      const code = audio?.error?.code || 0;
      if (code === 2) return "Audio could not load because of a network error. Check the direct file URL.";
      if (code === 3) return "The browser could not decode this audio file.";
      if (code === 4) return "Audio URL did not return a supported audio file. Check the hosted path.";
      return "The browser could not start this audio. Check that the URL opens the audio file directly.";
    }

    async function toggleAudio(id) {
