      if (!window.__tutorialAudio || activeAudio !== id) {
        stopAudio();
        window.__tutorialAudio = createTutorialAudio(annotation.url, id);
        activeAudio = id;
        audioPlaying = false;
      }
      if (window.__tutorialAudio.paused) {
        try {
          await window.__tutorialAudio.play();
          audioPlaying = true;
        } catch (_) {
          audioPlaying = false;
          showToast(audioFailureMessage(window.__tutorialAudio));
        }
      } else {
        window.__tutorialAudio.pause();
        audioPlaying = false;
      }
      render();
      if (audioPlaying) updateAudioTimeline(id);
    }

