    function applyHeadMetadata(documentElement, exportState) {
      const head = documentElement.querySelector("head");
      const metadata = metadataForExport(exportState);
      head.querySelector("title").textContent = `${metadata.title} | Magic Hashtags`;
      setMeta(head, "name", "description", metadata.description);
      setMeta(head, "property", "og:type", "website");
      setMeta(head, "property", "og:site_name", "Magic Hashtags");
      setMeta(head, "property", "og:title", metadata.title);
      setMeta(head, "property", "og:description", metadata.description);
      setMeta(head, "property", "og:url", metadata.url);
      setMeta(head, "property", "og:image", metadata.image);
      setMeta(head, "property", "og:image:alt", metadata.alt);
      setMeta(head, "name", "twitter:card", "summary_large_image");
      setMeta(head, "name", "twitter:title", metadata.title);
      setMeta(head, "name", "twitter:description", metadata.description);
      setMeta(head, "name", "twitter:image", metadata.image);
      setMeta(head, "name", "twitter:image:alt", metadata.alt);
      let canonical = head.querySelector('link[rel="canonical"]');
      if (!canonical) {
        canonical = documentElement.ownerDocument.createElement("link");
        canonical.rel = "canonical";
        head.append(canonical);
      }
      canonical.href = metadata.url;
    }

    function setMeta(head, attribute, key, content) {
      let node = head.querySelector(`meta[${attribute}="${key}"]`);
      if (!node) {
        node = head.ownerDocument.createElement("meta");
        node.setAttribute(attribute, key);
        head.append(node);
      }
      node.content = content;
    }

    function applyExportFont(documentElement) {
      const fontUrl = "/fonts/hanken-grotesk-latin.woff2";
      const absoluteFontUrl = "https://magichashtags.com/fonts/hanken-grotesk-latin.woff2";
      const italicFontUrl = "/fonts/hanken-grotesk-latin-italic.woff2";
      const absoluteItalicFontUrl = "https://magichashtags.com/fonts/hanken-grotesk-latin-italic.woff2";
      const impactLabelUrl = "/fonts/Impact_Label.ttf";
      const absoluteImpactLabelUrl = "https://magichashtags.com/fonts/Impact_Label.ttf";
      const impactLabelReversedUrl = "/fonts/Impact_Label_Reversed.ttf";
      const absoluteImpactLabelReversedUrl = "https://magichashtags.com/fonts/Impact_Label_Reversed.ttf";
      const preload = documentElement.querySelector("#hanken-grotesk-preload");
      const impactLabelPreload = documentElement.querySelector("#impact-label-preload");
      const impactLabelReversedPreload = documentElement.querySelector("#impact-label-reversed-preload");
      const fontFace = documentElement.querySelector("#hanken-grotesk-font-face");
      const impactLabelFontFace = documentElement.querySelector("#impact-label-font-face");
      const impactLabelReversedFontFace = documentElement.querySelector("#impact-label-reversed-font-face");
      const impactLabelEmbeddedUrl = impactLabelFontFace?.textContent.match(/url\("(data:font\/ttf;base64,[^"]+)"\)/)?.[1] || "";
      const impactLabelReversedEmbeddedUrl = impactLabelReversedFontFace?.textContent.match(/url\("(data:font\/ttf;base64,[^"]+)"\)/)?.[1] || "";
      const impactLabelSources = [
        `url("${impactLabelUrl}") format("truetype")`,
        `url("${absoluteImpactLabelUrl}") format("truetype")`,
        impactLabelEmbeddedUrl ? `url("${impactLabelEmbeddedUrl}") format("truetype")` : ""
      ].filter(Boolean).join(",\n        ");
      const impactLabelReversedSources = [
        `url("${impactLabelReversedUrl}") format("truetype")`,
        `url("${absoluteImpactLabelReversedUrl}") format("truetype")`,
        impactLabelReversedEmbeddedUrl ? `url("${impactLabelReversedEmbeddedUrl}") format("truetype")` : ""
      ].filter(Boolean).join(",\n        ");
      if (preload) preload.setAttribute("href", fontUrl);
      if (impactLabelPreload) impactLabelPreload.setAttribute("href", impactLabelUrl);
      if (impactLabelReversedPreload) impactLabelReversedPreload.setAttribute("href", impactLabelReversedUrl);
      if (fontFace) {
        fontFace.textContent = `
    @font-face {
      font-family: "Hanken Grotesk";
      src:
        url("${fontUrl}") format("woff2"),
        url("${absoluteFontUrl}") format("woff2");
      font-style: normal;
      font-weight: 100 900;
      font-display: swap;
    }
    @font-face {
      font-family: "Hanken Grotesk";
      src:
        url("${italicFontUrl}") format("woff2"),
        url("${absoluteItalicFontUrl}") format("woff2");
      font-style: italic;
      font-weight: 100 900;
      font-display: swap;
    }
  `;
      }
      if (impactLabelFontFace) {
        impactLabelFontFace.textContent = `
    @font-face {
      font-family: "Impact Label";
      src:
        ${impactLabelSources};
      font-style: normal;
      font-weight: 400;
      font-display: block;
    }
  `;
      }
      if (impactLabelReversedFontFace) {
        impactLabelReversedFontFace.textContent = `
    @font-face {
      font-family: "Impact Label Reversed";
      src:
        ${impactLabelReversedSources};
      font-style: normal;
      font-weight: 400;
      font-display: block;
    }
  `;
      }
    }

