          multiSelection = [];
          render();
          await playerVisualReadyPromise;
          await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
          const slideElement = root.querySelector("[data-stage]");
          if (!slideElement) throw new Error(`Slide ${index + 1} was not available to render.`);
          const captureElement = slide.kind === "scroll"
            ? slideElement.querySelector("[data-scroll-slide]") || slideElement
            : slideElement;
          const png = await elementAsPngBlob(captureElement, SCENE_WIDTH, { fullScrollPage: slide.kind === "scroll" });
          pngEntries.push({ name: `${baseName}-slide-${String(index + 1).padStart(2, "0")}.png`, blob: png });
        }
        downloadBlob(`${baseName}-slides.zip`, await makeSlidePngZip(pngEntries));
        resultMessage = `Exported one ZIP containing ${state.tutorial.slides.length} slide PNG${state.tutorial.slides.length === 1 ? "" : "s"}.`;
      } catch (error) {
        resultMessage = `PNG export failed: ${error?.message || "unknown rendering error"}`;
      } finally {
        pngExportInProgress = false;
        state.ui = originalUi;
        render();
        showToast(resultMessage || "PNG export finished.", 8000);
      }
    }

