function scrollPageHeightUnits(slide = currentSlide()) {
      if (slide?.kind !== "scroll") return STAGE_OBJECT_MAX_POSITION;
      const width = Number(slide.media?.naturalWidth) || 0;
      const height = Number(slide.media?.naturalHeight) || 0;
      if (!width || !height) return SCROLL_DEFAULT_HEIGHT_UNITS;
      return clamp((height / width) * SCENE_ASPECT * 100, STAGE_OBJECT_MAX_POSITION, SCROLL_MAX_HEIGHT_UNITS);
    }

function stageVerticalPositionMax(slide = currentSlide()) {
      return slide?.kind === "scroll" ? scrollPageHeightUnits(slide) : STAGE_OBJECT_MAX_POSITION;
    }

function scrollViewportOffsetUnits(slide = currentSlide()) {
      if (slide?.kind !== "scroll") return 0;
      const viewport = root?.querySelector?.(`[data-scroll-slide="${CSS.escape(slide.id)}"]`);
      if (!viewport) return Number(scrollSlidePositions.get(slide.id)) || 0;
      const pageFrameHeight = viewport.clientWidth / SCENE_ASPECT;
      return viewport.scrollTop / Math.max(pageFrameHeight, 1) * 100;
    }

function fitStageObjectBounds(item, slide = currentSlide()) {
      if (!item) return item;
      const width = clamp(Number(item.w) || 1, 1, 100);
      const height = clamp(Number(item.h) || 1, 1, 100);
      const radians = Math.abs(Number(item.rotation) || 0) * Math.PI / 180;
      const cos = Math.abs(Math.cos(radians));
      const sin = Math.abs(Math.sin(radians));
      /* The authored page is always 5:3. Convert the rotated rectangle's
         projected bounds back to page percentages before clamping its center. */
      const halfWidth = Math.min(50, (width * cos + height * (3 / 5) * sin) / 2);
      const halfHeight = Math.min(50, (height * cos + width * (5 / 3) * sin) / 2);
      const x = Number(item.x);
      const y = Number(item.y);
      const horizontalBleed = item.type ? STAGE_ANNOTATION_HORIZONTAL_BLEED : 0;
      item.x = clamp(Number.isFinite(x) ? x : 50, halfWidth - horizontalBleed, 100 - halfWidth + horizontalBleed);
      const verticalMax = stageVerticalPositionMax(slide);
      item.y = clamp(Number.isFinite(y) ? y : 50, halfHeight, verticalMax - halfHeight);
      return item;
    }

function normalizeSiteColor(value, fallback) {
      const color = String(value || fallback).trim().toLowerCase();
