async function initializeProjectApp() {
      renderProjectLoading();
      try {
        const listing = await projectApi();
        projects = Array.isArray(listing.projects) ? listing.projects : [];
        projectApiError = "";
      } catch (error) {
        projectApiError = `The on-disk draft connection is unavailable: ${error?.message || "connection failed"}`;
        renderProjectChooser();
        return;
      }

      if (!PROJECT_ID) {
        renderProjectChooser();
        return;
