      const summary = projects.find((project) => project.id === PROJECT_ID);
      if (!summary) {
        projectApiError = "That draft no longer exists. Choose another draft or create a new one.";
        renderProjectChooser();
        return;
      }

      renderProjectLoading(`Opening ${summary.name}…`);
      try {
        const payload = await projectApi(`/${encodeURIComponent(PROJECT_ID)}`);
        currentProject = payload.project;
        state = clone(currentProject.state);
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
          draftStorageError = "";
        } catch (error) {
          draftStorageError = `The browser safety copy is unavailable: ${error?.message || "storage access failed"}. Disk autosave is still active.`;
        }
        draftSavePhase = "saved";
        prepareLoadedState();
        render();
        finishBuilderStartup();
      } catch (error) {
        let cached = null;
        try { cached = readJson(localStorage.getItem(STORAGE_KEY), null); }
        catch (_) { cached = null; }
        if (!cached) {
          projectApiError = `Could not open ${summary.name}: ${error?.message || "connection failed"}`;
          renderProjectChooser();
          return;
        }
        currentProject = { ...summary, state: cached };
        state = cached;
        draftStorageError = `Disk autosave is unavailable: ${error?.message || "connection failed"}. A browser safety copy is open.`;
        draftSavePhase = "error";
        prepareLoadedState();
        render();
        finishBuilderStartup();
        showToast(draftStorageError);
      }
