function linkMediaToSlide(slideId, file, pathParts, message, stateName = "linked") {
      const mediaType = mediaTypeForFile(file);
      if (!mediaType) throw new Error("Use an image, GIF, audio file, MP4, WebM, MOV, or M4V file.");
      const targetSlide = state.tutorial.slides.find((slide) => slide.id === slideId);
      if (!targetSlide) throw new Error("the destination slide is no longer available");
      targetSlide.media.url = publicMediaUrl(pathParts);
      targetSlide.media.type = mediaType;
      targetSlide.media.fit = "contain";
      targetSlide.media.x = 0;
      targetSlide.media.y = 0;
      targetSlide.media.scale = 1;
      targetSlide.media.naturalWidth = 0;
      targetSlide.media.naturalHeight = 0;
      if (targetSlide.kind !== "cover") {
        targetSlide.kind = targetSlide.kind === "scroll" && mediaType !== "video"
          ? "scroll"
          : mediaType === "video" ? "video" : targetSlide.kind === "video" ? "image" : targetSlide.kind;
        if (targetSlide.kind === "scroll") targetSlide.media.type = "image";
      }
      mediaDropState = stateName;
      mediaDropMessage = message;
      commit(message);
    }

async function selectExistingMediaFile(expectedSlideKind = "", requestedSlideId = "") {
      const targetSlideId = requestedSlideId || currentSlide().id;
      if (!mediaSiteDirectoryHandle && !await connectMediaDirectory()) return;
      if (!("showOpenFilePicker" in window)) {
        showToast("File selection needs Chrome or Edge. You can still paste a media URL.");
        return;
      }
      try {
        if (!await ensureMediaDirectoryPermission()) throw new Error("folder access was not granted");
        const pickerTypes = expectedSlideKind === "video"
          ? [{
              description: "Video",
              accept: { "video/*": [".mp4", ".webm", ".mov", ".m4v"] }
            }]
          : ["image", "scroll"].includes(expectedSlideKind)
            ? [{
                description: "Images and GIFs",
                accept: { "image/*": [".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".avif"] }
              }]
            : [{
                description: "Images, video, GIF, and audio",
                accept: {
                  "image/*": [".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".avif"],
                  "video/*": [".mp4", ".webm", ".mov", ".m4v"],
                  "audio/*": [".mp3", ".m4a", ".wav", ".ogg", ".aac"]
                }
              }];
        const [fileHandle] = await window.showOpenFilePicker({
          id: MEDIA_LIBRARY_PICKER_ID,
          startIn: mediaPickerStartDirectory(),
          multiple: false,
          excludeAcceptAllOption: Boolean(expectedSlideKind),
          types: pickerTypes
        });
        if (!fileHandle || fileHandle.kind !== "file") throw new Error("Choose one media file.");
        const pathParts = await mediaSiteDirectoryHandle.resolve(fileHandle);
        if (!pathParts?.length) {
          throw new Error("That file is not inside the connected mh_media folder. Use Copy New File only if it is not on the media website yet.");
        }
        await rememberSelectedMediaDirectory(pathParts);
        const file = await fileHandle.getFile();
        const actualType = mediaTypeForFile(file);
        if (expectedSlideKind === "video" && actualType !== "video") {
          throw new Error("Choose an MP4, WebM, MOV, or M4V video file.");
        }
        if (expectedSlideKind === "image" && !["image", "gif"].includes(actualType)) {
          throw new Error("Choose an image or GIF file.");
        }
        linkMediaToSlide(targetSlideId, file, pathParts, `Linked existing website file: ${pathParts.join("/")}`);
        showToast(`${file.name} linked and loaded. No file was copied or renamed.`);
      } catch (error) {
        if (error?.name === "AbortError") return;
        mediaDropState = "error";
        mediaDropMessage = `Could not link that file: ${error?.message || "file access failed"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

