async function copyNewMediaFile(file) {
      if (!file) return;
      const mediaType = mediaTypeForFile(file);
      if (!mediaType) {
        mediaDropState = "error";
        mediaDropMessage = "Use an image, GIF, audio file, MP4, WebM, MOV, or M4V file.";
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return;
      }
      const folder = mediaFolderSlug();
      if (!folder) {
        mediaDropState = "error";
        mediaDropMessage = "Add a short tutorial folder name before copying the new file.";
        updateMediaDropZone();
        root.querySelector("#mediaDropFolder")?.focus();
        showToast(mediaDropMessage);
        return;
      }
      if (!mediaSiteDirectoryHandle) {
        mediaDropState = "error";
        mediaDropMessage = "Connect the main mh_media folder first.";
        updateMediaDropZone();
        showToast(mediaDropMessage);
        return;
      }
      const targetSlideId = currentSlide().id;
      try {
        if (!await ensureMediaDirectoryPermission()) throw new Error("write permission was not granted");
        mediaDropState = "copying";
        mediaDropMessage = `Copying ${file.name} (${formatMediaFileSize(file.size)})…`;
        updateMediaDropZone();
        const tutorialsDirectory = await mediaSiteDirectoryHandle.getDirectoryHandle("tutorials", { create: true });
        const tutorialDirectory = await tutorialsDirectory.getDirectoryHandle(folder, { create: true });
        const filename = await availableMediaFilename(tutorialDirectory, webSafeMediaFilename(file.name));
        const fileHandle = await tutorialDirectory.getFileHandle(filename, { create: true });
        const writable = await fileHandle.createWritable();
        await writable.write(file);
        await writable.close();
        linkMediaToSlide(
          targetSlideId,
          file,
          ["tutorials", folder, filename],
          `Copied and linked tutorials/${folder}/${filename}. Publish the media website when you are ready.`,
          "copied"
        );
        showToast(`${filename} copied and linked. Publish the media website when ready.`);
      } catch (error) {
        mediaDropState = "error";
        mediaDropMessage = `Media copy failed: ${error?.message || "unknown error"}`;
        updateMediaDropZone();
        showToast(mediaDropMessage);
      }
    }

