function scheduleSave() {
      if (MODE !== "builder") return;
      clearTimeout(saveTimer);
      draftSavePhase = "saving";
      updateDraftSaveStatus();
      saveTimer = setTimeout(saveStateNow, 180);
    }

function saveStateNow() {
      if (MODE !== "builder") return false;
      clearTimeout(saveTimer);
      state.meta.updatedAt = Date.now();
      let browserBackupSaved = true;
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        lastDraftSavedAt = state.meta.updatedAt;
      } catch (error) {
        browserBackupSaved = false;
        draftStorageError = `Browser autosave failed: ${error?.message || "storage access failed"}`;
      }
      if (IS_PROJECT_APP && currentProject) {
        queueProjectDiskSave();
        return true;
      }
      if (browserBackupSaved) {
        draftStorageError = "";
        draftSavePhase = "saved";
        updateDraftSaveStatus();
        return true;
      } else {
        draftSavePhase = "error";
        updateDraftSaveStatus();
        return false;
      }
    }

function queueProjectDiskSave() {
      if (!IS_PROJECT_APP || !currentProject) return Promise.resolve(false);
      const snapshot = clone(state);
      const saveVersion = ++projectDiskSaveVersion;
      draftSavePhase = "saving";
      updateDraftSaveStatus();
      projectDiskSavePromise = projectDiskSavePromise
        .catch(() => false)
        .then(async () => {
          const payload = await projectApi(`/${encodeURIComponent(PROJECT_ID)}`, {
            method: "PUT",
            body: JSON.stringify({ state: snapshot })
          });
          currentProject = payload.project;
          const summary = {
            id: currentProject.id,
            name: currentProject.name,
            createdAt: currentProject.createdAt,
            updatedAt: currentProject.updatedAt
          };
          projects = projects.map((project) => project.id === PROJECT_ID ? summary : project);
          if (saveVersion === projectDiskSaveVersion) {
            draftStorageError = "";
            draftSavePhase = "saved";
            lastDraftSavedAt = Number(snapshot.meta?.updatedAt) || Date.now();
            updateDraftSaveStatus();
          }
          return true;
        })
        .catch((error) => {
          if (saveVersion === projectDiskSaveVersion) {
            draftStorageError = `Disk autosave failed: ${error?.message || "save failed"}. The browser safety copy is still available.`;
            draftSavePhase = "error";
            updateDraftSaveStatus();
          }
          return false;
        });
      return projectDiskSavePromise;
    }

