function recordUndoStep() {
      const nextSnapshot = historySnapshot();
      if (!committedSnapshot || nextSnapshot === committedSnapshot) return;
      undoStack.push(committedSnapshot);
      if (undoStack.length > 50) undoStack.shift();
      committedSnapshot = nextSnapshot;
    }

function undoLastChange() {
      recordUndoStep();
      const previousSnapshot = undoStack.pop();
      if (!previousSnapshot) {
        showToast("Nothing to undo.");
        return;
      }
      const previous = readJson(previousSnapshot, null);
      if (!previous) return;
      state.meta = previous.meta;
      state.tutorial = previous.tutorial;
      normalizeState();
      const slide = currentSlide();
      if (!isSlideIntroState(slide) && !slide.hotspots.some((item) => item.id === state.ui.activeHotspotId)) {
        state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
      }
      const selectedStillExists = state.ui.selectedKind === "hotspot"
        ? slide.hotspots.some((item) => item.id === state.ui.selectedId)
        : state.ui.selectedKind === "annotation"
          ? slide.annotations.some((item) => item.id === state.ui.selectedId)
          : false;
      if (!selectedStillExists) {
        state.ui.selectedKind = null;
        state.ui.selectedId = null;
      }
      state.ui.contentsOpen = false;
      state.ui.videoModalId = null;
      committedSnapshot = historySnapshot();
      scheduleSave();
      render();
      showToast("Undid last change.");
    }

function commit(message, shouldRender = true) {
