function fitRenderedTextCardsToContent({ forceIds = null } = {}) {
      let changed = false;
      root.querySelectorAll("[data-stage]").forEach((stage) => {
        const stageHeight = stage.clientHeight;
        if (!(stageHeight > 0)) return;
        stage.querySelectorAll(":scope > .annotation-text, :scope > .annotation-slide-intro, :scope > .annotation-callout").forEach((object) => {
          const annotation = currentSlide().annotations.find((item) => item.id === object.dataset.id);
          if (!annotation || !["text", "slide-intro", "callout"].includes(annotation.type)) return;
          const frame = object.querySelector(":scope > .object-frame");
          if (!frame) return;
          const shouldFit = Boolean(forceIds?.has(annotation.id));
          if (shouldFit) {
            object.classList.add("is-measuring-text-height");
            const naturalHeight = frame.getBoundingClientRect().height;
            object.classList.remove("is-measuring-text-height");
            const previousHeight = Number(annotation.h) || 1;
            const desiredHeight = clamp((naturalHeight + 2) * 100 / stageHeight, 4, 90);
            if (Math.abs(desiredHeight - previousHeight) > .05) {
              const previousTop = (Number(annotation.y) || 0) - previousHeight / 2;
              annotation.h = desiredHeight;
              annotation.y = previousTop + annotation.h / 2;
              fitStageObjectBounds(annotation);
              object.style.cssText = objectStyle(annotation);
              changed = true;
            }
          }
        });
      });
      if (changed && MODE === "builder") scheduleSave();
      return changed;
    }

