function metaSelect(key, label, value, options) {
	      return `<label>${escapeHtml(label)}<select data-meta="${key}">${options.map(([optionValue, optionLabel]) => `<option value="${escapeHtml(optionValue)}" ${optionValue === value ? "selected" : ""}>${escapeHtml(optionLabel)}</option>`).join("")}</select></label>`;
