function youtubeVideoInfo(value) {
      const original = String(value || "").trim();
      if (!original) return null;
      try {
        const url = new URL(original);
        const host = url.hostname.toLowerCase().replace(/^www\./, "");
        const isYoutube = host === "youtube.com"
          || host.endsWith(".youtube.com")
          || host === "youtube-nocookie.com"
          || host.endsWith(".youtube-nocookie.com");
        const isShareHost = host === "youtu.be" || host.endsWith(".youtu.be");
        if (!isYoutube && !isShareHost) return null;
        const parts = url.pathname.split("/").filter(Boolean);
        const isShort = isYoutube && parts[0] === "shorts";
        let id = "";
        if (isShareHost) id = parts[0] || "";
        else if (isShort) id = parts[1] || "";
        else if (["embed", "live", "v"].includes(parts[0])) id = parts[1] || "";
        else id = url.searchParams.get("v") || "";
        if (!/^[a-zA-Z0-9_-]{6,20}$/.test(id)) return null;
        return {
          id,
          isShort,
          embedUrl: `https://www.youtube.com/embed/${id}?autoplay=1&playsinline=1&rel=0`
        };
      } catch (_) {
        return null;
      }
    }

