        root.querySelector(`[data-object][data-id="${CSS.escape(item.id)}"]`)?.style.setProperty("--object-shadow", item.imageShadow ? `drop-shadow(0 ${item.shadowHeight}px ${Math.max(1,item.shadowHeight*.45)}px rgba(0,0,0,.28))` : "none");
