function normalizeMainMediaInput(target) {
      let value = target.value.trim();
      const base = mediaBase();
      const appended = value.slice(base.length);
      if (value.startsWith(base) && /^https?:\/\//i.test(appended)) {
        value = appended;
        target.value = value;
      }
      return value;
    }

function onFocusIn(event) {
      const target = event.target;
      positionShapeNavigation(target.closest?.("[data-shape-menu]"));
      if (target.id === "mainMediaUrl" && !currentSlide().media.url && target.value === mediaBase()) {
        target.select();
      }
    }

function syncLiveEditableBeforeRender(target = document.activeElement) {
      const editable = target?.isContentEditable
        ? target
        : target?.closest?.('[contenteditable="true"]');
      if (!editable || !root.contains(editable)) return false;
      editable.dispatchEvent(new Event("input", { bubbles: true }));
      return true;
    }

function onFocusOut(event) {
      if (event.target.isContentEditable) {
        syncLiveEditableBeforeRender(event.target);
        commit("", false);
      }
    }

function refreshMainMediaLayer() {
      if (currentSlide()?.kind === "scroll") {
        const stageWrap = root.querySelector(".stage-wrap");
        if (stageWrap) stageWrap.outerHTML = renderStage(currentSlide());
        syncRuntimeMedia();
        return;
      }
      const layer = root.querySelector(".media-layer");
      if (!layer) return;
      layer.outerHTML = renderMainMedia(currentSlide());
      syncRuntimeMedia();
    }

function selectObject(kind, id, additive = false) {
      if (MODE !== "builder") return;
      if (kind !== "annotation" || id !== imageCropEditId) imageCropEditId = "";
      syncObjectSelection();
      const key = selectionKey(kind, id);
      const clickedEntry = selectionEntry(key);
      if (!clickedEntry) return;
      const groupedEntries = kind === "annotation" ? objectGroupEntriesForItem(clickedEntry.item) : [];
      const candidateKeys = groupedEntries.length > 1 ? groupedEntries.map(({ key: groupKey }) => groupKey) : [key];
      if (kind === "hotspot" && state.ui.activeHotspotId !== id) stopAudio();
      if (additive) {
        if (candidateKeys.every((candidateKey) => multiSelection.includes(candidateKey))) {
          multiSelection = multiSelection.filter((entry) => !candidateKeys.includes(entry));
        } else {
          multiSelection.push(...candidateKeys.filter((candidateKey) => !multiSelection.includes(candidateKey)));
        }
      } else if (!multiSelection.includes(key)) {
        multiSelection = candidateKeys;
      }
      const primary = additive && !multiSelection.includes(key)
        ? selectionEntry(multiSelection[multiSelection.length - 1])
        : selectionEntry(key);
      state.ui.selectedKind = primary?.kind || null;
      state.ui.selectedId = primary?.id || null;
      if (kind === "hotspot" && multiSelection.includes(key)) state.ui.activeHotspotId = id;
      render();
    }

function onPointerDown(event) {
