      }
      syncLiveEditableBeforeRender();
      const popupResizeHandle = event.target.closest("[data-popup-resize-handle]");
      if (popupResizeHandle) {
        const popup = popupResizeHandle.closest(".slide-sidebar.is-demo-popup");
        const body = popup?.closest(".tutorial-body.is-demo-centered-slide");
        const hotspot = currentSlide().hotspots.find((item) => item.id === popupResizeHandle.dataset.id);
        if (!popup || !body || !hotspot) return;
        const rect = body.getBoundingClientRect();
        const popupRect = popup.getBoundingClientRect();
        const left = clamp((popupRect.left - rect.left) / Math.max(rect.width, 1) * 100, 0, 100);
        const right = clamp((popupRect.right - rect.left) / Math.max(rect.width, 1) * 100, 0, 100);
        const top = clamp((popupRect.top - rect.top) / Math.max(rect.height, 1) * 100, 0, 100);
        const bottom = clamp((popupRect.bottom - rect.top) / Math.max(rect.height, 1) * 100, 0, 100);
