          original: { left, right, top, bottom },
          minW: clamp(180 / Math.max(rect.width, 1) * 100, 12, 50),
          minH: clamp(120 / Math.max(rect.height, 1) * 100, 10, 50)
        };
        hotspot.popupX = (left + right) / 2;
        hotspot.popupY = (top + bottom) / 2;
        hotspot.popupW = Math.max(popupDrag.minW, right - left);
        hotspot.popupH = Math.max(popupDrag.minH, bottom - top);
        popup.classList.remove("demo-popup-left", "demo-popup-right", "demo-popup-top", "demo-popup-bottom");
        popup.classList.add("is-custom-position", "is-custom-size");
