      const dy = (event.clientY - drag.startY) / drag.rect.height * 100;
      const verticalMax = stageVerticalPositionMax(currentSlide());
      const pointerDistance = Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY);
      if (drag.deferredBodyDrag && !drag.moved && pointerDistance < 5) return;
      if (pointerDistance >= 5 || Math.abs(dx) > .2 || Math.abs(dy) > .2) drag.moved = true;
