function placeCaretInMixedBodyLine(line, offset = 0) {
      const selection = window.getSelection();
      if (!selection || !line) return;
      line.normalize();
      const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
      let textNode = walker.nextNode(), remaining = Math.max(0, offset);
      while (textNode && remaining > textNode.length) {
        const next = walker.nextNode();
        if (!next) { remaining = textNode.length; break; }
        remaining -= textNode.length;
        textNode = next;
      }
      const range = document.createRange();
      if (textNode) {
        range.setStart(textNode, clamp(remaining, 0, textNode.textContent.length));
      } else {
        range.setStart(line, 0);
      }
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);
    }

function insertMixedBodyLine(event, editor) {
      event.preventDefault();
      const selection = window.getSelection();
      const range = selection?.rangeCount ? selection.getRangeAt(0) : null;
      const rangeElement = range?.startContainer?.nodeType === 1
        ? range.startContainer
        : range?.startContainer?.parentElement;
      let line = rangeElement?.closest?.(".mixed-body-line");
      if (!line || line.parentElement !== editor) line = editor.querySelector(".mixed-body-line:last-child");
      if (!line) {
        line = document.createElement("div");
        line.className = "mixed-body-line";
        line.dataset.listKind = "plain";
        line.dataset.pipe = "false";
        editor.append(line);
      }

      if (range && !range.collapsed && line.contains(range.startContainer) && line.contains(range.endContainer)) {
        range.deleteContents();
      }

      let offset = line.innerText.replace(/\r/g, "").replace(/\n+$/, "").length;
      if (range && line.contains(range.startContainer)) {
        const beforeCaret = document.createRange();
        beforeCaret.selectNodeContents(line);
        beforeCaret.setEnd(range.startContainer, range.startOffset);
        offset = beforeCaret.toString().length;
      }

      const text = line.innerText.replace(/\r/g, "").replace(/\n+$/, "");
      const currentKind = lineListKind(line);
      if (currentKind !== "plain" && !text) {
        setLineListKind(line, "plain");
        placeCaretInMixedBodyLine(line);
        editor.dispatchEvent(new Event("input", { bubbles: true }));
        updateBodyListToggleState(editor, [line]);
        return;
      }

      const nextLine = document.createElement("div");
      nextLine.className = "mixed-body-line";
      setLineListKind(nextLine, currentKind);
      line.removeAttribute("data-placeholder");
      const tail = document.createRange();
      tail.selectNodeContents(line);
      if (range && line.contains(range.startContainer)) tail.setStart(range.startContainer, range.startOffset);
      else tail.collapse(false);
      nextLine.append(tail.extractContents());
      line.after(nextLine);

      placeCaretInMixedBodyLine(nextLine);
      editor.dispatchEvent(new Event("input", { bubbles: true }));
      lastMixedBodySelection = { editor, lines: [nextLine] };
      updateBodyListToggleState(editor, [nextLine]);
    }

