function revealScrollSlideObject(element) {
      const viewport = element?.closest?.("[data-scroll-slide]");
      if (!viewport) return;
      const viewportBounds = viewport.getBoundingClientRect();
      const objectBounds = element.getBoundingClientRect();
      const padding = Math.min(48, viewportBounds.height * .12);
      const above = objectBounds.top < viewportBounds.top + padding;
      const below = objectBounds.bottom > viewportBounds.bottom - padding;
      if (!above && !below) return;
      const top = viewport.scrollTop + objectBounds.top - viewportBounds.top
        - (viewportBounds.height - objectBounds.height) / 2;
      viewport.scrollTo({
        top: Math.max(0, top),
        behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth"
