function arrangeSelected(mode) {
      const arrangement = arrangementEntries();
      const entries = arrangement.entries;
      const verticalMax = stageVerticalPositionMax(currentSlide());
      const distribution = mode === "horizontal" || mode === "vertical";
      const minimum = distribution ? 3 : 2;
      if (entries.length < minimum) {
        if (entries.length === 1 && !distribution) {
          const item = entries[0].item;
          const pageHeight = verticalMax;
          if (mode === "left") item.x = item.w / 2;
          if (mode === "center") item.x = 50;
          if (mode === "right") item.x = 100 - item.w / 2;
          if (mode === "top") item.y = item.h / 2;
          if (mode === "middle") item.y = pageHeight / 2;
          if (mode === "bottom") item.y = pageHeight - item.h / 2;
          commit("Aligned selected item to the slide.");
          return;
        }
        showToast(distribution ? "Select at least three unlocked items." : "Select at least two unlocked items.");
        return;
      }
      if (mode === "left") {
        const left = Math.min(...entries.map(({ item }) => item.x - item.w / 2));
        entries.forEach(({ item }) => {
          item.x = clamp(left + item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "center") {
        const left = Math.min(...entries.map(({ item }) => item.x - item.w / 2));
        const right = Math.max(...entries.map(({ item }) => item.x + item.w / 2));
        const center = (left + right) / 2;
        entries.forEach(({ item }) => {
          item.x = clamp(center, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "right") {
        const right = Math.max(...entries.map(({ item }) => item.x + item.w / 2));
        entries.forEach(({ item }) => {
          item.x = clamp(right - item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
        });
      } else if (mode === "top") {
        const top = Math.min(...entries.map(({ item }) => item.y - item.h / 2));
        entries.forEach(({ item }) => {
          item.y = clamp(top + item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "middle") {
        const top = Math.min(...entries.map(({ item }) => item.y - item.h / 2));
        const bottom = Math.max(...entries.map(({ item }) => item.y + item.h / 2));
        const middle = (top + bottom) / 2;
        entries.forEach(({ item }) => {
          item.y = clamp(middle, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "bottom") {
        const bottom = Math.max(...entries.map(({ item }) => item.y + item.h / 2));
        entries.forEach(({ item }) => {
          item.y = clamp(bottom - item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
        });
      } else if (mode === "horizontal") {
        const ordered = entries.slice().sort((a, b) => a.item.x - b.item.x);
        const start = ordered[0].item.x - ordered[0].item.w / 2;
        const last = ordered[ordered.length - 1].item;
        const end = last.x + last.w / 2;
        const totalWidth = ordered.reduce((sum, { item }) => sum + item.w, 0);
        const gap = (end - start - totalWidth) / (ordered.length - 1);
        let cursor = start;
        ordered.forEach(({ item }) => {
          item.x = clamp(cursor + item.w / 2, STAGE_OBJECT_MIN_POSITION, STAGE_OBJECT_MAX_POSITION);
          cursor += item.w + gap;
        });
      } else if (mode === "vertical") {
        const ordered = entries.slice().sort((a, b) => a.item.y - b.item.y);
        const start = ordered[0].item.y - ordered[0].item.h / 2;
        const last = ordered[ordered.length - 1].item;
        const end = last.y + last.h / 2;
        const totalHeight = ordered.reduce((sum, { item }) => sum + item.h, 0);
        const gap = (end - start - totalHeight) / (ordered.length - 1);
        let cursor = start;
        ordered.forEach(({ item }) => {
          item.y = clamp(cursor + item.h / 2, STAGE_OBJECT_MIN_POSITION, verticalMax);
          cursor += item.h + gap;
