        center: `Aligned ${target} to center.`,
        top: `Aligned ${target} to top.`,
        middle: `Aligned ${target} to middle.`,
        bottom: `Aligned ${target} to bottom.`,
        horizontal: `Distributed ${target} horizontally.`,
        vertical: `Distributed ${target} vertically.`
      };
      commit(messages[mode]);
    }

