        });
        state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
      } else {
        const deletedAnnotation = slide.annotations.find((item) => item.id === state.ui.selectedId);
        if (deletedAnnotation?.type === "clip-frame") {
          const released = clipFrameMembers(deletedAnnotation, slide);
          released.forEach((item) => { item.clipFrameId = ""; });
          message = `Deleted the clip frame and kept ${released.length} ${released.length === 1 ? "item" : "items"}.`;
        }
        slide.annotations = slide.annotations.filter((item) => item.id !== state.ui.selectedId);
        if (deletedAnnotation?.objectGroupId) {
          const remainingGroup = slide.annotations.filter((item) => item.objectGroupId === deletedAnnotation.objectGroupId);
          if (remainingGroup.length < 2) remainingGroup.forEach((item) => { item.objectGroupId = ""; });
        }
        if (deletedAnnotation?.type === "slide-intro") {
          state.ui.activeHotspotId = slide.hotspots[0]?.id || null;
        }
      }
      state.ui.selectedId = null;
      state.ui.selectedKind = null;
      commit(message);
