        if (!video) return;
        video.currentTime = clamp(Number(value), 0, Number.isFinite(video.duration) ? video.duration : 0);
        updateDemoPlaybackUi();
        return;
      }
      const percent = clamp(Number(value), 0, 100);
      const count = Math.max(1, state.tutorial.slides.length);
      const position = percent >= 100 ? count - Number.EPSILON : (percent / 100) * count;
      const index = Math.min(count - 1, Math.floor(position));
      const fraction = clamp(position - index, 0, .999);
      const shouldResume = demoSeekResumeAfter;
      demoSeekPreview = null;
