function createTutorialAudio(url, id) {
      const audio = new Audio();
      audio.preload = "metadata";
      audio.crossOrigin = "anonymous";
      audio.src = normalizeHostedAnnotationUrl("audio", url);
      const updateTimeline = () => {
        if (window.__tutorialAudio === audio && activeAudio === id) updateAudioTimeline(id);
      };
      audio.addEventListener("loadedmetadata", updateTimeline);
      audio.addEventListener("durationchange", updateTimeline);
      audio.addEventListener("timeupdate", updateTimeline);
      audio.addEventListener("ended", () => {
        if (window.__tutorialAudio !== audio || activeAudio !== id) return;
        activeAudio = null;
        audioPlaying = false;
        render();
      });
      return audio;
    }

