async function inlinePngExportImages(source, cloneRoot) {
      const sourceImages = [...source.querySelectorAll("img")];
      const cloneImages = [...cloneRoot.querySelectorAll("img")];
      await Promise.all(cloneImages.map(async (image, index) => {
        const sourceImage = sourceImages[index];
        const src = sourceImage?.currentSrc || sourceImage?.src || image.src;
        if (!src || src.startsWith("data:")) return;
        try {
          const response = await fetch(src, { mode: "cors", credentials: "omit", signal: AbortSignal.timeout(5000) });
          if (!response.ok) throw new Error(`image request returned ${response.status}`);
          image.src = await blobAsDataUrl(await response.blob());
        } catch (_) {
          image.removeAttribute("src");
          image.alt = image.alt || "Image unavailable in PNG export";
        }
      }));

      const sourceVideos = [...source.querySelectorAll("video")];
      const cloneVideos = [...cloneRoot.querySelectorAll("video")];
      cloneVideos.forEach((video, index) => {
        const sourceVideo = sourceVideos[index];
        const replacement = document.createElement("div");
        replacement.className = video.className;
        replacement.setAttribute("aria-label", video.getAttribute("aria-label") || "Video slide");
        replacement.style.cssText = "width:100%;height:100%;background:#d7d7d7;";
        if (sourceVideo?.videoWidth && sourceVideo?.videoHeight) {
          try {
            const canvas = document.createElement("canvas");
            canvas.width = sourceVideo.videoWidth;
            canvas.height = sourceVideo.videoHeight;
            canvas.getContext("2d").drawImage(sourceVideo, 0, 0);
            const image = document.createElement("img");
            image.src = canvas.toDataURL("image/png");
            image.alt = video.getAttribute("aria-label") || "Video frame";
            image.style.cssText = "width:100%;height:100%;object-fit:contain;";
            video.replaceWith(image);
            return;
          } catch (_) {}
        }
        video.replaceWith(replacement);
      });
    }

