async function elementAsPngBlob(element, outputWidth = 1500, { fullScrollPage = false } = {}) {
      if (typeof window.html2canvas !== "function") {
        throw new Error("The local PNG renderer did not load.");
      }
      const rect = element.getBoundingClientRect();
      const scrollViewport = fullScrollPage ? element.querySelector("[data-scroll-slide]") : null;
      const scrollContent = scrollViewport?.querySelector(".scroll-slide-content");
      const captureHeight = fullScrollPage
        ? Math.max(rect.height, scrollViewport?.scrollHeight || 0, scrollContent?.scrollHeight || 0)
        : rect.height;
      const scale = outputWidth / Math.max(1, rect.width);
      const captureId = uid("png-capture");
      element.dataset.pngCaptureId = captureId;
      let canvas;
      try {
        canvas = await window.html2canvas(element, {
          backgroundColor: "#ffffff",
          scale,
          width: rect.width,
          height: captureHeight,
          windowHeight: Math.max(window.innerHeight, captureHeight),
          useCORS: true,
          allowTaint: false,
          logging: false,
          imageTimeout: 8000,
          onclone: (clonedDocument) => {
            const cloneTarget = clonedDocument.querySelector(`[data-png-capture-id="${CSS.escape(captureId)}"]`);
            const cloneRoot = cloneTarget?.closest(".tutorial-shell") || clonedDocument.querySelector(".tutorial-shell");
            cloneRoot?.querySelector(".reader-nav")?.remove();
            cloneRoot?.querySelectorAll("[contenteditable]").forEach((node) => node.removeAttribute("contenteditable"));
            cloneRoot?.querySelectorAll(".resize-handle,.markup-point-handle,.rotate-handle,.flip-handle,.move-handle,.demo-popup-drag-handle,.demo-popup-resize-handle,.scroll-slide-caret").forEach((node) => node.remove());
            if (fullScrollPage && cloneTarget) {
              cloneTarget.style.height = `${captureHeight}px`;
              cloneTarget.style.maxHeight = "none";
              cloneTarget.style.aspectRatio = "auto";
              cloneTarget.style.overflow = "visible";
              const cloneViewport = cloneTarget.matches("[data-scroll-slide]")
                ? cloneTarget
                : cloneTarget.querySelector("[data-scroll-slide]");
              const cloneContent = cloneViewport?.querySelector(".scroll-slide-content");
              if (cloneViewport) {
                cloneViewport.scrollTop = 0;
                cloneViewport.style.position = "relative";
                cloneViewport.style.inset = "auto";
                cloneViewport.style.width = "100%";
                cloneViewport.style.height = `${captureHeight}px`;
                cloneViewport.style.overflow = "visible";
              }
              if (cloneContent) {
                cloneContent.style.minHeight = "0";
                cloneContent.style.height = `${captureHeight}px`;
              }
            }
          }
        });
      } finally {
        delete element.dataset.pngCaptureId;
      }
      return await new Promise((resolve, reject) => {
        canvas.toBlob(
          (blob) => blob ? resolve(blob) : reject(new Error("The browser could not create the PNG file.")),
          "image/png"
        );
      });
    }

