function zipHeader(length) {
      const bytes = new Uint8Array(length);
      return { bytes, view: new DataView(bytes.buffer) };
    }

async function makeSlidePngZip(entries) {
      const encoder = new TextEncoder();
      const localParts = [];
      const centralParts = [];
      let offset = 0;
      const now = new Date();
      const dosTime = ((now.getHours() & 31) << 11) | ((now.getMinutes() & 63) << 5) | ((Math.floor(now.getSeconds() / 2)) & 31);
      const dosDate = (((Math.max(1980, now.getFullYear()) - 1980) & 127) << 9) | (((now.getMonth() + 1) & 15) << 5) | (now.getDate() & 31);
      for (const entry of entries) {
        const name = encoder.encode(entry.name);
        const data = new Uint8Array(await entry.blob.arrayBuffer());
        const crc = zipCrc32(data);
        const local = zipHeader(30);
        local.view.setUint32(0, 0x04034b50, true);
        local.view.setUint16(4, 20, true);
        local.view.setUint16(6, 0x0800, true);
        local.view.setUint16(8, 0, true);
        local.view.setUint16(10, dosTime, true);
        local.view.setUint16(12, dosDate, true);
        local.view.setUint32(14, crc, true);
        local.view.setUint32(18, data.length, true);
        local.view.setUint32(22, data.length, true);
        local.view.setUint16(26, name.length, true);
        local.view.setUint16(28, 0, true);
        localParts.push(local.bytes, name, data);

        const central = zipHeader(46);
        central.view.setUint32(0, 0x02014b50, true);
        central.view.setUint16(4, 20, true);
        central.view.setUint16(6, 20, true);
        central.view.setUint16(8, 0x0800, true);
        central.view.setUint16(10, 0, true);
        central.view.setUint16(12, dosTime, true);
        central.view.setUint16(14, dosDate, true);
        central.view.setUint32(16, crc, true);
        central.view.setUint32(20, data.length, true);
        central.view.setUint32(24, data.length, true);
        central.view.setUint16(28, name.length, true);
        central.view.setUint16(30, 0, true);
        central.view.setUint16(32, 0, true);
        central.view.setUint16(34, 0, true);
        central.view.setUint16(36, 0, true);
        central.view.setUint32(38, 0, true);
        central.view.setUint32(42, offset, true);
        centralParts.push(central.bytes, name);
        offset += local.bytes.length + name.length + data.length;
      }
      const centralSize = centralParts.reduce((sum, part) => sum + part.length, 0);
      const end = zipHeader(22);
      end.view.setUint32(0, 0x06054b50, true);
      end.view.setUint16(4, 0, true);
      end.view.setUint16(6, 0, true);
      end.view.setUint16(8, entries.length, true);
      end.view.setUint16(10, entries.length, true);
      end.view.setUint32(12, centralSize, true);
      end.view.setUint32(16, offset, true);
      end.view.setUint16(20, 0, true);
      return new Blob([...localParts, ...centralParts, end.bytes], { type: "application/zip" });
    }

async function exportPng() {
      if (pngExportInProgress) {
        showToast("The slide PNG ZIP is already being prepared.");
        return;
      }
      pngExportInProgress = true;
      showToast(`Preparing ${state.tutorial.slides.length} slide PNG${state.tutorial.slides.length === 1 ? "" : "s"}…`);
      const originalUi = clone(state.ui);
      const baseName = slugify(state.meta.tutorialSlug || state.tutorial.title) || "demo";
      const pngEntries = [];
      let resultMessage = "";
      try {
        await waitForExportFonts();
        if (IS_PROJECT_APP) await saveProjectToDiskNow();
        for (let index = 0; index < state.tutorial.slides.length; index += 1) {
          const slide = state.tutorial.slides[index];
          state.ui.slideIndex = index;
          state.ui.activeHotspotId = slideIntroCard(slide) ? null : slide.hotspots[0]?.id || null;
          state.ui.selectedKind = null;
          state.ui.selectedId = null;
          state.ui.contentsOpen = false;
          state.ui.videoModalId = null;
          multiSelection = [];
          render();
          await playerVisualReadyPromise;
          await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
          const slideElement = root.querySelector("[data-stage]");
          if (!slideElement) throw new Error(`Slide ${index + 1} was not available to render.`);
          const captureElement = slide.kind === "scroll"
            ? slideElement.querySelector("[data-scroll-slide]") || slideElement
            : slideElement;
          const png = await elementAsPngBlob(captureElement, SCENE_WIDTH, { fullScrollPage: slide.kind === "scroll" });
          pngEntries.push({ name: `${baseName}-slide-${String(index + 1).padStart(2, "0")}.png`, blob: png });
        }
        downloadBlob(`${baseName}-slides.zip`, await makeSlidePngZip(pngEntries));
        resultMessage = `Exported one ZIP containing ${state.tutorial.slides.length} slide PNG${state.tutorial.slides.length === 1 ? "" : "s"}.`;
      } catch (error) {
        resultMessage = `PNG export failed: ${error?.message || "unknown rendering error"}`;
      } finally {
        pngExportInProgress = false;
        state.ui = originalUi;
        render();
        showToast(resultMessage || "PNG export finished.", 8000);
      }
    }

async function copyPublicUrl() {
      const value = publicUrl();
      if (!value) {
        showToast("Add a learning section and tutorial slug first.");
        return;
      }
      try {
        await navigator.clipboard.writeText(value);
      } catch (_) {
        const input = document.createElement("textarea");
        input.value = value;
        input.setAttribute("readonly", "");
        input.style.position = "fixed";
        input.style.opacity = "0";
        document.body.append(input);
        input.select();
        document.execCommand("copy");
        input.remove();
      }
      showToast("Copied the public social share URL.");
    }

function download(filename, contents, type) {
      const blob = new Blob([contents], { type: `${type};charset=utf-8` });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = filename;
      document.body.append(link);
      link.click();
      link.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

